14	/**
15	 * A model loader for handling Android resource files. Model must be an Android resource id in the
16	 * package of the given context.
17	 *
18	 * <p>This class should always be less preferred than {@link DirectResourceLoader} because {@link
19	 * DirectResourceLoader} is more efficient for {@code Drawables} owned by this package. This class
20	 * only handles passing through {@link Uri}s to {@link
21	 * com.bumptech.glide.load.resource.drawable.ResourceDrawableDecoder} and {@link
22	 * com.bumptech.glide.load.resource.bitmap.ResourceBitmapDecoder}. Those classes can handle assets
23	 * from other applications, but are not as efficient as {@link DirectResourceLoader} for assets
24	 * owned by this package.
25	 *
26	 * @param <Data> The type of data that will be loaded for the given android resource.
27	 */
28	public class ResourceLoader<Data> implements ModelLoader<Integer, Data> {
29	  private static final String TAG = "ResourceLoader";
30	  private final ModelLoader<Uri, Data> uriLoader;
31	  private final Resources resources;
32	
33	  // Public API.
34	  @SuppressWarnings("WeakerAccess")
35	  public ResourceLoader(Resources resources, ModelLoader<Uri, Data> uriLoader) {
36	    this.resources = resources;
37	    this.uriLoader = uriLoader;
38	  }
39	
40	  @Override
41	  public LoadData<Data> buildLoadData(
42	      @NonNull Integer model, int width, int height, @NonNull Options options) {
43	    Uri uri = getResourceUri(model);
44	    return uri == null ? null : uriLoader.buildLoadData(uri, width, height, options);
45	  }
46	
47	  @Nullable
48	  private Uri getResourceUri(Integer model) {
49	    try {
50	      return Uri.parse(
51	          ContentResolver.SCHEME_ANDROID_RESOURCE
52	              + "://"
53	              + resources.getResourcePackageName(model)
54	              + '/'
55	              + model);
56	    } catch (Resources.NotFoundException e) {
57	      if (Log.isLoggable(TAG, Log.WARN)) {
58	        Log.w(TAG, "Received invalid resource id: " + model, e);
59	      }
60	      return null;
61	    }
62	  }
63	
64	  @Override
65	  public boolean handles(@NonNull Integer model) {
66	    // TODO: check that this is in fact a resource id.
67	    return true;
68	  }
69	
70	  /** Factory for loading {@link InputStream}s from Android resource ids. */
71	  public static class StreamFactory implements ModelLoaderFactory<Integer, InputStream> {
72	
73	    private final Resources resources;
74	
75	    public StreamFactory(Resources resources) {
76	      this.resources = resources;
77	    }
78	
79	    @NonNull
80	    @Override
81	    public ModelLoader<Integer, InputStream> build(MultiModelLoaderFactory multiFactory) {
82	      return new ResourceLoader<>(resources, multiFactory.build(Uri.class, InputStream.class));
83	    }
84	
85	    @Override
86	    public void teardown() {
87	      // Do nothing.
88	    }
89	  }
90	
91	  /**
92	   * Factory for loading {@link ParcelFileDescriptor}s from Android resource ids.
93	   *
94	   * @deprecated This class is unused by Glide. {@link AssetFileDescriptorFactory} should be
95	   *     preferred because it's not possible to reliably load a simple {@link
96	   *     java.io.FileDescriptor} for resources.
97	   */
98	  @Deprecated
99	  public static class FileDescriptorFactory
100	      implements ModelLoaderFactory<Integer, ParcelFileDescriptor> {
101	
102	    private final Resources resources;
103	
104	    public FileDescriptorFactory(Resources resources) {
105	      this.resources = resources;
106	    }
107	
108	    @NonNull
109	    @Override
110	    public ModelLoader<Integer, ParcelFileDescriptor> build(MultiModelLoaderFactory multiFactory) {
111	      return new ResourceLoader<>(
112	          resources, multiFactory.build(Uri.class, ParcelFileDescriptor.class));
113	    }
114	
115	    @Override
116	    public void teardown() {
117	      // Do nothing.
118	    }
119	  }
120	
121	  /** Loads {@link AssetFileDescriptor}s from resource ids. */
122	  public static final class AssetFileDescriptorFactory
123	      implements ModelLoaderFactory<Integer, AssetFileDescriptor> {
124	
125	    private final Resources resources;
126	
127	    public AssetFileDescriptorFactory(Resources resources) {
128	      this.resources = resources;
129	    }
130	
131	    @Override
132	    public ModelLoader<Integer, AssetFileDescriptor> build(MultiModelLoaderFactory multiFactory) {
133	      return new ResourceLoader<>(
134	          resources, multiFactory.build(Uri.class, AssetFileDescriptor.class));
135	    }
136	
137	    @Override
138	    public void teardown() {
139	      // Do nothing.
140	    }
141	  }
142	
143	  /** Factory for loading resource {@link Uri}s from Android resource ids. */
144	  public static class UriFactory implements ModelLoaderFactory<Integer, Uri> {
145	
146	    private final Resources resources;
147	
148	    public UriFactory(Resources resources) {
149	      this.resources = resources;
150	    }
151	
152	    @NonNull
153	    @Override
154	    public ModelLoader<Integer, Uri> build(MultiModelLoaderFactory multiFactory) {
155	      return new ResourceLoader<>(resources, UnitModelLoader.<Uri>getInstance());
156	    }
157	
158	    @Override
159	    public void teardown() {
160	      // Do nothing.
161	    }
162	  }
163	}
