1	package com.bumptech.glide.load.model;
2	
3	import android.os.ParcelFileDescriptor;
4	import android.util.Log;
5	import androidx.annotation.NonNull;
6	import com.bumptech.glide.Priority;
7	import com.bumptech.glide.load.DataSource;
8	import com.bumptech.glide.load.Options;
9	import com.bumptech.glide.load.data.DataFetcher;
10	import com.bumptech.glide.signature.ObjectKey;
11	import java.io.File;
12	import java.io.FileInputStream;
13	import java.io.FileNotFoundException;
14	import java.io.IOException;
15	import java.io.InputStream;
16	
17	/**
18	 * A simple model loader for loading data from {@link File}s.
19	 *
20	 * @param <Data> The type of data loaded from the given {@link java.io.File} ({@link
21	 *     java.io.InputStream} or {@link java.io.FileDescriptor} etc).
22	 */
23	public class FileLoader<Data> implements ModelLoader<File, Data> {
24	  private static final String TAG = "FileLoader";
25	
26	  private final FileOpener<Data> fileOpener;
27	
28	  // Public API.
29	  @SuppressWarnings("WeakerAccess")
30	  public FileLoader(FileOpener<Data> fileOpener) {
31	    this.fileOpener = fileOpener;
32	  }
33	
34	  @Override
35	  public LoadData<Data> buildLoadData(
36	      @NonNull File model, int width, int height, @NonNull Options options) {
37	    return new LoadData<>(new ObjectKey(model), new FileFetcher<>(model, fileOpener));
38	  }
39	
40	  @Override
41	  public boolean handles(@NonNull File model) {
42	    return true;
43	  }
44	
45	  /**
46	   * Allows opening a specific type of data from a {@link java.io.File}.
47	   *
48	   * @param <Data> The type of data that can be opened.
49	   */
50	  public interface FileOpener<Data> {
51	    Data open(File file) throws FileNotFoundException;
52	
53	    void close(Data data) throws IOException;
54	
55	    Class<Data> getDataClass();
56	  }
57	
58	  private static final class FileFetcher<Data> implements DataFetcher<Data> {
59	    private final File file;
60	    private final FileOpener<Data> opener;
61	    private Data data;
62	
63	    FileFetcher(File file, FileOpener<Data> opener) {
64	      this.file = file;
65	      this.opener = opener;
66	    }
67	
68	    @Override
69	    public void loadData(@NonNull Priority priority, @NonNull DataCallback<? super Data> callback) {
70	      try {
71	        data = opener.open(file);
72	        callback.onDataReady(data);
73	      } catch (FileNotFoundException e) {
74	        if (Log.isLoggable(TAG, Log.DEBUG)) {
75	          Log.d(TAG, "Failed to open file", e);
76	        }
77	        callback.onLoadFailed(e);
78	      }
79	    }
80	
81	    @Override
82	    public void cleanup() {
83	      if (data != null) {
84	        try {
85	          opener.close(data);
86	        } catch (IOException e) {
87	          // Ignored.
88	        }
89	      }
90	    }
91	
92	    @Override
93	    public void cancel() {
94	      // Do nothing.
95	    }
96	
97	    @NonNull
98	    @Override
99	    public Class<Data> getDataClass() {
100	      return opener.getDataClass();
101	    }
102	
103	    @NonNull
104	    @Override
105	    public DataSource getDataSource() {
106	      return DataSource.LOCAL;
107	    }
108	  }
109	
110	  /**
111	   * Base factory for loading data from {@link java.io.File files}.
112	   *
113	   * @param <Data> The type of data that will be loaded for a given {@link java.io.File}.
114	   */
115	  public static class Factory<Data> implements ModelLoaderFactory<File, Data> {
116	    private final FileOpener<Data> opener;
117	
118	    public Factory(FileOpener<Data> opener) {
119	      this.opener = opener;
120	    }
121	
122	    @NonNull
123	    @Override
124	    public final ModelLoader<File, Data> build(@NonNull MultiModelLoaderFactory multiFactory) {
125	      return new FileLoader<>(opener);
126	    }
127	
128	    @Override
129	    public final void teardown() {
130	      // Do nothing.
131	    }
132	  }
133	
134	  /** Factory for loading {@link InputStream}s from {@link File}s. */
135	  public static class StreamFactory extends Factory<InputStream> {
136	    public StreamFactory() {
137	      super(
138	          new FileOpener<InputStream>() {
139	            @Override
140	            public InputStream open(File file) throws FileNotFoundException {
141	              return new FileInputStream(file);
142	            }
143	
144	            @Override
145	            public void close(InputStream inputStream) throws IOException {
146	              inputStream.close();
147	            }
148	
149	            @Override
150	            public Class<InputStream> getDataClass() {
151	              return InputStream.class;
152	            }
153	          });
154	    }
155	  }
156	
157	  /** Factory for loading {@link ParcelFileDescriptor}s from {@link File}s. */
158	  public static class FileDescriptorFactory extends Factory<ParcelFileDescriptor> {
159	
160	    public FileDescriptorFactory() {
161	      super(
162	          new FileOpener<ParcelFileDescriptor>() {
163	            @Override
164	            public ParcelFileDescriptor open(File file) throws FileNotFoundException {
165	              return ParcelFileDescriptor.open(file, ParcelFileDescriptor.MODE_READ_ONLY);
166	            }
167	
168	            @Override
169	            public void close(ParcelFileDescriptor parcelFileDescriptor) throws IOException {
170	              parcelFileDescriptor.close();
171	            }
172	
173	            @Override
174	            public Class<ParcelFileDescriptor> getDataClass() {
175	              return ParcelFileDescriptor.class;
176	            }
177	          });
178	    }
179	  }
180	}
