12	import com.bumptech.glide.signature.ObjectKey;
13	import java.io.InputStream;
14	
15	/**
16	 * Loads a specific data type from an Asset Manager Uri.
17	 *
18	 * @param <Data> The type of data this loader will obtain.
19	 */
20	public class AssetUriLoader<Data> implements ModelLoader<Uri, Data> {
21	  private static final String ASSET_PATH_SEGMENT = "android_asset";
22	  private static final String ASSET_PREFIX =
23	      ContentResolver.SCHEME_FILE + ":///" + ASSET_PATH_SEGMENT + "/";
24	  private static final int ASSET_PREFIX_LENGTH = ASSET_PREFIX.length();
25	
26	  private final AssetManager assetManager;
27	  private final AssetFetcherFactory<Data> factory;
28	
29	  // Public API.
30	  @SuppressWarnings("WeakerAccess")
31	  public AssetUriLoader(AssetManager assetManager, AssetFetcherFactory<Data> factory) {
32	    this.assetManager = assetManager;
33	    this.factory = factory;
34	  }
35	
36	  @Override
37	  public LoadData<Data> buildLoadData(
38	      @NonNull Uri model, int width, int height, @NonNull Options options) {
39	    String assetPath = model.toString().substring(ASSET_PREFIX_LENGTH);
40	    return new LoadData<>(new ObjectKey(model), factory.buildFetcher(assetManager, assetPath));
41	  }
42	
43	  @Override
44	  public boolean handles(@NonNull Uri model) {
45	    return ContentResolver.SCHEME_FILE.equals(model.getScheme())
46	        && !model.getPathSegments().isEmpty()
47	        && ASSET_PATH_SEGMENT.equals(model.getPathSegments().get(0));
48	  }
49	
50	  /**
51	   * A factory to build a {@link DataFetcher} for a specific asset path.
52	   *
53	   * @param <Data> The type of data that will be obtained by the fetcher.
54	   */
55	  public interface AssetFetcherFactory<Data> {
56	    DataFetcher<Data> buildFetcher(AssetManager assetManager, String assetPath);
57	  }
58	
59	  /** Factory for loading {@link InputStream}s from asset manager Uris. */
60	  public static class StreamFactory
61	      implements ModelLoaderFactory<Uri, InputStream>, AssetFetcherFactory<InputStream> {
62	
63	    private final AssetManager assetManager;
64	
65	    public StreamFactory(AssetManager assetManager) {
66	      this.assetManager = assetManager;
67	    }
68	
69	    @NonNull
70	    @Override
71	    public ModelLoader<Uri, InputStream> build(MultiModelLoaderFactory multiFactory) {
72	      return new AssetUriLoader<>(assetManager, this);
73	    }
74	
75	    @Override
76	    public void teardown() {
77	      // Do nothing.
78	    }
79	
80	    @Override
81	    public DataFetcher<InputStream> buildFetcher(AssetManager assetManager, String assetPath) {
82	      return new StreamAssetPathFetcher(assetManager, assetPath);
83	    }
84	  }
85	
86	  /** Factory for loading {@link AssetFileDescriptor}s from asset manager Uris. */
87	  public static class FileDescriptorFactory
88	      implements ModelLoaderFactory<Uri, AssetFileDescriptor>,
89	          AssetFetcherFactory<AssetFileDescriptor> {
90	
91	    private final AssetManager assetManager;
92	
93	    public FileDescriptorFactory(AssetManager assetManager) {
94	      this.assetManager = assetManager;
95	    }
96	
97	    @NonNull
98	    @Override
99	    public ModelLoader<Uri, AssetFileDescriptor> build(MultiModelLoaderFactory multiFactory) {
100	      return new AssetUriLoader<>(assetManager, this);
101	    }
102	
103	    @Override
104	    public void teardown() {
105	      // Do nothing.
106	    }
107	
108	    @Override
109	    public DataFetcher<AssetFileDescriptor> buildFetcher(
110	        AssetManager assetManager, String assetPath) {
111	      return new FileDescriptorAssetPathFetcher(assetManager, assetPath);
112	    }
113	  }
114	}
