3	import android.content.Context;
4	import android.database.Cursor;
5	import android.net.Uri;
6	import android.provider.MediaStore;
7	import android.text.TextUtils;
8	import androidx.annotation.NonNull;
9	import com.bumptech.glide.Priority;
10	import com.bumptech.glide.load.DataSource;
11	import com.bumptech.glide.load.Options;
12	import com.bumptech.glide.load.data.DataFetcher;
13	import com.bumptech.glide.load.data.mediastore.MediaStoreUtil;
14	import com.bumptech.glide.signature.ObjectKey;
15	import java.io.File;
16	import java.io.FileNotFoundException;
17	
18	/** Loads the file path for {@link MediaStore} owned {@link Uri uris}. */
19	public final class MediaStoreFileLoader implements ModelLoader<Uri, File> {
20	
21	  private final Context context;
22	
23	  // Public API.
24	  @SuppressWarnings("WeakerAccess")
25	  public MediaStoreFileLoader(Context context) {
26	    this.context = context;
27	  }
28	
29	  @Override
30	  public LoadData<File> buildLoadData(
31	      @NonNull Uri uri, int width, int height, @NonNull Options options) {
32	    return new LoadData<>(new ObjectKey(uri), new FilePathFetcher(context, uri));
33	  }
34	
35	  @Override
36	  public boolean handles(@NonNull Uri uri) {
37	    return MediaStoreUtil.isMediaStoreUri(uri);
38	  }
39	
40	  private static class FilePathFetcher implements DataFetcher<File> {
41	    private static final String[] PROJECTION =
42	        new String[] {
43	          MediaStore.MediaColumns.DATA,
44	        };
45	
46	    private final Context context;
47	    private final Uri uri;
48	
49	    FilePathFetcher(Context context, Uri uri) {
50	      this.context = context;
51	      this.uri = uri;
52	    }
53	
54	    @Override
55	    public void loadData(@NonNull Priority priority, @NonNull DataCallback<? super File> callback) {
56	      Cursor cursor =
57	          context
58	              .getContentResolver()
59	              .query(
60	                  uri, PROJECTION, null /*selection*/, null /*selectionArgs*/, null /*sortOrder*/);
61	
62	      String filePath = null;
63	      if (cursor != null) {
64	        try {
65	          if (cursor.moveToFirst()) {
66	            filePath = cursor.getString(cursor.getColumnIndexOrThrow(MediaStore.MediaColumns.DATA));
67	          }
68	        } finally {
69	          cursor.close();
70	        }
71	      }
72	
73	      if (TextUtils.isEmpty(filePath)) {
74	        callback.onLoadFailed(new FileNotFoundException("Failed to find file path for: " + uri));
75	      } else {
76	        callback.onDataReady(new File(filePath));
77	      }
78	    }
79	
80	    @Override
81	    public void cleanup() {
82	      // Do nothing.
83	    }
84	
85	    @Override
86	    public void cancel() {
87	      // Do nothing.
88	    }
89	
90	    @NonNull
91	    @Override
92	    public Class<File> getDataClass() {
93	      return File.class;
94	    }
95	
96	    @NonNull
97	    @Override
98	    public DataSource getDataSource() {
99	      return DataSource.LOCAL;
100	    }
101	  }
102	
103	  /** {@link ModelLoaderFactory} for {@link MediaStoreFileLoader}s. */
104	  public static final class Factory implements ModelLoaderFactory<Uri, File> {
105	
106	    private final Context context;
107	
108	    public Factory(Context context) {
109	      this.context = context;
110	    }
111	
112	    @NonNull
113	    @Override
114	    public ModelLoader<Uri, File> build(MultiModelLoaderFactory multiFactory) {
115	      return new MediaStoreFileLoader(context);
116	    }
117	
118	    @Override
119	    public void teardown() {
120	      // Do nothing.
121	    }
122	  }
123	}
