1	package com.bumptech.glide.load.model;
2	
3	import android.content.res.AssetFileDescriptor;
4	import android.net.Uri;
5	import android.os.ParcelFileDescriptor;
6	import android.text.TextUtils;
7	import androidx.annotation.NonNull;
8	import androidx.annotation.Nullable;
9	import com.bumptech.glide.load.Options;
10	import java.io.File;
11	import java.io.InputStream;
12	
13	/**
14	 * A model loader for handling certain string models. Handles paths, urls, and any uri string with a
15	 * scheme handled by {@link android.content.ContentResolver#openInputStream(Uri)}.
16	 *
17	 * @param <Data> The type of data that will be loaded from the given {@link java.lang.String}.
18	 */
19	public class StringLoader<Data> implements ModelLoader<String, Data> {
20	  private final ModelLoader<Uri, Data> uriLoader;
21	
22	  // Public API.
23	  @SuppressWarnings("WeakerAccess")
24	  public StringLoader(ModelLoader<Uri, Data> uriLoader) {
25	    this.uriLoader = uriLoader;
26	  }
27	
28	  @Override
29	  public LoadData<Data> buildLoadData(
30	      @NonNull String model, int width, int height, @NonNull Options options) {
31	    Uri uri = parseUri(model);
32	    if (uri == null || !uriLoader.handles(uri)) {
33	      return null;
34	    }
35	    return uriLoader.buildLoadData(uri, width, height, options);
36	  }
37	
38	  @Override
39	  public boolean handles(@NonNull String model) {
40	    // Avoid parsing the Uri twice and simply return null from buildLoadData if we don't handle this
41	    // particular Uri type.
42	    return true;
43	  }
44	
45	  @Nullable
46	  private static Uri parseUri(String model) {
47	    Uri uri;
48	    if (TextUtils.isEmpty(model)) {
49	      return null;
50	      // See https://pmd.github.io/pmd-6.0.0/pmd_rules_java_performance.html#simplifystartswith
51	    } else if (model.charAt(0) == '/') {
52	      uri = toFileUri(model);
53	    } else {
54	      uri = Uri.parse(model);
55	      String scheme = uri.getScheme();
56	      if (scheme == null) {
57	        uri = toFileUri(model);
58	      }
59	    }
60	    return uri;
61	  }
62	
63	  private static Uri toFileUri(String path) {
64	    return Uri.fromFile(new File(path));
65	  }
66	
67	  /** Factory for loading {@link InputStream}s from Strings. */
68	  public static class StreamFactory implements ModelLoaderFactory<String, InputStream> {
69	
70	    @NonNull
71	    @Override
72	    public ModelLoader<String, InputStream> build(@NonNull MultiModelLoaderFactory multiFactory) {
73	      return new StringLoader<>(multiFactory.build(Uri.class, InputStream.class));
74	    }
75	
76	    @Override
77	    public void teardown() {
78	      // Do nothing.
79	    }
80	  }
81	
