83	  public static class FileDescriptorFactory
84	      implements ModelLoaderFactory<String, ParcelFileDescriptor> {
85	
86	    @NonNull
87	    @Override
88	    public ModelLoader<String, ParcelFileDescriptor> build(
89	        @NonNull MultiModelLoaderFactory multiFactory) {
90	      return new StringLoader<>(multiFactory.build(Uri.class, ParcelFileDescriptor.class));
91	    }
92	
93	    @Override
94	    public void teardown() {
95	      // Do nothing.
96	    }
97	  }
