101	      implements ModelLoaderFactory<String, AssetFileDescriptor> {
102	
103	    @Override
104	    public ModelLoader<String, AssetFileDescriptor> build(
105	        @NonNull MultiModelLoaderFactory multiFactory) {
106	      return new StringLoader<>(multiFactory.build(Uri.class, AssetFileDescriptor.class));
107	    }
