12	/**
13	 * Handles http/https Uris by delegating to the {@link ModelLoader} for {@link
14	 * com.bumptech.glide.load.model.GlideUrl GlideUrls}.
15	 *
16	 * @param <Data> The type of data this Loader will obtain for a {@link Uri}.
17	 */
18	public class UrlUriLoader<Data> implements ModelLoader<Uri, Data> {
19	  private static final Set<String> SCHEMES =
20	      Collections.unmodifiableSet(new HashSet<>(Arrays.asList("http", "https")));
21	  private final ModelLoader<GlideUrl, Data> urlLoader;
