234	  @GuardedBy("Glide.class")
235	  @SuppressWarnings("deprecation")
236	  private static void initializeGlide(
237	      @NonNull Context context,
238	      @NonNull GlideBuilder builder,
239	      @Nullable GeneratedAppGlideModule annotationGeneratedModule) {
240	    Context applicationContext = context.getApplicationContext();
241	    List<GlideModule> manifestModules = Collections.emptyList();
242	    if (annotationGeneratedModule == null || annotationGeneratedModule.isManifestParsingEnabled()) {
243	      manifestModules = new ManifestParser(applicationContext).parse();
244	    }
245	
246	    if (annotationGeneratedModule != null
247	        && !annotationGeneratedModule.getExcludedModuleClasses().isEmpty()) {
248	      Set<Class<?>> excludedModuleClasses = annotationGeneratedModule.getExcludedModuleClasses();
249	      Iterator<GlideModule> iterator = manifestModules.iterator();
250	      while (iterator.hasNext()) {
251	        GlideModule current = iterator.next();
252	        if (!excludedModuleClasses.contains(current.getClass())) {
253	          continue;
254	        }
255	        if (Log.isLoggable(TAG, Log.DEBUG)) {
256	          Log.d(TAG, "AppGlideModule excludes manifest GlideModule: " + current);
257	        }
258	        iterator.remove();
259	      }
260	    }
261	
262	    if (Log.isLoggable(TAG, Log.DEBUG)) {
263	      for (GlideModule glideModule : manifestModules) {
264	        Log.d(TAG, "Discovered GlideModule from manifest: " + glideModule.getClass());
265	      }
266	    }
267	
268	    RequestManagerRetriever.RequestManagerFactory factory =
269	        annotationGeneratedModule != null
270	            ? annotationGeneratedModule.getRequestManagerFactory()
271	            : null;
272	    builder.setRequestManagerFactory(factory);
273	    for (GlideModule module : manifestModules) {
274	      module.applyOptions(applicationContext, builder);
275	    }
276	    if (annotationGeneratedModule != null) {
277	      annotationGeneratedModule.applyOptions(applicationContext, builder);
278	    }
279	    Glide glide = builder.build(applicationContext, manifestModules, annotationGeneratedModule);
280	    applicationContext.registerComponentCallbacks(glide);
281	    glide.registerActivityLifecycleCallbacks();
282	    Glide.glide = glide;
283	  }
