287	  private static GeneratedAppGlideModule getAnnotationGeneratedGlideModules(Context context) {
288	    GeneratedAppGlideModule result = null;
289	    try {
290	      Class<GeneratedAppGlideModule> clazz =
291	          (Class<GeneratedAppGlideModule>)
292	              Class.forName("com.bumptech.glide.GeneratedAppGlideModuleImpl");
293	      result =
294	          clazz.getDeclaredConstructor(Context.class).newInstance(context.getApplicationContext());
295	    } catch (ClassNotFoundException e) {
296	      if (Log.isLoggable(TAG, Log.WARN)) {
297	        Log.w(
298	            TAG,
299	            "Failed to find GeneratedAppGlideModule. You should include an"
300	                + " annotationProcessor compile dependency on com.github.bumptech.glide:compiler"
301	                + " in your application and a @GlideModule annotated AppGlideModule implementation"
302	                + " or LibraryGlideModules will be silently ignored");
303	      }
304	      // These exceptions can't be squashed across all versions of Android.
305	    } catch (InstantiationException e) {
306	      throwIncorrectGlideModule(e);
307	    } catch (IllegalAccessException e) {
308	      throwIncorrectGlideModule(e);
309	    } catch (NoSuchMethodException e) {
310	      throwIncorrectGlideModule(e);
311	    } catch (InvocationTargetException e) {
312	      throwIncorrectGlideModule(e);
313	    }
