1	package com.bumptech.glide.load.data;
2	
3	import android.content.ContentResolver;
4	import android.content.UriMatcher;
5	import android.content.res.AssetFileDescriptor;
6	import android.net.Uri;
7	import android.os.Build.VERSION_CODES;
8	import android.provider.ContactsContract;
9	import androidx.annotation.NonNull;
10	import androidx.annotation.RequiresExtension;
11	import com.bumptech.glide.load.data.mediastore.MediaStoreUtil;
12	import java.io.FileNotFoundException;
13	import java.io.IOException;
14	import java.io.InputStream;
15	
16	/** Fetches an {@link java.io.InputStream} for a local {@link android.net.Uri}. */
17	public class StreamLocalUriFetcher extends LocalUriFetcher<InputStream> {
18	  /** A lookup uri (e.g. content://com.android.contacts/contacts/lookup/3570i61d948d30808e537) */
19	  private static final int ID_CONTACTS_LOOKUP = 1;
20	
21	  /** A contact thumbnail uri (e.g. content://com.android.contacts/contacts/38/photo) */
22	  private static final int ID_CONTACTS_THUMBNAIL = 2;
23	
24	  /** A contact uri (e.g. content://com.android.contacts/contacts/38) */
25	  private static final int ID_CONTACTS_CONTACT = 3;
26	
27	  /**
28	   * A contact display photo (high resolution) uri (e.g.
29	   * content://com.android.contacts/5/display_photo)
30	   */
31	  private static final int ID_CONTACTS_PHOTO = 4;
32	
33	  /**
34	   * Uri for optimized search of phones by number (e.g.
35	   * content://com.android.contacts/phone_lookup/232323232
36	   */
37	  private static final int ID_LOOKUP_BY_PHONE = 5;
38	
39	  /** Match the incoming Uri for special cases which we can handle nicely. */
40	  private static final UriMatcher URI_MATCHER;
41	
42	  static {
43	    URI_MATCHER = new UriMatcher(UriMatcher.NO_MATCH);
44	    URI_MATCHER.addURI(ContactsContract.AUTHORITY, "contacts/lookup/*/#", ID_CONTACTS_LOOKUP);
45	    URI_MATCHER.addURI(ContactsContract.AUTHORITY, "contacts/lookup/*", ID_CONTACTS_LOOKUP);
46	    URI_MATCHER.addURI(ContactsContract.AUTHORITY, "contacts/#/photo", ID_CONTACTS_THUMBNAIL);
47	    URI_MATCHER.addURI(ContactsContract.AUTHORITY, "contacts/#", ID_CONTACTS_CONTACT);
48	    URI_MATCHER.addURI(ContactsContract.AUTHORITY, "contacts/#/display_photo", ID_CONTACTS_PHOTO);
49	    URI_MATCHER.addURI(ContactsContract.AUTHORITY, "phone_lookup/*", ID_LOOKUP_BY_PHONE);
50	  }
51	
52	  public StreamLocalUriFetcher(ContentResolver resolver, Uri uri) {
53	    super(resolver, uri);
54	  }
55	
56	  /**
57	   * useMediaStoreApisIfAvailable is part of an experiment and the constructor can be removed in a
58	   * future version.
59	   */
60	  public StreamLocalUriFetcher(
61	      ContentResolver resolver, Uri uri, boolean useMediaStoreApisIfAvailable) {
62	    super(resolver, uri, useMediaStoreApisIfAvailable);
63	  }
64	
65	  @Override
66	  protected InputStream loadResource(Uri uri, ContentResolver contentResolver)
67	      throws FileNotFoundException {
68	    InputStream inputStream = loadResourceFromUri(uri, contentResolver);
69	    if (inputStream == null) {
70	      throw new FileNotFoundException("InputStream is null for " + uri);
71	    }
72	    return inputStream;
73	  }
74	
75	  private InputStream loadResourceFromUri(Uri uri, ContentResolver contentResolver)
76	      throws FileNotFoundException {
77	    switch (URI_MATCHER.match(uri)) {
78	      case ID_CONTACTS_CONTACT:
79	        return openContactPhotoInputStream(contentResolver, uri);
80	      case ID_CONTACTS_LOOKUP:
81	      case ID_LOOKUP_BY_PHONE:
82	        // If it was a Lookup uri then resolve it first, then continue loading the contact uri.
83	        uri = ContactsContract.Contacts.lookupContact(contentResolver, uri);
84	        if (uri == null) {
85	          throw new FileNotFoundException("Contact cannot be found");
86	        }
87	        return openContactPhotoInputStream(contentResolver, uri);
88	      case ID_CONTACTS_THUMBNAIL:
89	      case ID_CONTACTS_PHOTO:
90	      case UriMatcher.NO_MATCH:
91	      default:
92	        if (useMediaStoreApisIfAvailable
93	            && MediaStoreUtil.isMediaStoreUri(uri)
94	            && MediaStoreUtil.isMediaStoreOpenFileApisAvailable()) {
95	          return openMediaStoreFileInputStream(uri, contentResolver);
96	        } else {
97	          return contentResolver.openInputStream(uri);
98	        }
99	    }
100	  }
101	
102	  private InputStream openContactPhotoInputStream(ContentResolver contentResolver, Uri contactUri) {
103	    return ContactsContract.Contacts.openContactPhotoInputStream(
104	        contentResolver, contactUri, true /*preferHighres*/);
105	  }
106	
107	  @RequiresExtension(
108	      extension = VERSION_CODES.R,
109	      version = MediaStoreUtil.MIN_EXTENSION_VERSION_FOR_OPEN_FILE_APIS)
110	  private InputStream openMediaStoreFileInputStream(Uri uri, ContentResolver contentResolver)
111	      throws FileNotFoundException {
112	    AssetFileDescriptor assetFileDescriptor =
113	        MediaStoreUtil.openAssetFileDescriptor(uri, contentResolver);
114	    if (assetFileDescriptor == null) {
115	      throw new FileNotFoundException("FileDescriptor is null for: " + uri);
116	    }
117	    try {
118	      return assetFileDescriptor.createInputStream();
119	    } catch (IOException exception) {
120	      try {
121	        assetFileDescriptor.close();
122	      } catch (Exception innerException) {
123	        // Ignored
124	      }
125	      throw (FileNotFoundException)
126	          new FileNotFoundException("Unable to create stream").initCause(exception);
127	    }
128	  }
129	
130	  @Override
131	  protected void close(InputStream data) throws IOException {
132	    data.close();
133	  }
134	
135	  @NonNull
136	  @Override
137	  public Class<InputStream> getDataClass() {
138	    return InputStream.class;
139	  }
140	}
