337	    private final Set<Bitmap> bitmaps = Collections.synchronizedSet(new HashSet<Bitmap>());
338	
339	    @Override
340	    public void add(Bitmap bitmap) {
341	      if (bitmaps.contains(bitmap)) {
342	        throw new IllegalStateException(
343	            "Can't add already added bitmap: "
344	                + bitmap
345	                + " ["
346	                + bitmap.getWidth()
347	                + "x"
348	                + bitmap.getHeight()
349	                + "]");
350	      }
351	      bitmaps.add(bitmap);
352	    }
353	
354	    @Override
355	    public void remove(Bitmap bitmap) {
356	      if (!bitmaps.contains(bitmap)) {
357	        throw new IllegalStateException("Cannot remove bitmap not in tracker");
358	      }
359	      bitmaps.remove(bitmap);
360	    }
361	  }
