363	  private static final class NullBitmapTracker implements BitmapTracker {
364	
365	    @Synthetic
366	    NullBitmapTracker() {}
367	
368	    @Override
369	    public void add(Bitmap bitmap) {
370	      // Do nothing.
371	    }
372	
373	    @Override
