633	   * Bitmap}s) that may have been loaded for the target so they may be reused.
634	   *
635	   * @param target The Target to cancel loads for.
636	   */
637	  public void clear(@Nullable final Target<?> target) {
638	    if (target == null) {
639	      return;
640	    }
641	
642	    untrackOrDelegate(target);
643	  }
644	
645	  private void untrackOrDelegate(@NonNull Target<?> target) {
646	    boolean isOwnedByUs = untrack(target);
647	    // We'll end up here if the Target was cleared after the RequestManager that started the request
648	    // is destroyed. That can happen for at least two reasons:
649	    // 1. We call clear() on a background thread using something other than Application Context
650	    // RequestManager.
651	    // 2. The caller retains a reference to the RequestManager after the corresponding Activity or
652	    // Fragment is destroyed, starts a load with it, and then clears that load with a different
653	    // RequestManager. Callers seem especially likely to do this in retained Fragments (#2262).
654	    //
655	    // #1 is always an error. At best the caller is leaking memory briefly in something like an
656	    // AsyncTask. At worst the caller is leaking an Activity or Fragment for a sustained period of
657	    // time if they do something like reference the Activity RequestManager in a long lived
658	    // background thread or task.
659	    //
660	    // #2 is always an error. Callers shouldn't be starting new loads using RequestManagers after
661	    // the corresponding Activity or Fragment is destroyed because retaining any reference to the
662	    // RequestManager leaks memory. It's possible that there's some brief period of time during or
663	    // immediately after onDestroy where this is reasonable, but I can't think of why.
664	    Request request = target.getRequest();
665	    if (!isOwnedByUs && !glide.removeFromManagers(target) && request != null) {
666	      target.setRequest(null);
667	      request.clear();
668	    }
669	  }
670	
671	  synchronized boolean untrack(@NonNull Target<?> target) {
672	    Request request = target.getRequest();
673	    // If the Target doesn't have a request, it's already been cleared.
674	    if (request == null) {
675	      return true;
676	    }
677	
678	    if (requestTracker.clearAndRemove(request)) {
679	      targetTracker.untrack(target);
680	      target.setRequest(null);
681	      return true;
682	    } else {
683	      return false;
684	    }
685	  }
686	
687	  synchronized void track(@NonNull Target<?> target, @NonNull Request request) {
688	    targetTracker.track(target);
689	    requestTracker.runRequest(request);
690	  }
