236	  private static final class PreloadTargetQueue {
237	    @Synthetic final Queue<PreloadTarget> queue;
238	
239	    // The loop is short and the only point is to create the objects.
240	    @SuppressWarnings("PMD.AvoidInstantiatingObjectsInLoops")
241	    PreloadTargetQueue(int size) {
242	      queue = Util.createQueue(size);
