639	  private void untrackOrDelegate(@NonNull Target<?> target) {
640	    boolean isOwnedByUs = untrack(target);
641	    // We'll end up here if the Target was cleared after the RequestManager that started the request
642	    // is destroyed. That can happen for at least two reasons:
643	    // 1. We call clear() on a background thread using something other than Application Context
644	    // RequestManager.
645	    // 2. The caller retains a reference to the RequestManager after the corresponding Activity or
646	    // Fragment is destroyed, starts a load with it, and then clears that load with a different
647	    // RequestManager. Callers seem especially likely to do this in retained Fragments (#2262).
648	    //
649	    // #1 is always an error. At best the caller is leaking memory briefly in something like an
650	    // AsyncTask. At worst the caller is leaking an Activity or Fragment for a sustained period of
651	    // time if they do something like reference the Activity RequestManager in a long lived
652	    // background thread or task.
653	    //
654	    // #2 is always an error. Callers shouldn't be starting new loads using RequestManagers after
655	    // the corresponding Activity or Fragment is destroyed because retaining any reference to the
656	    // RequestManager leaks memory. It's possible that there's some brief period of time during or
657	    // immediately after onDestroy where this is reasonable, but I can't think of why.
658	    Request request = target.getRequest();
659	    if (!isOwnedByUs && !glide.removeFromManagers(target) && request != null) {
660	      target.setRequest(null);
661	      request.clear();
662	    }
663	  }
664	
665	  synchronized boolean untrack(@NonNull Target<?> target) {
666	    Request request = target.getRequest();
667	    // If the Target doesn't have a request, it's already been cleared.
668	    if (request == null) {
669	      return true;
670	    }
671	
672	    if (requestTracker.clearAndRemove(request)) {
673	      targetTracker.untrack(target);
674	      target.setRequest(null);
675	      return true;
676	    }
677	    return false;
678	  }
