448	    RequestBuilder<TranscodeType> previous = null;
449	
450	    // Start with the lowest priority thumbnail so that we can safely handle mutations if
451	    // autoClone() is enabled by assigning the result of calling thumbnail() during the iteration.
452	    // Starting with the highest priority thumbnail would prevent us from assigning the result of
453	    // thumbnail because the mutated request wouldn't be used in the next iteration.
454	    for (int i = thumbnails.size() - 1; i >= 0; i--) {
455	      RequestBuilder<TranscodeType> current = thumbnails.get(i);
