1246	  private Request buildThumbnailRequestRecursive(
1247	      Object requestLock,
1248	      Target<TranscodeType> target,
1249	      RequestListener<TranscodeType> targetListener,
1250	      @Nullable RequestCoordinator parentCoordinator,
1251	      TransitionOptions<?, ? super TranscodeType> transitionOptions,
1252	      Priority priority,
1253	      int overrideWidth,
1254	      int overrideHeight,
1255	      BaseRequestOptions<?> requestOptions,
1256	      Executor callbackExecutor) {
1257	    if (thumbnailBuilder != null) {
1258	      // Recursive case: contains a potentially recursive thumbnail request builder.
1259	      if (isThumbnailBuilt) {
