1270	      if (thumbnailBuilder.isDefaultTransitionOptionsSet) {
1271	        thumbTransitionOptions = transitionOptions;
1272	      }
1273	
1274	      Priority thumbPriority =
1275	          thumbnailBuilder.isPrioritySet()
1276	              ? thumbnailBuilder.getPriority()
1277	              : getThumbnailPriority(priority);
1278	
1279	      int thumbOverrideWidth = thumbnailBuilder.getOverrideWidth();
1280	      int thumbOverrideHeight = thumbnailBuilder.getOverrideHeight();
1281	      if (Util.isValidDimensions(overrideWidth, overrideHeight)
1282	          && !thumbnailBuilder.isValidOverride()) {
1283	        thumbOverrideWidth = requestOptions.getOverrideWidth();
1284	        thumbOverrideHeight = requestOptions.getOverrideHeight();
1285	      }
1286	
1287	      ThumbnailRequestCoordinator coordinator =
1288	          new ThumbnailRequestCoordinator(requestLock, parentCoordinator);
1289	      Request fullRequest =
1290	          obtainRequest(
1291	              requestLock,
1292	              target,
1293	              targetListener,
1294	              requestOptions,
1295	              coordinator,
1296	              transitionOptions,
1297	              priority,
1298	              overrideWidth,
1299	              overrideHeight,
1300	              callbackExecutor);
1301	      isThumbnailBuilt = true;
1302	      // Recursively generate thumbnail requests.
1303	      Request thumbRequest =
1304	          thumbnailBuilder.buildRequestRecursive(
1305	              requestLock,
1306	              target,
1307	              targetListener,
1308	              coordinator,
1309	              thumbTransitionOptions,
1310	              thumbPriority,
1311	              thumbOverrideWidth,
1312	              thumbOverrideHeight,
1313	              thumbnailBuilder,
1314	              callbackExecutor);
1315	      isThumbnailBuilt = false;
1316	      coordinator.setRequests(fullRequest, thumbRequest);
1317	      return coordinator;
1318	    } else if (thumbSizeMultiplier != null) {
1319	      // Base case: thumbnail multiplier generates a thumbnail request, but cannot recurse.
1320	      ThumbnailRequestCoordinator coordinator =
1321	          new ThumbnailRequestCoordinator(requestLock, parentCoordinator);
1322	      Request fullRequest =
1323	          obtainRequest(
1324	              requestLock,
1325	              target,
1326	              targetListener,
1327	              requestOptions,
1328	              coordinator,
1329	              transitionOptions,
1330	              priority,
1331	              overrideWidth,
1332	              overrideHeight,
1333	              callbackExecutor);
1334	      BaseRequestOptions<?> thumbnailOptions =
1335	          requestOptions.clone().sizeMultiplier(thumbSizeMultiplier);
1336	
1337	      Request thumbnailRequest =
1338	          obtainRequest(
1339	              requestLock,
1340	              target,
1341	              targetListener,
1342	              thumbnailOptions,
1343	              coordinator,
1344	              transitionOptions,
1345	              getThumbnailPriority(priority),
1346	              overrideWidth,
1347	              overrideHeight,
1348	              callbackExecutor);
1349	
1350	      coordinator.setRequests(fullRequest, thumbnailRequest);
1351	      return coordinator;
1352	    } else {
1353	      // Base case: no thumbnail.
1354	      return obtainRequest(
1355	          requestLock,
1356	          target,
1357	          targetListener,
1358	          requestOptions,
1359	          parentCoordinator,
1360	          transitionOptions,
1361	          priority,
1362	          overrideWidth,
1363	          overrideHeight,
1364	          callbackExecutor);
1365	    }
1366	  }
