13	/**
14	 * A wrapper class for a set of headers to be included in a Glide request, allowing headers to be
15	 * constructed lazily.
16	 *
17	 * <p>Ideally headers are constructed once and then re-used for multiple loads, rather then being
18	 * constructed individually for each load.
19	 *
20	 * <p>This class is thread safe.
21	 */
22	public final class LazyHeaders implements Headers {
23	  private final Map<String, List<LazyHeaderFactory>> headers;
24	  private volatile Map<String, String> combinedHeaders;
25	
26	  LazyHeaders(Map<String, List<LazyHeaderFactory>> headers) {
27	    this.headers = Collections.unmodifiableMap(headers);
28	  }
29	
30	  @Override
31	  public Map<String, String> getHeaders() {
32	    if (combinedHeaders == null) {
33	      synchronized (this) {
34	        if (combinedHeaders == null) {
35	          this.combinedHeaders = Collections.unmodifiableMap(generateHeaders());
36	        }
37	      }
38	    }
39	
40	    return combinedHeaders;
41	  }
42	
43	  private Map<String, String> generateHeaders() {
44	    Map<String, String> combinedHeaders = new HashMap<>();
45	
46	    for (Map.Entry<String, List<LazyHeaderFactory>> entry : headers.entrySet()) {
47	      String values = buildHeaderValue(entry.getValue());
48	      if (!TextUtils.isEmpty(values)) {
49	        combinedHeaders.put(entry.getKey(), values);
50	      }
51	    }
52	
53	    return combinedHeaders;
54	  }
55	
56	  @NonNull
57	  private String buildHeaderValue(@NonNull List<LazyHeaderFactory> factories) {
58	    StringBuilder sb = new StringBuilder();
59	    int size = factories.size();
60	    for (int i = 0; i < size; i++) {
61	      LazyHeaderFactory factory = factories.get(i);
62	      String header = factory.buildHeader();
63	      if (!TextUtils.isEmpty(header)) {
64	        sb.append(header);
65	        if (i != factories.size() - 1) {
66	          sb.append(',');
67	        }
68	      }
69	    }
70	    return sb.toString();
71	  }
72	
73	  @Override
74	  public String toString() {
75	    return "LazyHeaders{" + "headers=" + headers + '}';
76	  }
77	
78	  @Override
79	  public boolean equals(Object o) {
80	    if (o instanceof LazyHeaders) {
81	      LazyHeaders other = (LazyHeaders) o;
82	      return headers.equals(other.headers);
83	    }
84	    return false;
85	  }
86	
87	  @Override
88	  public int hashCode() {
89	    return headers.hashCode();
90	  }
91	
92	  /**
93	   * Adds an {@link LazyHeaderFactory} that will be used to construct a value for the given key*
94	   * lazily on a background thread.
95	   *
96	   * <p>This class is not thread safe.
97	   *
98	   * <p>This class may include default values for User-Agent and Accept-Encoding headers. These will
99	   * be replaced by calls to either {@link #setHeader(String, LazyHeaderFactory)} or {@link
100	   * #addHeader(String, String)}, even though {@link #addHeader(String, LazyHeaderFactory)} would
101	   * usually append an additional value.
102	   */
103	  public static final class Builder {
104	    private static final String USER_AGENT_HEADER = "User-Agent";
105	    private static final String DEFAULT_USER_AGENT = getSanitizedUserAgent();
106	    private static final Map<String, List<LazyHeaderFactory>> DEFAULT_HEADERS;
107	
108	    // Set Accept-Encoding header to do our best to avoid gzip since it's both inefficient for
109	    // images and also makes it more difficult for us to detect and prevent partial content
110	    // rendering. See #440.
111	    static {
112	      Map<String, List<LazyHeaderFactory>> temp = new HashMap<>(2);
113	      if (!TextUtils.isEmpty(DEFAULT_USER_AGENT)) {
114	        temp.put(
115	            USER_AGENT_HEADER,
116	            Collections.<LazyHeaderFactory>singletonList(
117	                new StringHeaderFactory(DEFAULT_USER_AGENT)));
118	      }
119	      DEFAULT_HEADERS = Collections.unmodifiableMap(temp);
120	    }
121	
122	    private boolean copyOnModify = true;
123	    private Map<String, List<LazyHeaderFactory>> headers = DEFAULT_HEADERS;
124	    private boolean isUserAgentDefault = true;
125	
126	    /**
127	     * Adds a value for the given header and returns this builder.
128	     *
129	     * <p>Use {@link #addHeader(String, LazyHeaderFactory)} if obtaining the value requires I/O
130	     * (i.e. an OAuth token).
131	     *
132	     * @see #addHeader(String, LazyHeaderFactory)
133	     */
134	    public Builder addHeader(@NonNull String key, @NonNull String value) {
135	      return addHeader(key, new StringHeaderFactory(value));
136	    }
137	
138	    /**
139	     * Adds an {@link LazyHeaderFactory} that will be used to construct a value for the given key
140	     * lazily on a background thread.
141	     *
142	     * <p>Headers may have multiple values whose order is defined by the order in which this method
143	     * is called.
144	     *
145	     * <p>This class does not prevent you from adding the same value to a given key multiple times
146	     */
147	    public Builder addHeader(@NonNull String key, @NonNull LazyHeaderFactory factory) {
148	      if (isUserAgentDefault && USER_AGENT_HEADER.equalsIgnoreCase(key)) {
149	        return setHeader(key, factory);
150	      }
151	
152	      copyIfNecessary();
153	      getFactories(key).add(factory);
154	      return this;
155	    }
156	
157	    /**
158	     * Replaces all existing {@link LazyHeaderFactory LazyHeaderFactorys} for the given key with the
159	     * given {@link LazyHeaderFactory}.
160	     *
161	     * <p>If the given value is {@code null}, the header at the given key will be removed.
162	     *
163	     * <p>Use {@link #setHeader(String, LazyHeaderFactory)} if obtaining the value requires I/O
164	     * (i.e. an OAuth token).
165	     */
166	    @SuppressWarnings({"UnusedReturnValue", "WeakerAccess"}) // Public API
167	    public Builder setHeader(@NonNull String key, @Nullable String value) {
168	      return setHeader(key, value == null ? null : new StringHeaderFactory(value));
169	    }
170	
171	    /**
172	     * Replaces all existing {@link LazyHeaderFactory LazyHeaderFactorys} for the given key with the
173	     * given {@link LazyHeaderFactory}.
174	     *
175	     * <p>If the given value is {@code null}, the header at the given key will be removed.
176	     */
177	    public Builder setHeader(@NonNull String key, @Nullable LazyHeaderFactory factory) {
178	      copyIfNecessary();
179	      if (factory == null) {
180	        headers.remove(key);
181	      } else {
182	        List<LazyHeaderFactory> factories = getFactories(key);
183	        factories.clear();
184	        factories.add(factory);
185	      }
186	
187	      if (isUserAgentDefault && USER_AGENT_HEADER.equalsIgnoreCase(key)) {
188	        isUserAgentDefault = false;
189	      }
190	
191	      return this;
192	    }
193	
194	    private List<LazyHeaderFactory> getFactories(String key) {
195	      List<LazyHeaderFactory> factories = headers.get(key);
196	      if (factories == null) {
197	        factories = new ArrayList<>();
198	        headers.put(key, factories);
199	      }
200	      return factories;
201	    }
202	
203	    private void copyIfNecessary() {
204	      if (copyOnModify) {
205	        copyOnModify = false;
206	        headers = copyHeaders();
207	      }
208	    }
209	
210	    /** Returns a new immutable {@link LazyHeaders} object. */
211	    public LazyHeaders build() {
212	      copyOnModify = true;
213	      return new LazyHeaders(headers);
214	    }
215	
216	    private Map<String, List<LazyHeaderFactory>> copyHeaders() {
217	      Map<String, List<LazyHeaderFactory>> result = new HashMap<>(headers.size());
218	      for (Map.Entry<String, List<LazyHeaderFactory>> entry : headers.entrySet()) {
219	        @SuppressWarnings("PMD.AvoidInstantiatingObjectsInLoops")
220	        List<LazyHeaderFactory> valueCopy = new ArrayList<>(entry.getValue());
221	        result.put(entry.getKey(), valueCopy);
222	      }
223	      return result;
224	    }
225	
226	    /**
227	     * Ensures that the default header will pass OkHttp3's checks for header values.
228	     *
229	     * @see <a href="https://github.com/bumptech/glide/issues/2331">#2331</a>
230	     */
231	    @VisibleForTesting
232	    static String getSanitizedUserAgent() {
233	      String defaultUserAgent = System.getProperty("http.agent");
234	      if (TextUtils.isEmpty(defaultUserAgent)) {
235	        return defaultUserAgent;
236	      }
237	
238	      int length = defaultUserAgent.length();
239	      StringBuilder sb = new StringBuilder(defaultUserAgent.length());
240	      for (int i = 0; i < length; i++) {
241	        char c = defaultUserAgent.charAt(i);
242	        if ((c > '\u001f' || c == '\t') && c < '\u007f') {
243	          sb.append(c);
244	        } else {
245	          sb.append('?');
246	        }
247	      }
248	      return sb.toString();
249	    }
250	  }
251	
252	  static final class StringHeaderFactory implements LazyHeaderFactory {
253	
254	    @NonNull private final String value;
255	
256	    StringHeaderFactory(@NonNull String value) {
257	      this.value = value;
258	    }
259	
260	    @Override
261	    public String buildHeader() {
262	      return value;
263	    }
264	
265	    @Override
266	    public String toString() {
267	      return "StringHeaderFactory{" + "value='" + value + '\'' + '}';
268	    }
269	
270	    @Override
271	    public boolean equals(Object o) {
272	      if (o instanceof StringHeaderFactory) {
273	        StringHeaderFactory other = (StringHeaderFactory) o;
274	        return value.equals(other.value);
275	      }
276	      return false;
277	    }
278	
279	    @Override
280	    public int hashCode() {
281	      return value.hashCode();
282	    }
283	  }
284	}
