1	package com.bumptech.glide.load.model;
2	
3	import androidx.annotation.NonNull;
4	import androidx.annotation.Nullable;
5	import androidx.core.util.Pools.Pool;
6	import com.bumptech.glide.Registry.NoModelLoaderAvailableException;
7	import com.bumptech.glide.util.Synthetic;
8	import java.util.ArrayList;
9	import java.util.Collections;
10	import java.util.HashMap;
11	import java.util.List;
12	import java.util.Map;
13	
14	/**
15	 * Maintains an ordered put of {@link ModelLoader}s and the model and data types they handle in
16	 * order from highest priority to lowest.
17	 */
18	// Hides Model throughout.
19	@SuppressWarnings("TypeParameterHidesVisibleType")
20	public class ModelLoaderRegistry {
21	
22	  private final MultiModelLoaderFactory multiModelLoaderFactory;
23	  private final ModelLoaderCache cache = new ModelLoaderCache();
24	
25	  public ModelLoaderRegistry(@NonNull Pool<List<Throwable>> throwableListPool) {
26	    this(new MultiModelLoaderFactory(throwableListPool));
27	  }
28	
29	  private ModelLoaderRegistry(@NonNull MultiModelLoaderFactory multiModelLoaderFactory) {
30	    this.multiModelLoaderFactory = multiModelLoaderFactory;
31	  }
32	
33	  public synchronized <Model, Data> void append(
34	      @NonNull Class<Model> modelClass,
35	      @NonNull Class<Data> dataClass,
36	      @NonNull ModelLoaderFactory<? extends Model, ? extends Data> factory) {
37	    multiModelLoaderFactory.append(modelClass, dataClass, factory);
38	    cache.clear();
39	  }
40	
41	  public synchronized <Model, Data> void prepend(
42	      @NonNull Class<Model> modelClass,
43	      @NonNull Class<Data> dataClass,
44	      @NonNull ModelLoaderFactory<? extends Model, ? extends Data> factory) {
45	    multiModelLoaderFactory.prepend(modelClass, dataClass, factory);
46	    cache.clear();
47	  }
48	
49	  public synchronized <Model, Data> void remove(
50	      @NonNull Class<Model> modelClass, @NonNull Class<Data> dataClass) {
51	    tearDown(multiModelLoaderFactory.remove(modelClass, dataClass));
52	    cache.clear();
53	  }
54	
55	  public synchronized <Model, Data> void replace(
56	      @NonNull Class<Model> modelClass,
57	      @NonNull Class<Data> dataClass,
58	      @NonNull ModelLoaderFactory<? extends Model, ? extends Data> factory) {
59	    tearDown(multiModelLoaderFactory.replace(modelClass, dataClass, factory));
60	    cache.clear();
61	  }
62	
63	  private <Model, Data> void tearDown(
64	      @NonNull List<ModelLoaderFactory<? extends Model, ? extends Data>> factories) {
65	    for (ModelLoaderFactory<? extends Model, ? extends Data> factory : factories) {
66	      factory.teardown();
67	    }
68	  }
69	
70	  // We're allocating in a loop to avoid allocating empty lists that will never have anything added
71	  // to them.
72	  @SuppressWarnings("PMD.AvoidInstantiatingObjectsInLoops")
73	  @NonNull
74	  public <A> List<ModelLoader<A, ?>> getModelLoaders(@NonNull A model) {
75	    List<ModelLoader<A, ?>> modelLoaders = getModelLoadersForClass(getClass(model));
76	    if (modelLoaders.isEmpty()) {
77	      throw new NoModelLoaderAvailableException(model);
78	    }
79	    int size = modelLoaders.size();
80	    boolean isEmpty = true;
81	    List<ModelLoader<A, ?>> filteredLoaders = Collections.emptyList();
82	    //noinspection ForLoopReplaceableByForEach to improve perf
83	    for (int i = 0; i < size; i++) {
84	      ModelLoader<A, ?> loader = modelLoaders.get(i);
85	      if (loader.handles(model)) {
86	        if (isEmpty) {
87	          filteredLoaders = new ArrayList<>(size - i);
88	          isEmpty = false;
89	        }
90	        filteredLoaders.add(loader);
91	      }
92	    }
93	    if (filteredLoaders.isEmpty()) {
94	      throw new NoModelLoaderAvailableException(model, modelLoaders);
95	    }
96	    return filteredLoaders;
97	  }
98	
99	  public synchronized <Model, Data> ModelLoader<Model, Data> build(
100	      @NonNull Class<Model> modelClass, @NonNull Class<Data> dataClass) {
101	    return multiModelLoaderFactory.build(modelClass, dataClass);
102	  }
103	
104	  @NonNull
105	  public synchronized List<Class<?>> getDataClasses(@NonNull Class<?> modelClass) {
106	    return multiModelLoaderFactory.getDataClasses(modelClass);
107	  }
108	
109	  @NonNull
110	  private synchronized <A> List<ModelLoader<A, ?>> getModelLoadersForClass(
111	      @NonNull Class<A> modelClass) {
112	    List<ModelLoader<A, ?>> loaders = cache.get(modelClass);
113	    if (loaders == null) {
114	      loaders = Collections.unmodifiableList(multiModelLoaderFactory.build(modelClass));
115	      cache.put(modelClass, loaders);
116	    }
117	    return loaders;
118	  }
119	
120	  @NonNull
121	  @SuppressWarnings("unchecked")
122	  private static <A> Class<A> getClass(@NonNull A model) {
123	    return (Class<A>) model.getClass();
124	  }
125	
126	  private static class ModelLoaderCache {
127	    private final Map<Class<?>, Entry<?>> cachedModelLoaders = new HashMap<>();
128	
129	    @Synthetic
130	    ModelLoaderCache() {}
131	
132	    public void clear() {
133	      cachedModelLoaders.clear();
134	    }
135	
136	    public <Model> void put(Class<Model> modelClass, List<ModelLoader<Model, ?>> loaders) {
137	      Entry<?> previous = cachedModelLoaders.put(modelClass, new Entry<>(loaders));
138	      if (previous != null) {
139	        throw new IllegalStateException("Already cached loaders for model: " + modelClass);
140	      }
141	    }
142	
143	    @Nullable
144	    @SuppressWarnings("unchecked")
145	    public <Model> List<ModelLoader<Model, ?>> get(Class<Model> modelClass) {
146	      Entry<Model> entry = (Entry<Model>) cachedModelLoaders.get(modelClass);
147	      return entry == null ? null : entry.loaders;
148	    }
149	
150	    private static class Entry<Model> {
151	      @Synthetic final List<ModelLoader<Model, ?>> loaders;
152	
153	      public Entry(List<ModelLoader<Model, ?>> loaders) {
154	        this.loaders = loaders;
155	      }
156	    }
157	  }
