15	 * scheme handled by {@link android.content.ContentResolver#openInputStream(Uri)}.
16	 *
17	 * @param <Data> The type of data that will be loaded from the given {@link java.lang.String}.
18	 */
19	public class StringLoader<Data> implements ModelLoader<String, Data> {
20	  private final ModelLoader<Uri, Data> uriLoader;
21	
22	  // Public API.
23	  @SuppressWarnings("WeakerAccess")
24	  public StringLoader(ModelLoader<Uri, Data> uriLoader) {
25	    this.uriLoader = uriLoader;
26	  }
27	
28	  @Override
29	  public LoadData<Data> buildLoadData(
30	      @NonNull String model, int width, int height, @NonNull Options options) {
31	    Uri uri = parseUri(model);
32	    if (uri == null || !uriLoader.handles(uri)) {
33	      return null;
34	    }
35	    return uriLoader.buildLoadData(uri, width, height, options);
36	  }
37	
38	  @Override
39	  public boolean handles(@NonNull String model) {
40	    // Avoid parsing the Uri twice and simply return null from buildLoadData if we don't handle this
41	    // particular Uri type.
42	    return true;
43	  }
44	
45	  @Nullable
46	  private static Uri parseUri(String model) {
47	    Uri uri;
48	    if (TextUtils.isEmpty(model)) {
49	      return null;
50	      // See https://pmd.github.io/pmd-6.0.0/pmd_rules_java_performance.html#simplifystartswith
51	    } else if (model.charAt(0) == '/') {
52	      uri = toFileUri(model);
53	    } else {
54	      uri = Uri.parse(model);
55	      String scheme = uri.getScheme();
56	      if (scheme == null) {
57	        uri = toFileUri(model);
58	      }
59	    }
60	    return uri;
61	  }
62	
