90	  static GlideSupplier<Registry> lazilyCreateAndInitializeRegistry(
91	      final Glide glide,
92	      final List<GlideModule> manifestModules,
93	      @Nullable final AppGlideModule annotationGeneratedModule) {
94	    return new GlideSupplier<Registry>() {
95	      // Rely on callers using memoization if they want to avoid duplicate work, but
96	      // rely on ourselves to verify that no recursive initialization occurs.
97	      private boolean isInitializing;
98	
99	      @Override
100	      public Registry get() {
101	        if (isInitializing) {
102	          throw new IllegalStateException(
103	              "Recursive Registry initialization! In your"
104	                  + " AppGlideModule and LibraryGlideModules, Make sure you're using the provided "
105	                  + "Registry rather calling glide.getRegistry()!");
106	        }
107	        Trace.beginSection("Glide registry");
108	        isInitializing = true;
109	        try {
110	          return createAndInitRegistry(glide, manifestModules, annotationGeneratedModule);
111	        } finally {
112	          isInitializing = false;
113	          Trace.endSection();
114	        }
115	      }
116	    };
117	  }
