119	  @Synthetic
120	  static Registry createAndInitRegistry(
121	      Glide glide,
122	      List<GlideModule> manifestModules,
123	      @Nullable AppGlideModule annotationGeneratedModule) {
124	
125	    BitmapPool bitmapPool = glide.getBitmapPool();
126	    ArrayPool arrayPool = glide.getArrayPool();
127	    Context context = glide.getGlideContext().getApplicationContext();
128	
129	    GlideExperiments experiments = glide.getGlideContext().getExperiments();
130	
131	    Registry registry = new Registry();
132	    initializeDefaults(context, registry, bitmapPool, arrayPool, experiments);
133	    initializeModules(context, glide, registry, manifestModules, annotationGeneratedModule);
134	    return registry;
135	  }
136	
137	  private static void initializeDefaults(
138	      Context context,
139	      Registry registry,
140	      BitmapPool bitmapPool,
141	      ArrayPool arrayPool,
142	      GlideExperiments experiments) {
143	    registry.register(new DefaultImageHeaderParser());
144	    // Right now we're only using this parser for HEIF images, which are only supported on OMR1+.
