3	import android.graphics.Color;
4	import android.graphics.drawable.ColorDrawable;
5	import android.graphics.drawable.Drawable;
6	import android.graphics.drawable.TransitionDrawable;
7	
8	/**
9	 * A cross fade {@link Transition} for {@link android.graphics.drawable.Drawable}s that uses an
10	 * {@link android.graphics.drawable.TransitionDrawable} to transition from an existing drawable
11	 * already visible on the target to a new drawable. If no existing drawable exists, this class can
12	 * instead fall back to a default animation that doesn't rely on {@link
13	 * android.graphics.drawable.TransitionDrawable}.
14	 */
15	public class DrawableCrossFadeTransition implements Transition<Drawable> {
16	  private final int duration;
17	  private final boolean isCrossFadeEnabled;
18	
19	  /**
20	   * @param duration The duration that the cross fade animation should run if there is something to
21	   *     cross fade from when a new {@link android.graphics.drawable.Drawable} is put.
22	   * @param isCrossFadeEnabled If {@code true}, animates the previous resource's alpha to 0 while
23	   *     animating the new resource's alpha to 100. Otherwise, only animates the new resource's
24	   *     alpha to 100 while leaving the previous resource's alpha at 100. See {@link
25	   *     TransitionDrawable#setCrossFadeEnabled(boolean)}.
26	   */
27	  // Public API.
28	  @SuppressWarnings("WeakerAccess")
29	  public DrawableCrossFadeTransition(int duration, boolean isCrossFadeEnabled) {
30	    this.duration = duration;
31	    this.isCrossFadeEnabled = isCrossFadeEnabled;
32	  }
33	
34	  /**
35	   * Animates from the previous drawable to the current drawable in one of two ways.
36	   *
37	   * <ol>
38	   *   <li>Using the default animation provided in the constructor if the previous drawable is null
39	   *   <li>Using the cross fade animation with the duration provided in the constructor if the
40	   *       previous drawable is non null
41	   * </ol>
42	   *
43	   * @param current {@inheritDoc}
44	   * @param adapter {@inheritDoc}
45	   * @return {@inheritDoc}
46	   */
47	  @Override
48	  public boolean transition(Drawable current, ViewAdapter adapter) {
49	    Drawable previous = adapter.getCurrentDrawable();
50	    if (previous == null) {
51	      previous = new ColorDrawable(Color.TRANSPARENT);
52	    }
53	    TransitionDrawable transitionDrawable =
54	        new TransitionDrawable(new Drawable[] {previous, current});
55	    transitionDrawable.setCrossFadeEnabled(isCrossFadeEnabled);
56	    transitionDrawable.startTransition(duration);
57	    adapter.setDrawable(transitionDrawable);
58	    return true;
59	  }
60	}
