125	  private boolean hasJpegMpf(@NonNull Reader reader, @NonNull ArrayPool byteArrayPool)
126	      throws IOException {
127	    if (getType(reader) != JPEG) {
128	      return false;
129	    }
130	    int app2SegmentLength = moveToApp2SegmentAndGetLength(reader);
131	    while (app2SegmentLength > 0) {
132	      byte[] app2Data = byteArrayPool.get(app2SegmentLength, byte[].class);
133	      try {
134	        boolean hasJpegMpfPreamble = hasJpegMpfPreamble(reader, app2Data, app2SegmentLength);
135	        if (hasJpegMpfPreamble) {
136	          return true;
137	        }
138	      } finally {
139	        byteArrayPool.put(app2Data);
140	      }
141	      app2SegmentLength = moveToApp2SegmentAndGetLength(reader);
142	    }
143	    if (Log.isLoggable(TAG, Log.VERBOSE)) {
144	      Log.v(
145	          TAG,
146	          "hasMpf: Failed to parse APP2 segment length, or no APP2 segment with MPF metadata not"
147	              + " found");
148	    }
149	    return false;
150	  }
