152	  @NonNull
153	  private ImageType getType(Reader reader) throws IOException {
154	    try {
155	      final int firstTwoBytes = reader.getUInt16();
156	      // JPEG.
157	      if (firstTwoBytes == EXIF_MAGIC_NUMBER) {
158	        return JPEG;
159	      }
160	
161	      final int firstThreeBytes = (firstTwoBytes << 8) | reader.getUInt8();
162	      if (firstThreeBytes == GIF_HEADER) {
163	        return GIF;
164	      }
165	
166	      final int firstFourBytes = (firstThreeBytes << 8) | reader.getUInt8();
167	      // PNG.
168	      if (firstFourBytes == PNG_HEADER) {
169	        // See: http://stackoverflow.com/questions/2057923/how-to-check-a-png-for-grayscale-alpha
170	        // -color-type
171	        reader.skip(25 - 4);
172	        try {
173	          int alpha = reader.getUInt8();
174	          // A RGB indexed PNG can also have transparency. Better safe than sorry!
175	          return alpha >= 3 ? PNG_A : PNG;
176	        } catch (Reader.EndOfFileException e) {
177	          // TODO(b/143917798): Re-enable this logging when dependent tests are fixed.
178	          // if (Log.isLoggable(TAG, Log.ERROR)) {
179	          //   Log.e(TAG, "Unexpected EOF, assuming no alpha", e);
180	          // }
181	          return PNG;
182	        }
183	      }
184	
185	      if (firstFourBytes != RIFF_HEADER) {
186	        // Check for AVIF/HEIF (reads up to 32 bytes). If it is a valid FTYP box, then the
187	        // firstFourBytes will be the box size.
188	        return sniffFtyp(reader, /* boxSize= */ firstFourBytes);
189	      }
190	
191	      // WebP (reads up to 21 bytes).
192	      // See https://developers.google.com/speed/webp/docs/riff_container for details.
193	      // Bytes 4 - 7 contain length information. Skip these.
194	      reader.skip(4);
195	      final int thirdFourBytes = (reader.getUInt16() << 16) | reader.getUInt16();
196	      if (thirdFourBytes != WEBP_HEADER) {
197	        return UNKNOWN;
198	      }
199	      final int fourthFourBytes = (reader.getUInt16() << 16) | reader.getUInt16();
200	      if ((fourthFourBytes & VP8_HEADER_MASK) != VP8_HEADER) {
201	        return UNKNOWN;
202	      }
203	      if ((fourthFourBytes & VP8_HEADER_TYPE_MASK) == VP8_HEADER_TYPE_EXTENDED) {
204	        // Skip some more length bytes and check for transparency/alpha flag.
205	        reader.skip(4);
206	        short flags = reader.getUInt8();
207	        if ((flags & WEBP_EXTENDED_ANIMATION_FLAG) != 0) {
208	          return ANIMATED_WEBP;
209	        }
210	        if ((flags & WEBP_EXTENDED_ALPHA_FLAG) != 0) {
211	          return ImageType.WEBP_A;
212	        }
213	        return ImageType.WEBP;
214	      }
215	      if ((fourthFourBytes & VP8_HEADER_TYPE_MASK) == VP8_HEADER_TYPE_LOSSLESS) {
216	        // See chromium.googlesource.com/webm/libwebp/+/master/doc/webp-lossless-bitstream-spec.txt
217	        // for more info.
218	        reader.skip(4);
219	        short flags = reader.getUInt8();
220	        return (flags & WEBP_LOSSLESS_ALPHA_FLAG) != 0 ? ImageType.WEBP_A : ImageType.WEBP;
221	      }
222	      return ImageType.WEBP;
223	    } catch (Reader.EndOfFileException e) {
224	      // TODO(b/143917798): Re-enable this logging when dependent tests are fixed.
225	      // if (Log.isLoggable(TAG, Log.ERROR)) {
226	      //   Log.e(TAG, "Unexpected EOF", e);
227	      // }
228	      return UNKNOWN;
229	    }
230	  }
231	
232	  /**
233	   * Check if the bits look like an AVIF Image. AVIF Specification:
234	   * https://aomediacodec.github.io/av1-avif/
235	   *
236	   * @return AVIF or ANIMATED_AVIF if the first few bytes look like it could be an AVIF Image or an
237	   *     animated AVIF Image respectively, UNKNOWN otherwise.
238	   */
239	  private ImageType sniffFtyp(Reader reader, int boxSize) throws IOException {
240	    int chunkType = (reader.getUInt16() << 16) | reader.getUInt16();
241	    if (chunkType != FTYP_HEADER) {
242	      return UNKNOWN;
243	    }
244	    // majorBrand.
245	    int brand = (reader.getUInt16() << 16) | reader.getUInt16();
246	    // The overall logic is that, if any of the brands are 'avis', then we can conclude immediately
247	    // that it is an animated AVIF image. Otherwise, we conclude after seeing all the brands that if
248	    // one of them is 'avif', the it is a still AVIF image.
249	    if (brand == AVIS_BRAND) {
250	      return ANIMATED_AVIF;
251	    }
252	    boolean avifBrandSeen = brand == AVIF_BRAND;
253	    boolean heifBrandSeen = isHeifBrand(brand);
254	    // Skip the minor version.
255	    reader.skip(4);
256	    // Check the first five minor brands. While there could theoretically be more than five minor
257	    // brands, it is rare in practice. This way we stop the loop from running several times on a
258	    // blob that just happened to look like an ftyp box.
259	    int sizeRemaining = boxSize - 16;
260	    if (sizeRemaining % 4 == 0) {
261	      for (int i = 0; i < 5 && sizeRemaining > 0; ++i, sizeRemaining -= 4) {
262	        brand = (reader.getUInt16() << 16) | reader.getUInt16();
263	        if (brand == AVIS_BRAND) {
264	          return ANIMATED_AVIF;
265	        } else if (brand == AVIF_BRAND) {
266	          avifBrandSeen = true;
267	        } else if (isHeifBrand(brand)) {
268	          heifBrandSeen = true;
269	        }
270	      }
271	    }
272	    if (avifBrandSeen) {
273	      return AVIF;
274	    }
275	    if (heifBrandSeen) {
276	      return HEIF;
277	    }
278	    return UNKNOWN;
279	  }
280	
281	  private static boolean isHeifBrand(int brand) {
282	    return brand == HEIC_BRAND
283	        || brand == HEIX_BRAND
284	        || brand == HEVC_BRAND
285	        || brand == HEVX_BRAND
286	        || brand == MIF1_BRAND
287	        || brand == MSF1_BRAND;
288	  }
