290	  /**
291	   * Parse the orientation from the image header. If it doesn't handle this image type (or this is
292	   * not an image) it will return a default value rather than throwing an exception.
293	   *
294	   * @return The exif orientation if present or -1 if the header couldn't be parsed or doesn't
295	   *     contain an orientation
296	   */
297	  private int getOrientation(Reader reader, ArrayPool byteArrayPool) throws IOException {
298	    try {
299	      final int magicNumber = reader.getUInt16();
300	
301	      if (!handles(magicNumber)) {
302	        if (Log.isLoggable(TAG, Log.DEBUG)) {
303	          Log.d(TAG, "Parser doesn't handle magic number: " + magicNumber);
304	        }
305	        return UNKNOWN_ORIENTATION;
306	      }
307	      int exifSegmentLength = moveToExifSegmentAndGetLength(reader);
308	      if (exifSegmentLength == -1) {
309	        if (Log.isLoggable(TAG, Log.DEBUG)) {
310	          Log.d(TAG, "Failed to parse exif segment length, or exif segment not found");
311	        }
312	        return UNKNOWN_ORIENTATION;
313	      }
314	
315	      byte[] exifData = byteArrayPool.get(exifSegmentLength, byte[].class);
316	      try {
317	        return parseExifSegment(reader, exifData, exifSegmentLength);
318	      } finally {
319	        byteArrayPool.put(exifData);
320	      }
321	    } catch (Reader.EndOfFileException e) {
322	      // TODO(b/143917798): Re-enable this logging when dependent tests are fixed.
323	      // if (Log.isLoggable(TAG, Log.ERROR)) {
324	      //   Log.e(TAG, "Unexpected EOF", e);
325	      // }
326	      return UNKNOWN_ORIENTATION;
327	    }
328	  }
329	
330	  private int parseExifSegment(Reader reader, byte[] tempArray, int exifSegmentLength)
331	      throws IOException {
332	    int read = reader.read(tempArray, exifSegmentLength);
333	    if (read != exifSegmentLength) {
334	      if (Log.isLoggable(TAG, Log.DEBUG)) {
335	        Log.d(
336	            TAG,
337	            "Unable to read exif segment data"
338	                + ", length: "
339	                + exifSegmentLength
340	                + ", actually read: "
341	                + read);
342	      }
343	      return UNKNOWN_ORIENTATION;
344	    }
345	
346	    boolean hasJpegExifPreamble = hasJpegExifPreamble(tempArray, exifSegmentLength);
347	    if (hasJpegExifPreamble) {
348	      return parseExifSegment(new RandomAccessReader(tempArray, exifSegmentLength));
349	    }
350	    if (Log.isLoggable(TAG, Log.DEBUG)) {
351	      Log.d(TAG, "Missing jpeg exif preamble");
352	    }
353	    return UNKNOWN_ORIENTATION;
354	  }
