356	  private boolean hasJpegExifPreamble(byte[] exifData, int exifSegmentLength) {
357	    return hasMatchingBytes(exifData, exifSegmentLength, JPEG_EXIF_SEGMENT_PREAMBLE_BYTES);
358	  }
359	
360	  private boolean hasMatchingBytes(byte[] bytes, int byteLength, byte[] bytesToMatch) {
361	    boolean result = bytes != null && bytesToMatch != null && byteLength > bytesToMatch.length;
362	    if (result) {
363	      for (int i = 0; i < bytesToMatch.length; i++) {
364	        if (bytes[i] != bytesToMatch[i]) {
365	          result = false;
366	          break;
367	        }
368	      }
369	    }
370	    return result;
371	  }
