374	   * Moves reader to the start of the exif segment and returns the length of the exif segment or
375	   * {@code -1} if no exif segment is found.
376	   */
377	  private int moveToExifSegmentAndGetLength(Reader reader) throws IOException {
378	    return moveToSegmentAndGetLength(reader, EXIF_SEGMENT_TYPE);
379	  }
