381	  /**
382	   * Returns whether the reader, set at the beginning of the APP2 segment past the length bytes,
383	   * contains multi-picture format (MPF) data.
384	   *
385	   * @param reader must be set at the start of an APP2 segment, past the APP2 label and length
386	   *     bytes.
387	   * @param tempArray for storing temporary array. Must be at least the size of {@code
388	   *     app2SegmentLength}.
389	   * @param app2SegmentLength the length of the APP2 segment.
390	   * @throws IOException if an EOF is reached before anything was read.
391	   */
392	  private boolean hasJpegMpfPreamble(Reader reader, byte[] tempArray, int app2SegmentLength)
393	      throws IOException {
394	    int read = reader.read(tempArray, app2SegmentLength);
395	    if (read != app2SegmentLength) {
396	      if (Log.isLoggable(TAG, Log.DEBUG)) {
397	        Log.d(
398	            TAG,
399	            "Unable to read APP2 segment data"
400	                + ", length: "
401	                + app2SegmentLength
402	                + ", actually read: "
403	                + read);
404	      }
405	      return false;
406	    }
407	    return hasMatchingBytes(tempArray, app2SegmentLength, JPEG_MPF_SEGMENT_PREAMBLE_BYTES);
408	  }
