410	  private int moveToApp2SegmentAndGetLength(Reader reader) throws IOException {
411	    return moveToSegmentAndGetLength(reader, APP2_SEGMENT_TYPE);
412	  }
413	
414	  /**
415	   * Moves reader to the start of the segment identified by the segment type (e.g., "0xE1" for APP1
416	   * and returns the length of the exif segment or {@code -1} if no segment of that type is found.
417	   */
418	  private int moveToSegmentAndGetLength(Reader reader, int requestedSegmentType)
419	      throws IOException {
420	    while (true) {
421	      short segmentId = reader.getUInt8();
422	      if (segmentId != SEGMENT_START_ID) {
423	        if (Log.isLoggable(TAG, Log.DEBUG)) {
424	          Log.d(TAG, "Unknown segmentId=" + segmentId);
425	        }
426	        return -1;
427	      }
428	
429	      short segmentType = reader.getUInt8();
430	      if (segmentType == SEGMENT_SOS) {
431	        return -1;
432	      } else if (segmentType == MARKER_EOI) {
433	        if (Log.isLoggable(TAG, Log.DEBUG)) {
434	          Log.d(TAG, "Found MARKER_EOI in " + requestedSegmentType + " segment");
435	        }
436	        return -1;
437	      }
438	
439	      int segmentLength = reader.getUInt16();
440	      // A segment includes the bytes that specify its length.
441	      int segmentContentsLength = segmentLength - 2;
442	      if (segmentType != requestedSegmentType) {
443	        long skipped = reader.skip(segmentContentsLength);
444	        if (skipped != segmentContentsLength) {
445	          if (Log.isLoggable(TAG, Log.DEBUG)) {
446	            Log.d(
447	                TAG,
448	                "Unable to skip enough data"
449	                    + ", type: "
450	                    + segmentType
451	                    + ", wanted to skip: "
452	                    + segmentContentsLength
453	                    + ", but actually skipped: "
454	                    + skipped);
455	          }
456	          return -1;
457	        }
458	      } else {
459	        return segmentContentsLength;
460	      }
461	    }
462	  }
