464	  private static int parseExifSegment(RandomAccessReader segmentData) {
465	    final int headerOffsetSize = JPEG_EXIF_SEGMENT_PREAMBLE.length();
466	
467	    short byteOrderIdentifier = segmentData.getInt16(headerOffsetSize);
468	    final ByteOrder byteOrder;
469	    switch (byteOrderIdentifier) {
470	      case MOTOROLA_TIFF_MAGIC_NUMBER:
471	        byteOrder = ByteOrder.BIG_ENDIAN;
472	        break;
473	      case INTEL_TIFF_MAGIC_NUMBER:
474	        byteOrder = ByteOrder.LITTLE_ENDIAN;
475	        break;
476	      default:
477	        if (Log.isLoggable(TAG, Log.DEBUG)) {
478	          Log.d(TAG, "Unknown endianness = " + byteOrderIdentifier);
479	        }
480	        byteOrder = ByteOrder.BIG_ENDIAN;
481	        break;
482	    }
483	
484	    segmentData.order(byteOrder);
485	
486	    int firstIfdOffset = segmentData.getInt32(headerOffsetSize + 4) + headerOffsetSize;
487	    int tagCount = segmentData.getInt16(firstIfdOffset);
488	    for (int i = 0; i < tagCount; i++) {
489	      final int tagOffset = calcTagOffset(firstIfdOffset, i);
490	
491	      final int tagType = segmentData.getInt16(tagOffset);
492	      // We only want orientation.
493	      if (tagType != ORIENTATION_TAG_TYPE) {
494	        continue;
495	      }
496	
497	      final int formatCode = segmentData.getInt16(tagOffset + 2);
498	      // 12 is max format code.
499	      if (formatCode < 1 || formatCode > 12) {
500	        if (Log.isLoggable(TAG, Log.DEBUG)) {
501	          Log.d(TAG, "Got invalid format code = " + formatCode);
502	        }
503	        continue;
504	      }
505	
506	      final int componentCount = segmentData.getInt32(tagOffset + 4);
507	      if (componentCount < 0) {
508	        if (Log.isLoggable(TAG, Log.DEBUG)) {
509	          Log.d(TAG, "Negative tiff component count");
510	        }
511	        continue;
512	      }
513	
514	      if (Log.isLoggable(TAG, Log.DEBUG)) {
515	        Log.d(
516	            TAG,
517	            "Got tagIndex="
518	                + i
519	                + " tagType="
520	                + tagType
521	                + " formatCode="
522	                + formatCode
523	                + " componentCount="
524	                + componentCount);
525	      }
526	
527	      final int byteCount = componentCount + BYTES_PER_FORMAT[formatCode];
528	      if (byteCount > 4) {
529	        if (Log.isLoggable(TAG, Log.DEBUG)) {
530	          Log.d(TAG, "Got byte count > 4, not orientation, continuing, formatCode=" + formatCode);
531	        }
532	        continue;
533	      }
534	
535	      final int tagValueOffset = tagOffset + 8;
536	      if (tagValueOffset < 0 || tagValueOffset > segmentData.length()) {
537	        if (Log.isLoggable(TAG, Log.DEBUG)) {
538	          Log.d(TAG, "Illegal tagValueOffset=" + tagValueOffset + " tagType=" + tagType);
539	        }
540	        continue;
541	      }
542	
543	      if (byteCount < 0 || tagValueOffset + byteCount > segmentData.length()) {
544	        if (Log.isLoggable(TAG, Log.DEBUG)) {
545	          Log.d(TAG, "Illegal number of bytes for TI tag data tagType=" + tagType);
546	        }
547	        continue;
548	      }
549	
550	      // assume componentCount == 1 && fmtCode == 3
551	      return segmentData.getInt16(tagValueOffset);
552	    }
553	
554	    return -1;
555	  }
556	
557	  private static int calcTagOffset(int ifdOffset, int tagIndex) {
558	    return ifdOffset + 2 + 12 * tagIndex;
559	  }
