561	  private static boolean handles(int imageMagicNumber) {
562	    return (imageMagicNumber & EXIF_MAGIC_NUMBER) == EXIF_MAGIC_NUMBER
563	        || imageMagicNumber == MOTOROLA_TIFF_MAGIC_NUMBER
564	        || imageMagicNumber == INTEL_TIFF_MAGIC_NUMBER;
565	  }
