567	  private static final class RandomAccessReader {
568	    private final ByteBuffer data;
569	
570	    RandomAccessReader(byte[] data, int length) {
571	      this.data = (ByteBuffer) ByteBuffer.wrap(data).order(ByteOrder.BIG_ENDIAN).limit(length);
572	    }
573	
574	    void order(ByteOrder byteOrder) {
575	      this.data.order(byteOrder);
576	    }
577	
578	    int length() {
579	      return data.remaining();
580	    }
581	
582	    int getInt32(int offset) {
583	      return isAvailable(offset, 4) ? data.getInt(offset) : -1;
584	    }
585	
586	    short getInt16(int offset) {
587	      return isAvailable(offset, 2) ? data.getShort(offset) : -1;
588	    }
589	
590	    private boolean isAvailable(int offset, int byteSize) {
591	      return data.remaining() - offset >= byteSize;
592	    }
593	  }
