595	  private interface Reader {
596	
597	    /**
598	     * Reads and returns a 8-bit unsigned integer.
599	     *
600	     * <p>Throws an {@link EndOfFileException} if an EOF is reached.
601	     */
602	    short getUInt8() throws IOException;
603	
604	    /**
605	     * Reads and returns a 16-bit unsigned integer.
606	     *
607	     * <p>Throws an {@link EndOfFileException} if an EOF is reached.
608	     */
609	    int getUInt16() throws IOException;
610	
611	    /**
612	     * Reads and returns a byte array.
613	     *
614	     * <p>Throws an {@link EndOfFileException} if an EOF is reached before anything was read.
615	     */
616	    int read(byte[] buffer, int byteCount) throws IOException;
617	
618	    long skip(long total) throws IOException;
619	
620	    // TODO(timurrrr): Stop inheriting from IOException, and make sure all attempts to read from
621	    //   a Reader correctly handle EOFs.
622	    final class EndOfFileException extends IOException {
623	      private static final long serialVersionUID = 1L;
624	
625	      EndOfFileException() {
626	        super("Unexpectedly reached end of a file");
627	      }
628	    }
629	  }
630	
631	  private static final class ByteBufferReader implements Reader {
632	
633	    private final ByteBuffer byteBuffer;
634	
635	    ByteBufferReader(ByteBuffer byteBuffer) {
636	      this.byteBuffer = byteBuffer;
637	      byteBuffer.order(ByteOrder.BIG_ENDIAN);
638	    }
639	
640	    @Override
641	    public short getUInt8() throws EndOfFileException {
642	      if (byteBuffer.remaining() < 1) {
643	        throw new EndOfFileException();
644	      }
645	      return (short) (byteBuffer.get() & 0xFF);
646	    }
647	
648	    @Override
649	    public int getUInt16() throws EndOfFileException {
650	      return ((int) getUInt8() << 8) | getUInt8();
651	    }
652	
653	    @Override
654	    public int read(byte[] buffer, int byteCount) {
655	      int toRead = Math.min(byteCount, byteBuffer.remaining());
656	      if (toRead == 0) {
657	        return -1;
658	      }
659	      byteBuffer.get(buffer, 0 /*dstOffset*/, toRead);
660	      return toRead;
661	    }
662	
663	    @Override
664	    public long skip(long total) {
665	      int toSkip = (int) Math.min(byteBuffer.remaining(), total);
666	      byteBuffer.position(byteBuffer.position() + toSkip);
667	      return toSkip;
668	    }
669	  }
670	
671	  private static final class StreamReader implements Reader {
672	    private final InputStream is;
673	
674	    // Motorola / big endian byte order.
675	    StreamReader(InputStream is) {
676	      this.is = is;
677	    }
678	
679	    @Override
680	    public short getUInt8() throws IOException {
681	      int readResult = is.read();
682	      if (readResult == -1) {
683	        throw new EndOfFileException();
684	      }
685	
686	      return (short) readResult;
687	    }
688	
689	    @Override
690	    public int getUInt16() throws IOException {
691	      return ((int) getUInt8() << 8) | getUInt8();
692	    }
693	
694	    @Override
695	    public int read(byte[] buffer, int byteCount) throws IOException {
696	      int numBytesRead = 0;
697	      int lastReadResult = 0;
698	      while (numBytesRead < byteCount
699	          && (lastReadResult = is.read(buffer, numBytesRead, byteCount - numBytesRead)) != -1) {
700	        numBytesRead += lastReadResult;
701	      }
702	
703	      if (numBytesRead == 0 && lastReadResult == -1) {
704	        throw new EndOfFileException();
705	      }
706	
707	      return numBytesRead;
708	    }
709	
710	    @Override
711	    public long skip(long total) throws IOException {
712	      if (total < 0) {
713	        return 0;
714	      }
715	
716	      long toSkip = total;
717	      while (toSkip > 0) {
718	        long skipped = is.skip(toSkip);
719	        if (skipped > 0) {
720	          toSkip -= skipped;
721	        } else {
722	          // Skip has no specific contract as to what happens when you reach the end of
723	          // the stream. To differentiate between temporarily not having more data and
724	          // having finished the stream, we read a single byte when we fail to skip any
725	          // amount of data.
726	          int testEofByte = is.read();
727	          if (testEofByte == -1) {
728	            break;
729	          } else {
730	            toSkip--;
731	          }
732	        }
733	      }
734	      return total - toSkip;
735	    }
736	  }
