3	import androidx.annotation.NonNull;
4	import androidx.core.util.Pools;
5	import com.bumptech.glide.util.Preconditions;
6	import com.bumptech.glide.util.Synthetic;
7	import com.bumptech.glide.util.pool.FactoryPools;
8	import com.bumptech.glide.util.pool.StateVerifier;
9	
10	/**
11	 * A resource that defers any calls to {@link Resource#recycle()} until after {@link #unlock()} is
12	 * called.
13	 *
14	 * <p>If the resource was recycled prior to {@link #unlock()}, then {@link #unlock()} will also
15	 * recycle the resource.
16	 */
17	final class LockedResource<Z> implements Resource<Z>, FactoryPools.Poolable {
18	  private static final Pools.Pool<LockedResource<?>> POOL =
19	      FactoryPools.threadSafe(20, () -> new LockedResource<Object>());
20	  private final StateVerifier stateVerifier = StateVerifier.newInstance();
21	  private Resource<Z> toWrap;
22	  private boolean isLocked;
23	  private boolean isRecycled;
24	
25	  @SuppressWarnings("unchecked")
26	  @NonNull
27	  static <Z> LockedResource<Z> obtain(Resource<Z> resource) {
28	    LockedResource<Z> result = Preconditions.checkNotNull((LockedResource<Z>) POOL.acquire());
29	    result.init(resource);
30	    return result;
31	  }
32	
33	  @SuppressWarnings("WeakerAccess")
34	  @Synthetic
35	  LockedResource() {}
36	
37	  private void init(Resource<Z> toWrap) {
38	    isRecycled = false;
39	    isLocked = true;
40	    this.toWrap = toWrap;
41	  }
42	
43	  private void release() {
44	    toWrap = null;
45	    POOL.release(this);
46	  }
47	
48	  synchronized void unlock() {
49	    stateVerifier.throwIfRecycled();
50	
51	    if (!isLocked) {
52	      throw new IllegalStateException("Already unlocked");
53	    }
54	    this.isLocked = false;
55	    if (isRecycled) {
56	      recycle();
57	    }
58	  }
59	
60	  @NonNull
61	  @Override
62	  public Class<Z> getResourceClass() {
63	    return toWrap.getResourceClass();
64	  }
65	
66	  @NonNull
67	  @Override
68	  public Z get() {
69	    return toWrap.get();
70	  }
71	
72	  @Override
73	  public int getSize() {
74	    return toWrap.getSize();
75	  }
76	
77	  @Override
78	  public synchronized void recycle() {
79	    stateVerifier.throwIfRecycled();
80	
81	    this.isRecycled = true;
82	    if (!isLocked) {
83	      toWrap.recycle();
84	      release();
85	    }
86	  }
87	
88	  @NonNull
89	  @Override
90	  public StateVerifier getVerifier() {
91	    return stateVerifier;
92	  }
93	}
