213	          loadData.fetcher,
214	          loadData.fetcher.getDataSource(),
215	          originalKey);
216	    }
217	  }
218	
219	  @SuppressWarnings("WeakerAccess")
220	  @Synthetic
221	  void onLoadFailedInternal(LoadData<?> loadData, @NonNull Exception e) {
222	    cb.onDataFetcherFailed(originalKey, e, loadData.fetcher, loadData.fetcher.getDataSource());
223	  }
224	
225	  @Override
226	  public void reschedule() {
227	    // We don't expect this to happen, although if we ever need it to we can delegate to our
228	    // callback.
229	    throw new UnsupportedOperationException();
230	  }
231	
232	  // Called from source cache generator.
233	  @Override
234	  public void onDataFetcherReady(
235	      Key sourceKey, Object data, DataFetcher<?> fetcher, DataSource dataSource, Key attemptedKey) {
236	    // This data fetcher will be loading from a File and provide the wrong data source, so override
237	    // with the data source of the original fetcher
238	    cb.onDataFetcherReady(sourceKey, data, fetcher, loadData.fetcher.getDataSource(), sourceKey);
239	  }
240	
241	  @Override
242	  public void onDataFetcherFailed(
243	      Key sourceKey, Exception e, DataFetcher<?> fetcher, DataSource dataSource) {
244	    cb.onDataFetcherFailed(sourceKey, e, fetcher, loadData.fetcher.getDataSource());
245	  }
246	}
