10	/** Compatibility methods for {@link java.lang.Runtime}. */
11	final class RuntimeCompat {
12	  private static final String TAG = "GlideRuntimeCompat";
13	  private static final String CPU_NAME_REGEX = "cpu[0-9]+";
14	  private static final String CPU_LOCATION = "/sys/devices/system/cpu/";
15	
16	  private RuntimeCompat() {
17	    // Utility class.
18	  }
19	
20	  /** Determines the number of cores available on the device. */
21	  static int availableProcessors() {
22	    int cpus = Runtime.getRuntime().availableProcessors();
23	    if (Build.VERSION.SDK_INT < 17) {
24	      cpus = Math.max(getCoreCountPre17(), cpus);
25	    }
26	    return cpus;
27	  }
28	
29	  /**
30	   * Determines the number of cores available on the device (pre-v17).
31	   *
32	   * <p>Before Jellybean, {@link Runtime#availableProcessors()} returned the number of awake cores,
33	   * which may not be the number of available cores depending on the device's current state. See
34	   * https://stackoverflow.com/a/30150409.
35	   *
36	   * @return the maximum number of processors available to the VM; never smaller than one
37	   */
38	  @SuppressWarnings("PMD")
39	  private static int getCoreCountPre17() {
40	    // We override the current ThreadPolicy to allow disk reads.
41	    // This shouldn't actually do disk-IO and accesses a device file.
42	    // See: https://github.com/bumptech/glide/issues/1170
43	    File[] cpus = null;
44	    ThreadPolicy originalPolicy = StrictMode.allowThreadDiskReads();
45	    try {
46	      File cpuInfo = new File(CPU_LOCATION);
47	      final Pattern cpuNamePattern = Pattern.compile(CPU_NAME_REGEX);
48	      cpus = cpuInfo.listFiles((file, s) -> cpuNamePattern.matcher(s).matches());
49	    } catch (Throwable t) {
50	      if (Log.isLoggable(TAG, Log.ERROR)) {
51	        Log.e(TAG, "Failed to calculate accurate cpu count", t);
52	      }
53	    } finally {
54	      StrictMode.setThreadPolicy(originalPolicy);
55	    }
56	    return Math.max(1, cpus != null ? cpus.length : 0);
57	  }
58	}
