2	
3	import android.graphics.Bitmap;
4	import android.os.Build;
5	import androidx.annotation.Nullable;
6	import androidx.annotation.RequiresApi;
7	import androidx.annotation.VisibleForTesting;
8	import com.bumptech.glide.util.Synthetic;
9	import com.bumptech.glide.util.Util;
10	import java.util.NavigableMap;
11	
12	/**
13	 * A strategy for reusing bitmaps that relies on {@link Bitmap#reconfigure(int, int,
14	 * Bitmap.Config)}.
15	 *
16	 * <p>Requires {@link Build.VERSION_CODES#KITKAT KitKat} or higher.
17	 */
18	@RequiresApi(Build.VERSION_CODES.KITKAT)
19	final class SizeStrategy implements LruPoolStrategy {
20	  private static final int MAX_SIZE_MULTIPLE = 8;
21	  private final KeyPool keyPool = new KeyPool();
22	  private final GroupedLinkedMap<Key, Bitmap> groupedMap = new GroupedLinkedMap<>();
23	  private final NavigableMap<Integer, Integer> sortedSizes = new PrettyPrintTreeMap<>();
24	
25	  @Override
26	  public void put(Bitmap bitmap) {
27	    int size = Util.getBitmapByteSize(bitmap);
28	    final Key key = keyPool.get(size);
29	
30	    groupedMap.put(key, bitmap);
31	
32	    Integer current = sortedSizes.get(key.size);
33	    sortedSizes.put(key.size, current == null ? 1 : current + 1);
34	  }
35	
36	  @Override
37	  @Nullable
38	  public Bitmap get(int width, int height, Bitmap.Config config) {
39	    final int size = Util.getBitmapByteSize(width, height, config);
40	    Key key = keyPool.get(size);
41	
42	    Integer possibleSize = sortedSizes.ceilingKey(size);
43	    if (possibleSize != null && possibleSize != size && possibleSize <= size * MAX_SIZE_MULTIPLE) {
44	      keyPool.offer(key);
45	      key = keyPool.get(possibleSize);
46	    }
47	
48	    // Do a get even if we know we don't have a bitmap so that the key moves to the front in the
49	    // lru pool
50	    final Bitmap result = groupedMap.get(key);
51	    if (result != null) {
52	      result.reconfigure(width, height, config);
53	      decrementBitmapOfSize(possibleSize);
54	    }
55	
56	    return result;
57	  }
58	
59	  @Override
60	  @Nullable
61	  public Bitmap removeLast() {
62	    Bitmap removed = groupedMap.removeLast();
63	    if (removed != null) {
64	      final int removedSize = Util.getBitmapByteSize(removed);
65	      decrementBitmapOfSize(removedSize);
66	    }
67	    return removed;
68	  }
69	
70	  private void decrementBitmapOfSize(Integer size) {
71	    Integer current = sortedSizes.get(size);
72	    if (current == 1) {
73	      sortedSizes.remove(size);
74	    } else {
75	      sortedSizes.put(size, current - 1);
76	    }
77	  }
