1	package com.bumptech.glide.load.engine.bitmap_recycle;
2	
3	import android.annotation.SuppressLint;
4	import android.annotation.TargetApi;
5	import android.content.ComponentCallbacks2;
6	import android.graphics.Bitmap;
7	import android.graphics.Color;
8	import android.os.Build;
9	import android.util.Log;
10	import androidx.annotation.NonNull;
11	import androidx.annotation.Nullable;
12	import com.bumptech.glide.util.Synthetic;
13	import java.util.Arrays;
14	import java.util.Collections;
15	import java.util.HashSet;
16	import java.util.Set;
17	
18	/**
19	 * An {@link com.bumptech.glide.load.engine.bitmap_recycle.BitmapPool} implementation that uses an
20	 * {@link com.bumptech.glide.load.engine.bitmap_recycle.LruPoolStrategy} to bucket {@link Bitmap}s
21	 * and then uses an LRU eviction policy to evict {@link android.graphics.Bitmap}s from the least
22	 * recently used bucket in order to keep the pool below a given maximum size limit.
23	 */
24	public class LruBitmapPool implements BitmapPool {
25	  private static final String TAG = "LruBitmapPool";
26	  private static final Bitmap.Config DEFAULT_CONFIG = Bitmap.Config.ARGB_8888;
27	
28	  private final LruPoolStrategy strategy;
29	  private final Set<Bitmap.Config> allowedConfigs;
30	  private final long initialMaxSize;
31	  private final BitmapTracker tracker;
32	
33	  private long maxSize;
34	  private long currentSize;
35	  private int hits;
36	  private int misses;
37	  private int puts;
38	  private int evictions;
39	
40	  // Exposed for testing only.
41	  LruBitmapPool(long maxSize, LruPoolStrategy strategy, Set<Bitmap.Config> allowedConfigs) {
42	    this.initialMaxSize = maxSize;
43	    this.maxSize = maxSize;
44	    this.strategy = strategy;
45	    this.allowedConfigs = allowedConfigs;
46	    this.tracker = new NullBitmapTracker();
47	  }
48	
49	  /**
50	   * Constructor for LruBitmapPool.
51	   *
52	   * @param maxSize The initial maximum size of the pool in bytes.
53	   */
54	  public LruBitmapPool(long maxSize) {
55	    this(maxSize, getDefaultStrategy(), getDefaultAllowedConfigs());
56	  }
57	
58	  /**
59	   * Constructor for LruBitmapPool.
60	   *
61	   * @param maxSize The initial maximum size of the pool in bytes.
62	   * @param allowedConfigs A white listed put of {@link android.graphics.Bitmap.Config} that are
63	   *     allowed to be put into the pool. Configs not in the allowed put will be rejected.
64	   */
65	  // Public API.
66	  @SuppressWarnings("unused")
67	  public LruBitmapPool(long maxSize, Set<Bitmap.Config> allowedConfigs) {
68	    this(maxSize, getDefaultStrategy(), allowedConfigs);
69	  }
70	
71	  /** Returns the number of cache hits for bitmaps in the pool. */
72	  public long hitCount() {
73	    return hits;
74	  }
75	
76	  /** Returns the number of cache misses for bitmaps in the pool. */
77	  public long missCount() {
78	    return misses;
79	  }
80	
81	  /** Returns the number of bitmaps that have been evicted from the pool. */
82	  public long evictionCount() {
83	    return evictions;
84	  }
85	
86	  /** Returns the current size of the pool in bytes. */
87	  public long getCurrentSize() {
88	    return currentSize;
89	  }
90	
91	  @Override
92	  public long getMaxSize() {
93	    return maxSize;
94	  }
95	
96	  @Override
97	  public synchronized void setSizeMultiplier(float sizeMultiplier) {
98	    maxSize = Math.round(initialMaxSize * sizeMultiplier);
99	    evict();
100	  }
101	
102	  @Override
103	  public synchronized void put(Bitmap bitmap) {
104	    if (bitmap == null) {
105	      throw new NullPointerException("Bitmap must not be null");
106	    }
107	    if (bitmap.isRecycled()) {
108	      throw new IllegalStateException("Cannot pool recycled bitmap");
109	    }
110	    if (!bitmap.isMutable()
111	        || strategy.getSize(bitmap) > maxSize
112	        || !allowedConfigs.contains(bitmap.getConfig())) {
113	      if (Log.isLoggable(TAG, Log.VERBOSE)) {
114	        Log.v(
115	            TAG,
116	            "Reject bitmap from pool"
117	                + ", bitmap: "
118	                + strategy.logBitmap(bitmap)
119	                + ", is mutable: "
120	                + bitmap.isMutable()
121	                + ", is allowed config: "
122	                + allowedConfigs.contains(bitmap.getConfig()));
123	      }
124	      bitmap.recycle();
125	      return;
126	    }
127	
128	    final int size = strategy.getSize(bitmap);
129	    strategy.put(bitmap);
130	    tracker.add(bitmap);
131	
132	    puts++;
133	    currentSize += size;
134	
135	    if (Log.isLoggable(TAG, Log.VERBOSE)) {
136	      Log.v(TAG, "Put bitmap in pool=" + strategy.logBitmap(bitmap));
137	    }
138	    dump();
139	
140	    evict();
141	  }
142	
143	  private void evict() {
144	    trimToSize(maxSize);
145	  }
146	
147	  @Override
148	  @NonNull
149	  public Bitmap get(int width, int height, Bitmap.Config config) {
150	    Bitmap result = getDirtyOrNull(width, height, config);
151	    if (result == null) {
152	      return createBitmap(width, height, config);
153	    }
154	    // Bitmaps in the pool contain random data that in some cases must be cleared for an image
155	    // to be rendered correctly. we shouldn't force all consumers to independently erase the
156	    // contents individually, so we do so here. See issue #131.
157	    result.eraseColor(Color.TRANSPARENT);
158	    return result;
159	  }
160	
161	  @NonNull
162	  @Override
163	  public Bitmap getDirty(int width, int height, Bitmap.Config config) {
164	    Bitmap result = getDirtyOrNull(width, height, config);
165	    return result != null ? result : createBitmap(width, height, config);
166	  }
167	
168	  @NonNull
169	  private static Bitmap createBitmap(int width, int height, @Nullable Bitmap.Config config) {
170	    return Bitmap.createBitmap(width, height, config != null ? config : DEFAULT_CONFIG);
171	  }
172	
173	  @TargetApi(Build.VERSION_CODES.O)
174	  private static void assertNotHardwareConfig(Bitmap.Config config) {
175	    // Avoid short circuiting on sdk int since it breaks on some versions of Android.
176	    if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) {
177	      return;
178	    }
179	
180	    if (config == Bitmap.Config.HARDWARE) {
181	      throw new IllegalArgumentException(
182	          "Cannot create a mutable Bitmap with config: "
183	              + config
184	              + ". Consider setting Downsampler#ALLOW_HARDWARE_CONFIG to false in your"
185	              + " RequestOptions and/or in GlideBuilder.setDefaultRequestOptions");
186	    }
187	  }
188	
189	  @Nullable
190	  private synchronized Bitmap getDirtyOrNull(
191	      int width, int height, @Nullable Bitmap.Config config) {
192	    assertNotHardwareConfig(config);
193	    // Config will be null for non public config types, which can lead to transformations naively
194	    // passing in null as the requested config here. See issue #194.
195	    final Bitmap result = strategy.get(width, height, config != null ? config : DEFAULT_CONFIG);
196	    if (result == null) {
197	      if (Log.isLoggable(TAG, Log.DEBUG)) {
198	        Log.d(TAG, "Missing bitmap=" + strategy.logBitmap(width, height, config));
199	      }
200	      misses++;
201	    } else {
202	      hits++;
203	      currentSize -= strategy.getSize(result);
204	      tracker.remove(result);
205	      normalize(result);
206	    }
207	    if (Log.isLoggable(TAG, Log.VERBOSE)) {
208	      Log.v(TAG, "Get bitmap=" + strategy.logBitmap(width, height, config));
209	    }
210	    dump();
211	
212	    return result;
213	  }
214	
215	  // Setting these two values provides Bitmaps that are essentially equivalent to those returned
216	  // from Bitmap.createBitmap.
217	  private static void normalize(Bitmap bitmap) {
218	    bitmap.setHasAlpha(true);
219	    maybeSetPreMultiplied(bitmap);
220	  }
221	
222	  @TargetApi(Build.VERSION_CODES.KITKAT)
223	  private static void maybeSetPreMultiplied(Bitmap bitmap) {
224	    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.KITKAT) {
225	      bitmap.setPremultiplied(true);
226	    }
227	  }
228	
229	  @Override
230	  public void clearMemory() {
231	    if (Log.isLoggable(TAG, Log.DEBUG)) {
232	      Log.d(TAG, "clearMemory");
233	    }
234	    trimToSize(0);
235	  }
236	
237	  @SuppressWarnings("checkstyle:UnnecessaryParentheses") // Readability
238	  @SuppressLint("InlinedApi")
239	  @Override
240	  public void trimMemory(int level) {
241	    if (Log.isLoggable(TAG, Log.DEBUG)) {
242	      Log.d(TAG, "trimMemory, level=" + level);
243	    }
244	    if (level >= ComponentCallbacks2.TRIM_MEMORY_BACKGROUND
245	        || (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M
246	            && level >= ComponentCallbacks2.TRIM_MEMORY_UI_HIDDEN)) {
247	      clearMemory();
248	    } else if (level >= ComponentCallbacks2.TRIM_MEMORY_UI_HIDDEN
249	        || level == ComponentCallbacks2.TRIM_MEMORY_RUNNING_CRITICAL) {
250	      trimToSize(getMaxSize() / 2);
251	    }
252	  }
253	
254	  private synchronized void trimToSize(long size) {
255	    while (currentSize > size) {
256	      final Bitmap removed = strategy.removeLast();
257	      // TODO: This shouldn't ever happen, see #331.
258	      if (removed == null) {
259	        if (Log.isLoggable(TAG, Log.WARN)) {
260	          Log.w(TAG, "Size mismatch, resetting");
261	          dumpUnchecked();
262	        }
263	        currentSize = 0;
264	        return;
265	      }
266	      tracker.remove(removed);
267	      currentSize -= strategy.getSize(removed);
268	      evictions++;
269	      if (Log.isLoggable(TAG, Log.DEBUG)) {
270	        Log.d(TAG, "Evicting bitmap=" + strategy.logBitmap(removed));
271	      }
272	      dump();
273	      removed.recycle();
274	    }
275	  }
276	
277	  private void dump() {
278	    if (Log.isLoggable(TAG, Log.VERBOSE)) {
279	      dumpUnchecked();
280	    }
281	  }
282	
283	  private void dumpUnchecked() {
284	    Log.v(
285	        TAG,
286	        "Hits="
287	            + hits
288	            + ", misses="
289	            + misses
290	            + ", puts="
291	            + puts
292	            + ", evictions="
293	            + evictions
294	            + ", currentSize="
295	            + currentSize
296	            + ", maxSize="
297	            + maxSize
298	            + "\nStrategy="
299	            + strategy);
300	  }
301	
302	  private static LruPoolStrategy getDefaultStrategy() {
303	    return Build.VERSION.SDK_INT >= Build.VERSION_CODES.KITKAT
304	        ? new SizeConfigStrategy()
305	        : new AttributeStrategy();
306	  }
307	
308	  @TargetApi(Build.VERSION_CODES.O)
309	  private static Set<Bitmap.Config> getDefaultAllowedConfigs() {
310	    Set<Bitmap.Config> configs = new HashSet<>(Arrays.asList(Bitmap.Config.values()));
311	    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.KITKAT) {
312	      // GIFs, among other types, end up with a native Bitmap config that doesn't map to a java
313	      // config and is treated as null in java code. On KitKat+ these Bitmaps can be reconfigured
314	      // and are suitable for re-use.
315	      configs.add(null);
316	    }
317	    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
318	      configs.remove(Bitmap.Config.HARDWARE);
319	    }
320	    return Collections.unmodifiableSet(configs);
321	  }
322	
323	  private interface BitmapTracker {
324	    void add(Bitmap bitmap);
325	
326	    void remove(Bitmap bitmap);
327	  }
328	
329	  @SuppressWarnings("unused")
330	  // Only used for debugging
331	  private static class ThrowingBitmapTracker implements BitmapTracker {
332	    private final Set<Bitmap> bitmaps = Collections.synchronizedSet(new HashSet<>());
333	
334	    @Override
335	    public void add(Bitmap bitmap) {
336	      if (bitmaps.contains(bitmap)) {
337	        throw new IllegalStateException(
338	            "Can't add already added bitmap: "
339	                + bitmap
340	                + " ["
341	                + bitmap.getWidth()
342	                + "x"
343	                + bitmap.getHeight()
344	                + "]");
345	      }
346	      bitmaps.add(bitmap);
347	    }
348	
349	    @Override
350	    public void remove(Bitmap bitmap) {
351	      if (!bitmaps.contains(bitmap)) {
352	        throw new IllegalStateException("Cannot remove bitmap not in tracker");
353	      }
354	      bitmaps.remove(bitmap);
355	    }
356	  }
357	
358	  private static final class NullBitmapTracker implements BitmapTracker {
359	
360	    @Synthetic
361	    NullBitmapTracker() {}
362	
363	    @Override
364	    public void add(Bitmap bitmap) {
365	      // Do nothing.
366	    }
367	
368	    @Override
369	    public void remove(Bitmap bitmap) {
370	      // Do nothing.
371	    }
372	  }
373	}
