385	    ImageType imageType = imageReader.getImageType();
386	
387	    calculateScaling(
388	        imageType,
389	        imageReader,
390	        callbacks,
391	        bitmapPool,
392	        downsampleStrategy,
393	        degreesToRotate,
394	        sourceWidth,
395	        sourceHeight,
396	        targetWidth,
397	        targetHeight,
398	        options);
399	    calculateConfig(
400	        imageReader,
401	        decodeFormat,
402	        isHardwareConfigAllowed,
403	        isExifOrientationRequired,
404	        options,
405	        targetWidth,
406	        targetHeight);
407	
408	    boolean isKitKatOrGreater = Build.VERSION.SDK_INT >= Build.VERSION_CODES.KITKAT;
