17	/**
18	 * State and constants for interacting with {@link android.graphics.Bitmap.Config#HARDWARE} on
19	 * Android O+.
20	 */
21	public final class HardwareConfigState {
22	  private static final String TAG = "HardwareConfig";
23	
24	  /**
25	   * Force the state to wait until a call to allow hardware Bitmaps to be used when they'd otherwise
26	   * be eligible to work around a framework issue pre Q that can cause a native crash when
27	   * allocating a hardware Bitmap in this specific circumstance. See b/126573603#comment12 for
28	   * details.
29	   */
30	  public static final boolean BLOCK_HARDWARE_BITMAPS_WHEN_GL_CONTEXT_MIGHT_NOT_BE_INITIALIZED =
31	      Build.VERSION.SDK_INT < Build.VERSION_CODES.Q;
32	
33	  /** Support for the hardware bitmap config was added in Android O. */
34	  @ChecksSdkIntAtLeast(api = VERSION_CODES.P)
35	  public static final boolean HARDWARE_BITMAPS_SUPPORTED =
36	      Build.VERSION.SDK_INT >= Build.VERSION_CODES.P;
37	
38	  /**
39	   * Allows us to check to make sure we're not exceeding the FD limit for a process with hardware
40	   * {@link Bitmap}s.
41	   *
42	   * <p>{@link Bitmap.Config#HARDWARE} {@link Bitmap}s require two FDs (depending on the driver).
43	   * Processes have an FD limit of 1024 (at least on O). With sufficiently small {@link Bitmap}s
44	   * and/or a sufficiently large {@link com.bumptech.glide.load.engine.cache.MemoryCache}, we can
45	   * end up with enough {@link Bitmap}s in memory that we blow through the FD limit, which causes
46	   * graphics errors, Binder errors, and a variety of crashes.
47	   *
48	   * <p>Calling list.size() should be relatively efficient (hopefully < 1ms on average) because
49	   * /proc is an in-memory FS.
50	   */
51	  private static final File FD_SIZE_LIST = new File("/proc/self/fd");
52	
53	  /**
54	   * Each FD check takes 1-2ms, so to avoid overhead, only check every N decodes. 50 is more or less
55	   * arbitrary.
56	   */
57	  private static final int MINIMUM_DECODES_BETWEEN_FD_CHECKS = 50;
58	
59	  // 20k.
60	  private static final int MAXIMUM_FDS_FOR_HARDWARE_CONFIGS_P = 20000;
61	
62	  /**
63	   * Some P devices seem to have a more O like FD count, so we'll manually reduce the number of FDs
64	   * we use for hardware bitmaps. See b/139097735.
65	   */
66	  private static final int REDUCED_MAX_FDS_FOR_HARDWARE_CONFIGS_P = 500;
67	
68	  /**
69	   * @deprecated This constant is unused and will be removed in a future version, avoid using it.
70	   */
71	  @Deprecated public static final int NO_MAX_FD_COUNT = -1;
72	
73	  private static volatile HardwareConfigState instance;
74	
75	  private final int sdkBasedMaxFdCount;
76	
77	  @GuardedBy("this")
78	  private int decodesSinceLastFdCheck;
79	
80	  @GuardedBy("this")
81	  private boolean isFdSizeBelowHardwareLimit = true;
82	
83	  /**
84	   * Only mutated on the main thread. Read by any number of background threads concurrently.
85	   *
86	   * <p>Defaults to {@code false} because we need to wait for the GL context to be initialized and
87	   * it defaults to not initialized (https://b.corp.google.com/issues/126573603#comment12).
88	   */
89	  private final AtomicBoolean isHardwareConfigAllowedByAppState = new AtomicBoolean(false);
90	
91	  public static HardwareConfigState getInstance() {
92	    if (instance == null) {
93	      synchronized (HardwareConfigState.class) {
94	        if (instance == null) {
95	          instance = new HardwareConfigState();
96	        }
97	      }
98	    }
99	    return instance;
100	  }
