107	  public void blockHardwareBitmaps() {
108	    Util.assertMainThread();
109	    isHardwareConfigAllowedByAppState.set(false);
110	  }
111	
112	  public void unblockHardwareBitmaps() {
113	    Util.assertMainThread();
114	    isHardwareConfigAllowedByAppState.set(true);
115	  }
