117	  public boolean isHardwareConfigAllowed(
118	      int targetWidth,
119	      int targetHeight,
120	      boolean isHardwareConfigAllowed,
121	      boolean isExifOrientationRequired) {
122	    if (!isHardwareConfigAllowed) {
123	      if (Log.isLoggable(TAG, Log.VERBOSE)) {
124	        Log.v(TAG, "Hardware config disallowed by caller");
125	      }
126	      return false;
127	    }
128	    if (!HARDWARE_BITMAPS_SUPPORTED) {
129	      if (Log.isLoggable(TAG, Log.VERBOSE)) {
130	        Log.v(TAG, "Hardware config disallowed by sdk");
131	      }
132	      return false;
133	    }
134	    if (areHardwareBitmapsBlockedByAppState()) {
135	      if (Log.isLoggable(TAG, Log.VERBOSE)) {
136	        Log.v(TAG, "Hardware config disallowed by app state");
137	      }
138	      return false;
139	    }
140	    if (isExifOrientationRequired) {
141	      if (Log.isLoggable(TAG, Log.VERBOSE)) {
142	        Log.v(TAG, "Hardware config disallowed because exif orientation is required");
143	      }
144	      return false;
145	    }
146	    if (targetWidth < 0 || targetHeight < 0) {
147	      if (Log.isLoggable(TAG, Log.VERBOSE)) {
148	        Log.v(TAG, "Hardware config disallowed because of invalid dimensions");
149	      }
150	      return false;
151	    }
152	    // Make sure to call isFdSizeBelowHardwareLimit last because it has side affects.
153	    if (!isFdSizeBelowHardwareLimit()) {
154	      if (Log.isLoggable(TAG, Log.VERBOSE)) {
155	        Log.v(TAG, "Hardware config disallowed because there are insufficient FDs");
156	      }
157	      return false;
158	    }
159	
160	    return true;
161	  }
