163	  private boolean areHardwareBitmapsBlockedByAppState() {
164	    return BLOCK_HARDWARE_BITMAPS_WHEN_GL_CONTEXT_MIGHT_NOT_BE_INITIALIZED
165	        && !isHardwareConfigAllowedByAppState.get();
166	  }
