213	    if (isHardwareBitmapCountReducedOnApi28ByB139097735()) {
214	      return REDUCED_MAX_FDS_FOR_HARDWARE_CONFIGS_P;
215	    }
216	    return sdkBasedMaxFdCount;
217	  }
