219	  private synchronized boolean isFdSizeBelowHardwareLimit() {
220	    if (++decodesSinceLastFdCheck >= MINIMUM_DECODES_BETWEEN_FD_CHECKS) {
221	      decodesSinceLastFdCheck = 0;
222	      int currentFds = FD_SIZE_LIST.list().length;
223	      long maxFdCount = getMaxFdCount();
224	      isFdSizeBelowHardwareLimit = currentFds < maxFdCount;
225	
226	      if (!isFdSizeBelowHardwareLimit && Log.isLoggable(Downsampler.TAG, Log.WARN)) {
227	        Log.w(
228	            Downsampler.TAG,
229	            "Excluding HARDWARE bitmap config because we're over the file descriptor limit"
230	                + ", file descriptors "
231	                + currentFds
232	                + ", limit "
233	                + maxFdCount);
