2	
3	import androidx.annotation.GuardedBy;
4	import androidx.annotation.Nullable;
5	
6	/**
7	 * Runs a single primary {@link Request} until it completes and then a fallback error request only
8	 * if the single primary request fails.
9	 */
10	public final class ErrorRequestCoordinator implements RequestCoordinator, Request {
11	
12	  private final Object requestLock;
13	  @Nullable private final RequestCoordinator parent;
14	
15	  private volatile Request primary;
16	  private volatile Request error;
17	
18	  @GuardedBy("requestLock")
19	  private RequestState primaryState = RequestState.CLEARED;
20	
21	  @GuardedBy("requestLock")
22	  private RequestState errorState = RequestState.CLEARED;
23	
24	  public ErrorRequestCoordinator(Object requestLock, @Nullable RequestCoordinator parent) {
25	    this.requestLock = requestLock;
26	    this.parent = parent;
27	  }
28	
29	  public void setRequests(Request primary, Request error) {
30	    this.primary = primary;
31	    this.error = error;
32	  }
33	
34	  @Override
35	  public void begin() {
36	    synchronized (requestLock) {
37	      if (primaryState != RequestState.RUNNING) {
38	        primaryState = RequestState.RUNNING;
39	        primary.begin();
40	      }
41	    }
42	  }
43	
44	  @Override
45	  public void clear() {
46	    synchronized (requestLock) {
47	      primaryState = RequestState.CLEARED;
48	      primary.clear();
49	      // Don't check primary's failed state here because it will have been reset by the clear call
50	      // immediately before this.
51	      if (errorState != RequestState.CLEARED) {
52	        errorState = RequestState.CLEARED;
53	        error.clear();
54	      }
55	    }
56	  }
57	
58	  @Override
59	  public void pause() {
60	    synchronized (requestLock) {
61	      if (primaryState == RequestState.RUNNING) {
62	        primaryState = RequestState.PAUSED;
63	        primary.pause();
64	      }
65	      if (errorState == RequestState.RUNNING) {
66	        errorState = RequestState.PAUSED;
67	        error.pause();
68	      }
69	    }
70	  }
71	
72	  @Override
73	  public boolean isRunning() {
74	    synchronized (requestLock) {
75	      return primaryState == RequestState.RUNNING || errorState == RequestState.RUNNING;
76	    }
77	  }
78	
79	  @Override
80	  public boolean isComplete() {
81	    synchronized (requestLock) {
82	      return primaryState == RequestState.SUCCESS || errorState == RequestState.SUCCESS;
83	    }
84	  }
85	
86	  @Override
87	  public boolean isCleared() {
88	    synchronized (requestLock) {
89	      return primaryState == RequestState.CLEARED && errorState == RequestState.CLEARED;
90	    }
91	  }
92	
93	  @Override
94	  public boolean isEquivalentTo(Request o) {
95	    if (o instanceof ErrorRequestCoordinator) {
96	      ErrorRequestCoordinator other = (ErrorRequestCoordinator) o;
97	      return primary.isEquivalentTo(other.primary) && error.isEquivalentTo(other.error);
98	    }
99	    return false;
100	  }
101	
102	  @Override
103	  public boolean canSetImage(Request request) {
104	    synchronized (requestLock) {
105	      // Only one of primary or error runs at a time, so if we've reached this point and nothing
106	      // else is broken, we should have nothing else to enforce.
107	      return parentCanSetImage();
108	    }
109	  }
110	
111	  @GuardedBy("requestLock")
112	  private boolean parentCanSetImage() {
113	    return parent == null || parent.canSetImage(this);
114	  }
115	
116	  @Override
117	  public boolean canNotifyStatusChanged(Request request) {
118	    synchronized (requestLock) {
119	      return parentCanNotifyStatusChanged() && isValidRequestForStatusChanged(request);
120	    }
121	  }
122	
123	  @Override
124	  public boolean canNotifyCleared(Request request) {
125	    synchronized (requestLock) {
126	      return parentCanNotifyCleared() && request.equals(primary);
127	    }
128	  }
129	
130	  @GuardedBy("requestLock")
131	  private boolean parentCanNotifyCleared() {
132	    return parent == null || parent.canNotifyCleared(this);
133	  }
134	
135	  @GuardedBy("requestLock")
136	  private boolean parentCanNotifyStatusChanged() {
137	    return parent == null || parent.canNotifyStatusChanged(this);
138	  }
139	
140	  @GuardedBy("requestLock")
141	  private boolean isValidRequestForStatusChanged(Request request) {
142	    if (primaryState != RequestState.FAILED) {
143	      return request.equals(primary);
144	    }
145	    return request.equals(error)
146	        // We don't want to call onLoadStarted once for the primary request and then again
147	        // if it fails and the error request starts. It's already running, so we might as well
148	        // avoid the duplicate notification by only notifying about the error state when it's
149	        // final.
150	        && (errorState == RequestState.SUCCESS || errorState == RequestState.FAILED);
151	  }
152	
153	  @Override
154	  public boolean isAnyResourceSet() {
155	    synchronized (requestLock) {
156	      return primary.isAnyResourceSet() || error.isAnyResourceSet();
157	    }
158	  }
159	
160	  @Override
161	  public void onRequestSuccess(Request request) {
162	    synchronized (requestLock) {
163	      if (request.equals(primary)) {
164	        primaryState = RequestState.SUCCESS;
165	      } else if (request.equals(error)) {
166	        errorState = RequestState.SUCCESS;
167	      }
168	      if (parent != null) {
169	        parent.onRequestSuccess(this);
170	      }
171	    }
172	  }
173	
174	  @Override
175	  public void onRequestFailed(Request request) {
176	    synchronized (requestLock) {
177	      if (!request.equals(error)) {
178	        primaryState = RequestState.FAILED;
179	        if (errorState != RequestState.RUNNING) {
180	          errorState = RequestState.RUNNING;
181	          error.begin();
182	        }
183	        return;
184	      }
185	
186	      errorState = RequestState.FAILED;
187	
188	      if (parent != null) {
189	        parent.onRequestFailed(this);
190	      }
191	    }
192	  }
193	
194	  @Override
195	  public RequestCoordinator getRoot() {
196	    synchronized (requestLock) {
197	      return parent != null ? parent.getRoot() : this;
198	    }
199	  }
200	}
