12	 * example when the user changes screens or scrolls back and forth in a list. In those cases the
13	 * user typically does not expect to see a transition. As a result, when the resource is loaded from
14	 * the memory cache this factory produces an {@link NoTransition}.
15	 */
16	// Public API.
17	@SuppressWarnings("WeakerAccess")
18	public class DrawableCrossFadeFactory implements TransitionFactory<Drawable> {
19	  private final int duration;
20	  private final boolean isCrossFadeEnabled;
21	  private DrawableCrossFadeTransition resourceTransition;
22	
23	  protected DrawableCrossFadeFactory(int duration, boolean isCrossFadeEnabled) {
24	    this.duration = duration;
25	    this.isCrossFadeEnabled = isCrossFadeEnabled;
26	  }
27	
28	  @Override
29	  public Transition<Drawable> build(DataSource dataSource, boolean isFirstResource) {
30	    return dataSource == DataSource.MEMORY_CACHE
31	        ? NoTransition.<Drawable>get()
32	        : getResourceTransition();
33	  }
34	
35	  private Transition<Drawable> getResourceTransition() {
36	    if (resourceTransition == null) {
37	      resourceTransition = new DrawableCrossFadeTransition(duration, isCrossFadeEnabled);
38	    }
39	    return resourceTransition;
40	  }
41	
42	  /** A Builder for {@link DrawableCrossFadeFactory}. */
43	  @SuppressWarnings("unused")
44	  public static class Builder {
45	    private static final int DEFAULT_DURATION_MS = 300;
46	    private final int durationMillis;
47	    private boolean isCrossFadeEnabled;
48	
49	    public Builder() {
50	      this(DEFAULT_DURATION_MS);
51	    }
52	
53	    /**
54	     * @param durationMillis The duration of the cross fade animation in milliseconds.
55	     */
56	    public Builder(int durationMillis) {
57	      this.durationMillis = durationMillis;
58	    }
59	
60	    /**
61	     * Enables or disables animating the alpha of the {@link Drawable} the cross fade will animate
62	     * from.
63	     *
64	     * <p>Defaults to {@code false}.
65	     *
66	     * @param isCrossFadeEnabled If {@code true} the previous {@link Drawable}'s alpha will be
67	     *     animated from 100 to 0 while the new {@link Drawable}'s alpha is animated from 0 to 100.
68	     *     Otherwise the previous {@link Drawable}'s alpha will remain at 100 throughout the
69	     *     animation. See {@link
70	     *     android.graphics.drawable.TransitionDrawable#setCrossFadeEnabled(boolean)}
71	     */
72	    public Builder setCrossFadeEnabled(boolean isCrossFadeEnabled) {
73	      this.isCrossFadeEnabled = isCrossFadeEnabled;
74	      return this;
75	    }
76	
77	    public DrawableCrossFadeFactory build() {
78	      return new DrawableCrossFadeFactory(durationMillis, isCrossFadeEnabled);
79	    }
80	  }
