5	/**
6	 * A {@link TransitionFactory} that produces ViewPropertyAnimations.
7	 *
8	 * @param <R> The type of the resource that will be transitioned into a view.
9	 */
10	public class ViewPropertyAnimationFactory<R> implements TransitionFactory<R> {
11	  private final ViewPropertyTransition.Animator animator;
12	  private ViewPropertyTransition<R> animation;
