14	  public ViewPropertyAnimationFactory(ViewPropertyTransition.Animator animator) {
15	    this.animator = animator;
16	  }
17	
18	  /**
19	   * Returns a new {@link Transition} for the given arguments. If isMemoryCache is {@code true} or
20	   * isFirstImage is {@code false}, returns a {@link NoTransition} and otherwise returns a new
21	   * {@link ViewPropertyTransition} for the {@link ViewPropertyTransition.Animator} provided in the
22	   * constructor.
23	   */
24	  @Override
25	  public Transition<R> build(DataSource dataSource, boolean isFirstResource) {
