8	import com.bumptech.glide.load.Key;
9	import com.bumptech.glide.load.Options;
10	import com.bumptech.glide.load.data.DataFetcher;
11	import com.bumptech.glide.load.data.DataFetcher.DataCallback;
12	import com.bumptech.glide.load.engine.GlideException;
13	import com.bumptech.glide.util.Preconditions;
14	import java.util.ArrayList;
15	import java.util.Arrays;
16	import java.util.List;
17	
18	/**
19	 * Allows attempting multiple ModelLoaders registered for a given model and data class.
20	 *
21	 * <p>TODO: we should try to find a way to remove this class. It exists to allow individual
22	 * ModelLoaders to delegate to multiple ModelLoaders without having to duplicate this logic
23	 * everywhere. We have very similar logic in the {@link
24	 * com.bumptech.glide.load.engine.DataFetcherGenerator} implementations and should try to avoid this
25	 * duplication.
26	 */
27	class MultiModelLoader<Model, Data> implements ModelLoader<Model, Data> {
28	
29	  private final List<ModelLoader<Model, Data>> modelLoaders;
30	  private final Pool<List<Throwable>> exceptionListPool;
31	
32	  MultiModelLoader(
33	      @NonNull List<ModelLoader<Model, Data>> modelLoaders,
34	      @NonNull Pool<List<Throwable>> exceptionListPool) {
35	    this.modelLoaders = modelLoaders;
36	    this.exceptionListPool = exceptionListPool;
37	  }
38	
39	  @Override
40	  public LoadData<Data> buildLoadData(
41	      @NonNull Model model, int width, int height, @NonNull Options options) {
42	    Key sourceKey = null;
43	    int size = modelLoaders.size();
44	    List<DataFetcher<Data>> fetchers = new ArrayList<>(size);
45	    //noinspection ForLoopReplaceableByForEach to improve perf
46	    for (int i = 0; i < size; i++) {
47	      ModelLoader<Model, Data> modelLoader = modelLoaders.get(i);
48	      if (modelLoader.handles(model)) {
49	        LoadData<Data> loadData = modelLoader.buildLoadData(model, width, height, options);
50	        if (loadData != null) {
51	          sourceKey = loadData.sourceKey;
52	          fetchers.add(loadData.fetcher);
53	        }
54	      }
55	    }
56	    return !fetchers.isEmpty() && sourceKey != null
57	        ? new LoadData<>(sourceKey, new MultiFetcher<>(fetchers, exceptionListPool))
58	        : null;
59	  }
60	
61	  @Override
62	  public boolean handles(@NonNull Model model) {
63	    for (ModelLoader<Model, Data> modelLoader : modelLoaders) {
64	      if (modelLoader.handles(model)) {
65	        return true;
66	      }
67	    }
68	    return false;
69	  }
70	
71	  @Override
72	  public String toString() {
73	    return "MultiModelLoader{" + "modelLoaders=" + Arrays.toString(modelLoaders.toArray()) + '}';
74	  }
75	
76	  static class MultiFetcher<Data> implements DataFetcher<Data>, DataCallback<Data> {
77	
78	    private final List<DataFetcher<Data>> fetchers;
79	    private final Pool<List<Throwable>> throwableListPool;
80	    private int currentIndex;
81	    private Priority priority;
82	    private DataCallback<? super Data> callback;
83	    @Nullable private List<Throwable> exceptions;
84	    private boolean isCancelled;
85	
86	    MultiFetcher(
87	        @NonNull List<DataFetcher<Data>> fetchers,
88	        @NonNull Pool<List<Throwable>> throwableListPool) {
89	      this.throwableListPool = throwableListPool;
90	      Preconditions.checkNotEmpty(fetchers);
91	      this.fetchers = fetchers;
92	      currentIndex = 0;
93	    }
94	
95	    @Override
96	    public void loadData(@NonNull Priority priority, @NonNull DataCallback<? super Data> callback) {
97	      this.priority = priority;
98	      this.callback = callback;
99	      exceptions = throwableListPool.acquire();
100	      fetchers.get(currentIndex).loadData(priority, this);
101	
102	      // If a race occurred where we cancelled the fetcher in cancel() and then called loadData here
103	      // immediately after, make sure that we cancel the newly started fetcher. We don't bother
104	      // checking cancelled before loadData because it's not required for correctness and would
105	      // require an unlikely race to be useful.
106	      if (isCancelled) {
107	        cancel();
108	      }
109	    }
110	
111	    @Override
112	    public void cleanup() {
113	      if (exceptions != null) {
114	        throwableListPool.release(exceptions);
115	      }
116	      exceptions = null;
117	      for (DataFetcher<Data> fetcher : fetchers) {
118	        fetcher.cleanup();
119	      }
120	    }
121	
122	    @Override
123	    public void cancel() {
124	      isCancelled = true;
125	      for (DataFetcher<Data> fetcher : fetchers) {
126	        fetcher.cancel();
127	      }
128	    }
129	
130	    @NonNull
131	    @Override
132	    public Class<Data> getDataClass() {
133	      return fetchers.get(0).getDataClass();
134	    }
135	
136	    @NonNull
137	    @Override
138	    public DataSource getDataSource() {
139	      return fetchers.get(0).getDataSource();
140	    }
141	
142	    @Override
143	    public void onDataReady(@Nullable Data data) {
144	      if (data != null) {
145	        callback.onDataReady(data);
146	      } else {
147	        startNextOrFail();
148	      }
149	    }
150	
151	    @Override
152	    public void onLoadFailed(@NonNull Exception e) {
153	      Preconditions.checkNotNull(exceptions).add(e);
154	      startNextOrFail();
155	    }
156	
157	    private void startNextOrFail() {
158	      if (isCancelled) {
159	        return;
160	      }
161	
162	      if (currentIndex < fetchers.size() - 1) {
163	        currentIndex++;
164	        loadData(priority, callback);
165	      } else {
166	        Preconditions.checkNotNull(exceptions);
167	        callback.onLoadFailed(new GlideException("Fetch failed", new ArrayList<>(exceptions)));
168	      }
169	    }
170	  }
171	}
