33	  /**
34	   * Returns {@code true} if the given experiment is enabled.
35	   *
36	   * <p>This is an experimental API, it may be removed at any point without deprecation or other
37	   * notice.
38	   */
39	  public boolean isEnabled(Class<? extends Experiment> clazz) {
40	    return experiments.containsKey(clazz);
41	  }
42	
43	  interface Experiment {}
44	
45	  static final class Builder {
46	    private final Map<Class<?>, Experiment> experiments = new HashMap<>();
47	
48	    Builder update(Experiment experiment, boolean isEnabled) {
49	      if (isEnabled) {
