3	import android.graphics.Bitmap;
4	import android.graphics.Canvas;
5	import android.graphics.drawable.Animatable;
6	import android.graphics.drawable.BitmapDrawable;
7	import android.graphics.drawable.Drawable;
8	import android.util.Log;
9	import androidx.annotation.Nullable;
10	import com.bumptech.glide.load.engine.Resource;
11	import com.bumptech.glide.load.engine.bitmap_recycle.BitmapPool;
12	import com.bumptech.glide.load.engine.bitmap_recycle.BitmapPoolAdapter;
13	import com.bumptech.glide.request.target.Target;
14	import java.util.concurrent.locks.Lock;
15	
16	final class DrawableToBitmapConverter {
17	  private static final String TAG = "DrawableToBitmap";
18	  private static final BitmapPool NO_RECYCLE_BITMAP_POOL =
19	      new BitmapPoolAdapter() {
20	        @Override
21	        public void put(Bitmap bitmap) {
22	          // Avoid calling super to avoid recycling the given Bitmap.
23	        }
24	      };
25	
26	  private DrawableToBitmapConverter() {
27	    // Utility class.
28	  }
29	
30	  @Nullable
31	  static Resource<Bitmap> convert(BitmapPool bitmapPool, Drawable drawable, int width, int height) {
32	    // Handle DrawableContainer or StateListDrawables that may contain one or more BitmapDrawables.
33	    drawable = drawable.getCurrent();
34	    Bitmap result = null;
35	    boolean isRecycleable = false;
36	    if (drawable instanceof BitmapDrawable) {
37	      result = ((BitmapDrawable) drawable).getBitmap();
38	    } else if (!(drawable instanceof Animatable)) {
39	      result = drawToBitmap(bitmapPool, drawable, width, height);
40	      // We created and drew to the Bitmap, so it's safe for us to recycle or re-use.
41	      isRecycleable = true;
42	    }
43	
44	    BitmapPool toUse = isRecycleable ? bitmapPool : NO_RECYCLE_BITMAP_POOL;
45	    return BitmapResource.obtain(result, toUse);
46	  }
47	
48	  @Nullable
49	  private static Bitmap drawToBitmap(
50	      BitmapPool bitmapPool, Drawable drawable, int width, int height) {
51	    if (width == Target.SIZE_ORIGINAL && drawable.getIntrinsicWidth() <= 0) {
52	      if (Log.isLoggable(TAG, Log.WARN)) {
53	        Log.w(
54	            TAG,
55	            "Unable to draw "
56	                + drawable
57	                + " to Bitmap with Target.SIZE_ORIGINAL because the"
58	                + " Drawable has no intrinsic width");
59	      }
60	      return null;
61	    }
62	    if (height == Target.SIZE_ORIGINAL && drawable.getIntrinsicHeight() <= 0) {
63	      if (Log.isLoggable(TAG, Log.WARN)) {
64	        Log.w(
65	            TAG,
66	            "Unable to draw "
67	                + drawable
68	                + " to Bitmap with Target.SIZE_ORIGINAL because the"
69	                + " Drawable has no intrinsic height");
70	      }
71	      return null;
72	    }
73	    int targetWidth = drawable.getIntrinsicWidth() > 0 ? drawable.getIntrinsicWidth() : width;
74	    int targetHeight = drawable.getIntrinsicHeight() > 0 ? drawable.getIntrinsicHeight() : height;
75	
76	    Lock lock = TransformationUtils.getBitmapDrawableLock();
77	    lock.lock();
78	    Bitmap result = bitmapPool.get(targetWidth, targetHeight, Bitmap.Config.ARGB_8888);
79	    try {
80	      Canvas canvas = new Canvas(result);
81	      drawable.setBounds(0, 0, targetWidth, targetHeight);
82	      drawable.draw(canvas);
83	      canvas.setBitmap(null);
84	    } finally {
85	      lock.unlock();
86	    }
87	    return result;
88	  }
89	}
