79	    @NonNull
80	    @Override
81	    public Set<RequestManager> getDescendants() {
82	      Set<RequestManager> result = new HashSet<>();
83	      getChildFragmentsRecursive(childFragmentManager, result);
84	      return result;
85	    }
86	
87	    private void getChildFragmentsRecursive(
88	        FragmentManager fragmentManager, Set<RequestManager> requestManagers) {
89	      List<Fragment> children = fragmentManager.getFragments();
90	      for (int i = 0, size = children.size(); i < size; i++) {
91	        Fragment child = children.get(i);
92	        getChildFragmentsRecursive(child.getChildFragmentManager(), requestManagers);
93	        RequestManager fromChild = getOnly(child.getLifecycle());
94	        if (fromChild != null) {
95	          requestManagers.add(fromChild);
96	        }
97	      }
98	    }
99	  }
100	}
