235	      this.context = context.getApplicationContext();
236	      this.connectivityManager = connectivityManager;
237	      this.listener = listener;
238	    }
239	
240	    @Override
241	    public boolean register() {
242	      EXECUTOR.execute(
243	          () -> {
244	            // Initialize isConnected so that we notice the first time around when there's a
245	            // broadcast.
246	            // TODO(judds): This causes a race where:
247	            // 1. Connectivity is disconnected
248	            // 2. Register is called, but punted to a background thread and not run yet
249	            // 3. Some network requiring request is started, runs and fails due to connectivity
250	            // 4. Connectivity is re-established
251	            // 5. This code finally runs on the background thread.
252	            // In step 5, we'll think that we're currently connected and won't trigger a retry for
253	            // any previously failed requests.
254	            // In the long run it might be nice to define some explicit initialization step for
255	            // Glide where we do this and other expensive things on a background thread prior to
256	            // starting the first request. For now it seems better to just accept this race than
