288	            }
289	            isRegistered = false;
290	            context.unregisterReceiver(connectivityReceiver);
291	          });
292	    }
293	
294	    @Synthetic
295	    void onConnectivityChange() {
296	      EXECUTOR.execute(
297	          () -> {
298	            boolean wasConnected = isConnected;
299	            isConnected = isConnected();
300	            if (wasConnected != isConnected) {
