306	          });
307	    }
308	
309	    // Pass through the boolean because the instance variable could change while we're waiting for
310	    // the runnable to be executed on the main thread.
311	    @Synthetic
312	    void notifyChangeOnUiThread(final boolean isConnected) {
313	      Util.postOnUiThread(() -> listener.onConnectivityChanged(isConnected));
