10	import java.io.ByteArrayInputStream;
11	import java.io.IOException;
12	import java.io.InputStream;
13	
14	/**
15	 * A simple model loader for loading data from a Data URL String.
16	 *
17	 * <p>Data URIs use the "data" scheme.
18	 *
19	 * <p>See http://www.ietf.org/rfc/rfc2397.txt for a complete description of the 'data' URL scheme.
20	 *
21	 * <p>Briefly, a 'data' URL has the form:
22	 *
23	 * <pre>data:[mediatype][;base64],some_data</pre>
24	 *
25	 * @param <Model> The type of Model that we can retrieve data for, e.g. {@link String}.
26	 * @param <Data> The type of data that can be opened, e.g. {@link InputStream}.
27	 */
28	public final class DataUrlLoader<Model, Data> implements ModelLoader<Model, Data> {
29	
30	  private static final String DATA_SCHEME_IMAGE = "data:image";
31	  private static final String BASE64_TAG = ";base64";
32	  private final DataDecoder<Data> dataDecoder;
33	
34	  // Public API.
35	  @SuppressWarnings("WeakerAccess")
36	  public DataUrlLoader(DataDecoder<Data> dataDecoder) {
37	    this.dataDecoder = dataDecoder;
38	  }
39	
40	  @Override
41	  public LoadData<Data> buildLoadData(
42	      @NonNull Model model, int width, int height, @NonNull Options options) {
43	    return new LoadData<>(
44	        new ObjectKey(model), new DataUriFetcher<>(model.toString(), dataDecoder));
45	  }
46	
47	  @Override
48	  public boolean handles(@NonNull Model model) {
49	    // We expect Model to be a Uri or a String, both of which implement toString() efficiently. We
50	    // should reconsider this implementation before adding any new Model types.
51	    return model.toString().startsWith(DATA_SCHEME_IMAGE);
52	  }
53	
54	  /**
55	   * Allows decoding a specific type of data from a Data URL String.
56	   *
57	   * @param <Data> The type of data that can be opened.
58	   */
59	  public interface DataDecoder<Data> {
60	
61	    Data decode(String uri) throws IllegalArgumentException;
62	
63	    void close(Data data) throws IOException;
64	
65	    Class<Data> getDataClass();
66	  }
67	
68	  private static final class DataUriFetcher<Data> implements DataFetcher<Data> {
69	
70	    private final String dataUri;
71	    private final DataDecoder<Data> reader;
72	    private Data data;
73	
74	    DataUriFetcher(String dataUri, DataDecoder<Data> reader) {
75	      this.dataUri = dataUri;
76	      this.reader = reader;
77	    }
78	
79	    @Override
80	    public void loadData(@NonNull Priority priority, @NonNull DataCallback<? super Data> callback) {
81	      try {
82	        data = reader.decode(dataUri);
83	        callback.onDataReady(data);
84	      } catch (IllegalArgumentException e) {
85	        callback.onLoadFailed(e);
86	      }
87	    }
88	
89	    @Override
90	    public void cleanup() {
91	      try {
92	        reader.close(data);
93	      } catch (IOException e) {
94	        // Ignored.
95	      }
96	    }
97	
98	    @Override
99	    public void cancel() {
100	      // Do nothing.
101	    }
102	
103	    @NonNull
104	    @Override
105	    public Class<Data> getDataClass() {
106	      return reader.getDataClass();
107	    }
108	
109	    @NonNull
110	    @Override
111	    public DataSource getDataSource() {
112	      return DataSource.LOCAL;
113	    }
114	  }
115	
116	  /**
117	   * Factory for loading {@link InputStream}s from data uris.
118	   *
119	   * @param <Model> The type of Model we can obtain data for, e.g. String.
120	   */
121	  public static final class StreamFactory<Model> implements ModelLoaderFactory<Model, InputStream> {
122	
123	    private final DataDecoder<InputStream> opener;
124	
125	    public StreamFactory() {
126	      opener =
127	          new DataDecoder<InputStream>() {
128	            @Override
129	            public InputStream decode(String url) {
130	              if (!url.startsWith(DATA_SCHEME_IMAGE)) {
131	                throw new IllegalArgumentException("Not a valid image data URL.");
132	              }
133	
134	              int commaIndex = url.indexOf(',');
135	              if (commaIndex == -1) {
136	                throw new IllegalArgumentException("Missing comma in data URL.");
137	              }
138	
139	              String beforeComma = url.substring(0, commaIndex);
140	              if (!beforeComma.endsWith(BASE64_TAG)) {
141	                throw new IllegalArgumentException("Not a base64 image data URL.");
142	              }
143	
144	              String afterComma = url.substring(commaIndex + 1);
145	              byte[] bytes = Base64.decode(afterComma, Base64.DEFAULT);
146	
147	              return new ByteArrayInputStream(bytes);
148	            }
149	
150	            @Override
151	            public void close(InputStream inputStream) throws IOException {
152	              inputStream.close();
153	            }
154	
155	            @Override
156	            public Class<InputStream> getDataClass() {
157	              return InputStream.class;
158	            }
159	          };
160	    }
161	
162	    @NonNull
163	    @Override
164	    public ModelLoader<Model, InputStream> build(@NonNull MultiModelLoaderFactory multiFactory) {
165	      return new DataUrlLoader<>(opener);
166	    }
167	
168	    @Override
169	    public void teardown() {
170	      // Do nothing.
171	    }
172	  }
173	}
