3	import android.app.Activity;
4	import android.os.Build;
5	import android.view.View;
6	import android.view.ViewTreeObserver;
7	import android.view.ViewTreeObserver.OnDrawListener;
8	import androidx.annotation.RequiresApi;
9	import com.bumptech.glide.load.resource.bitmap.HardwareConfigState;
10	import com.bumptech.glide.util.Synthetic;
11	import com.bumptech.glide.util.Util;
12	import java.util.Collections;
13	import java.util.Set;
14	import java.util.WeakHashMap;
15	
16	@RequiresApi(Build.VERSION_CODES.O)
17	final class FirstFrameWaiter implements FrameWaiter {
18	  @Synthetic
19	  final Set<Activity> pendingActivities =
20	      Collections.newSetFromMap(new WeakHashMap<Activity, Boolean>());
21	
22	  @Synthetic volatile boolean isFirstFrameSet;
23	
24	  @Override
25	  public void registerSelf(Activity activity) {
26	    // It's possible we'll create a few of these, but it's not particularly expensive to do so and
27	    // we'd rather work around any edge cases that might prevent the first Activity we listen to
28	    // from firing our callback ever.
29	    if (isFirstFrameSet) {
30	      return;
31	    }
32	    if (!pendingActivities.add(activity)) {
33	      return;
34	    }
35	
36	    final View view = activity.getWindow().getDecorView();
37	    ViewTreeObserver viewTreeObserver = view.getViewTreeObserver();
38	    viewTreeObserver.addOnDrawListener(
39	        new OnDrawListener() {
40	          @Override
41	          public void onDraw() {
42	            // We can't remove the listener during onDraw, so always post the removal to the UI
43	            // thread, even if the first frame may already be set before our listener goes off.
44	            final OnDrawListener listener = this;
45	            Util.postOnUiThread(
46	                () -> {
47	                  HardwareConfigState.getInstance().unblockHardwareBitmaps();
48	                  isFirstFrameSet = true;
49	                  removeListener(view, listener);
50	                  pendingActivities.clear();
51	                });
52	          }
53	        });
54	  }
55	
56	  @Synthetic
57	  static void removeListener(View view, OnDrawListener listener) {
58	    // The original ViewTreeObserver might be merged into a new one and be dead.
59	    // Since we have to handle that case anyway, We might as well always just
60	    // obtain the current observer and use a single code path.
61	    // We also have to wait to remove this because we're being called in onDraw.
62	    ViewTreeObserver currentViewTreeObserver = view.getViewTreeObserver();
63	    currentViewTreeObserver.removeOnDrawListener(listener);
64	  }
65	}
