15	/**
16	 * A class that generates and caches safe and unique string file names from {@link
17	 * com.bumptech.glide.load.Key}s.
18	 */
19	// Public API.
20	@SuppressWarnings("WeakerAccess")
21	public class SafeKeyGenerator {
22	  private final LruCache<Key, String> loadIdToSafeHash = new LruCache<>(1000);
23	  private final Pools.Pool<PoolableDigestContainer> digestPool =
24	      FactoryPools.threadSafe(
25	          10,
26	          () -> {
27	            try {
28	              return new PoolableDigestContainer(MessageDigest.getInstance("SHA-256"));
29	            } catch (NoSuchAlgorithmException e) {
30	              throw new RuntimeException(e);
31	            }
32	          });
33	
34	  public String getSafeKey(Key key) {
35	    String safeKey;
36	    synchronized (loadIdToSafeHash) {
37	      safeKey = loadIdToSafeHash.get(key);
38	    }
39	    if (safeKey == null) {
40	      safeKey = calculateHexStringDigest(key);
41	    }
42	    synchronized (loadIdToSafeHash) {
43	      loadIdToSafeHash.put(key, safeKey);
44	    }
45	    return safeKey;
46	  }
47	
48	  private String calculateHexStringDigest(Key key) {
49	    PoolableDigestContainer container = Preconditions.checkNotNull(digestPool.acquire());
50	    try {
51	      key.updateDiskCacheKey(container.messageDigest);
52	      // calling digest() will automatically reset()
53	      return Util.sha256BytesToHex(container.messageDigest.digest());
54	    } finally {
55	      digestPool.release(container);
56	    }
57	  }
58	
59	  private static final class PoolableDigestContainer implements FactoryPools.Poolable {
60	
61	    @Synthetic final MessageDigest messageDigest;
62	    private final StateVerifier stateVerifier = StateVerifier.newInstance();
63	
64	    PoolableDigestContainer(MessageDigest messageDigest) {
65	      this.messageDigest = messageDigest;
66	    }
67	
68	    @NonNull
69	    @Override
70	    public StateVerifier getVerifier() {
71	      return stateVerifier;
72	    }
73	  }
74	}
