3	import android.annotation.TargetApi;
4	import android.graphics.Bitmap;
5	import android.graphics.BitmapFactory;
6	import android.os.Build;
7	import android.os.Build.VERSION_CODES;
8	import android.util.Log;
9	import androidx.annotation.ChecksSdkIntAtLeast;
10	import androidx.annotation.GuardedBy;
11	import androidx.annotation.VisibleForTesting;
12	import com.bumptech.glide.util.Util;
13	import java.io.File;
14	import java.util.Arrays;
15	import java.util.concurrent.atomic.AtomicBoolean;
16	
17	/**
18	 * State and constants for interacting with {@link android.graphics.Bitmap.Config#HARDWARE} on
19	 * Android O+.
20	 */
21	public final class HardwareConfigState {
22	  private static final String TAG = "HardwareConfig";
23	
24	  /**
25	   * Force the state to wait until a call to allow hardware Bitmaps to be used when they'd otherwise
26	   * be eligible to work around a framework issue pre Q that can cause a native crash when
27	   * allocating a hardware Bitmap in this specific circumstance. See b/126573603#comment12 for
28	   * details.
29	   */
30	  public static final boolean BLOCK_HARDWARE_BITMAPS_WHEN_GL_CONTEXT_MIGHT_NOT_BE_INITIALIZED =
31	      Build.VERSION.SDK_INT < Build.VERSION_CODES.Q;
32	
33	  /** Support for the hardware bitmap config was added in Android O. */
34	  @ChecksSdkIntAtLeast(api = VERSION_CODES.P)
35	  public static final boolean HARDWARE_BITMAPS_SUPPORTED =
36	      Build.VERSION.SDK_INT >= Build.VERSION_CODES.P;
37	
38	  /**
39	   * Allows us to check to make sure we're not exceeding the FD limit for a process with hardware
40	   * {@link Bitmap}s.
41	   *
42	   * <p>{@link Bitmap.Config#HARDWARE} {@link Bitmap}s require two FDs (depending on the driver).
43	   * Processes have an FD limit of 1024 (at least on O). With sufficiently small {@link Bitmap}s
44	   * and/or a sufficiently large {@link com.bumptech.glide.load.engine.cache.MemoryCache}, we can
45	   * end up with enough {@link Bitmap}s in memory that we blow through the FD limit, which causes
46	   * graphics errors, Binder errors, and a variety of crashes.
47	   *
48	   * <p>Calling list.size() should be relatively efficient (hopefully < 1ms on average) because
49	   * /proc is an in-memory FS.
50	   */
51	  private static final File FD_SIZE_LIST = new File("/proc/self/fd");
52	
53	  /**
54	   * Each FD check takes 1-2ms, so to avoid overhead, only check every N decodes. 50 is more or less
55	   * arbitrary.
56	   */
57	  private static final int MINIMUM_DECODES_BETWEEN_FD_CHECKS = 50;
58	
59	  // 20k.
60	  private static final int MAXIMUM_FDS_FOR_HARDWARE_CONFIGS_P = 20000;
61	
62	  /**
63	   * Some P devices seem to have a more O like FD count, so we'll manually reduce the number of FDs
64	   * we use for hardware bitmaps. See b/139097735.
65	   */
66	  private static final int REDUCED_MAX_FDS_FOR_HARDWARE_CONFIGS_P = 500;
67	
68	  /**
69	   * @deprecated This constant is unused and will be removed in a future version, avoid using it.
70	   */
71	  @Deprecated public static final int NO_MAX_FD_COUNT = -1;
72	
73	  private static volatile HardwareConfigState instance;
74	
75	  private final int sdkBasedMaxFdCount;
76	
77	  @GuardedBy("this")
78	  private int decodesSinceLastFdCheck;
79	
80	  @GuardedBy("this")
81	  private boolean isFdSizeBelowHardwareLimit = true;
82	
83	  /**
84	   * Only mutated on the main thread. Read by any number of background threads concurrently.
85	   *
86	   * <p>Defaults to {@code false} because we need to wait for the GL context to be initialized and
87	   * it defaults to not initialized (https://b.corp.google.com/issues/126573603#comment12).
88	   */
89	  private final AtomicBoolean isHardwareConfigAllowedByAppState = new AtomicBoolean(false);
90	
91	  public static HardwareConfigState getInstance() {
92	    if (instance == null) {
93	      synchronized (HardwareConfigState.class) {
94	        if (instance == null) {
95	          instance = new HardwareConfigState();
96	        }
97	      }
98	    }
99	    return instance;
100	  }
101	
102	  @VisibleForTesting
103	  HardwareConfigState() {
104	    sdkBasedMaxFdCount = MAXIMUM_FDS_FOR_HARDWARE_CONFIGS_P;
105	  }
106	
107	  public void blockHardwareBitmaps() {
108	    Util.assertMainThread();
109	    isHardwareConfigAllowedByAppState.set(false);
110	  }
111	
112	  public void unblockHardwareBitmaps() {
113	    Util.assertMainThread();
114	    isHardwareConfigAllowedByAppState.set(true);
115	  }
116	
117	  public boolean isHardwareConfigAllowed(
118	      int targetWidth,
119	      int targetHeight,
120	      boolean isHardwareConfigAllowed,
121	      boolean isExifOrientationRequired) {
122	    if (!isHardwareConfigAllowed) {
123	      if (Log.isLoggable(TAG, Log.VERBOSE)) {
124	        Log.v(TAG, "Hardware config disallowed by caller");
125	      }
126	      return false;
127	    }
128	    if (!HARDWARE_BITMAPS_SUPPORTED) {
129	      if (Log.isLoggable(TAG, Log.VERBOSE)) {
130	        Log.v(TAG, "Hardware config disallowed by sdk");
131	      }
132	      return false;
133	    }
134	    if (areHardwareBitmapsBlockedByAppState()) {
135	      if (Log.isLoggable(TAG, Log.VERBOSE)) {
136	        Log.v(TAG, "Hardware config disallowed by app state");
137	      }
138	      return false;
139	    }
140	    if (isExifOrientationRequired) {
141	      if (Log.isLoggable(TAG, Log.VERBOSE)) {
142	        Log.v(TAG, "Hardware config disallowed because exif orientation is required");
143	      }
144	      return false;
145	    }
146	    if (targetWidth < 0 || targetHeight < 0) {
147	      if (Log.isLoggable(TAG, Log.VERBOSE)) {
148	        Log.v(TAG, "Hardware config disallowed because of invalid dimensions");
149	      }
150	      return false;
151	    }
152	    // Make sure to call isFdSizeBelowHardwareLimit last because it has side affects.
153	    if (!isFdSizeBelowHardwareLimit()) {
154	      if (Log.isLoggable(TAG, Log.VERBOSE)) {
155	        Log.v(TAG, "Hardware config disallowed because there are insufficient FDs");
156	      }
157	      return false;
158	    }
159	
160	    return true;
161	  }
162	
163	  private boolean areHardwareBitmapsBlockedByAppState() {
164	    return BLOCK_HARDWARE_BITMAPS_WHEN_GL_CONTEXT_MIGHT_NOT_BE_INITIALIZED
165	        && !isHardwareConfigAllowedByAppState.get();
166	  }
167	
168	  @TargetApi(Build.VERSION_CODES.O)
169	  boolean setHardwareConfigIfAllowed(
170	      int targetWidth,
171	      int targetHeight,
172	      BitmapFactory.Options optionsWithScaling,
173	      boolean isHardwareConfigAllowed,
174	      boolean isExifOrientationRequired) {
175	    boolean result =
176	        isHardwareConfigAllowed(
177	            targetWidth, targetHeight, isHardwareConfigAllowed, isExifOrientationRequired);
178	    if (result) {
179	      optionsWithScaling.inPreferredConfig = Bitmap.Config.HARDWARE;
180	      optionsWithScaling.inMutable = false;
181	    }
182	    return result;
183	  }
184	
185	  private static boolean isHardwareBitmapCountReducedOnApi28ByB139097735() {
186	    if (Build.VERSION.SDK_INT != Build.VERSION_CODES.P) {
187	      return false;
188	    }
189	    for (String prefixOrModelName :
190	        Arrays.asList(
191	            "GM1900",
192	            "GM1901",
193	            "GM1903",
194	            "GM1911",
195	            "GM1915",
196	            "ONEPLUS A3000",
197	            "ONEPLUS A3010",
198	            "ONEPLUS A5010",
199	            "ONEPLUS A5000",
200	            "ONEPLUS A3003",
201	            "ONEPLUS A6000",
202	            "ONEPLUS A6003",
203	            "ONEPLUS A6010",
204	            "ONEPLUS A6013")) {
205	      if (Build.MODEL.startsWith(prefixOrModelName)) {
206	        return true;
207	      }
208	    }
209	    return false;
210	  }
211	
212	  private int getMaxFdCount() {
213	    if (isHardwareBitmapCountReducedOnApi28ByB139097735()) {
214	      return REDUCED_MAX_FDS_FOR_HARDWARE_CONFIGS_P;
215	    }
216	    return sdkBasedMaxFdCount;
217	  }
218	
219	  private synchronized boolean isFdSizeBelowHardwareLimit() {
220	    if (++decodesSinceLastFdCheck >= MINIMUM_DECODES_BETWEEN_FD_CHECKS) {
221	      decodesSinceLastFdCheck = 0;
222	      int currentFds = FD_SIZE_LIST.list().length;
223	      long maxFdCount = getMaxFdCount();
224	      isFdSizeBelowHardwareLimit = currentFds < maxFdCount;
225	
226	      if (!isFdSizeBelowHardwareLimit && Log.isLoggable(Downsampler.TAG, Log.WARN)) {
227	        Log.w(
228	            Downsampler.TAG,
229	            "Excluding HARDWARE bitmap config because we're over the file descriptor limit"
230	                + ", file descriptors "
231	                + currentFds
232	                + ", limit "
233	                + maxFdCount);
234	      }
235	    }
236	
237	    return isFdSizeBelowHardwareLimit;
238	  }
239	}
