33	/**
34	 * Decodes video data to Bitmaps from {@link ParcelFileDescriptor}s and {@link
35	 * AssetFileDescriptor}s.
36	 *
37	 * @param <T> The type of data, currently either {@link ParcelFileDescriptor} or {@link
38	 *     AssetFileDescriptor}.
39	 */
40	public class VideoDecoder<T> implements ResourceDecoder<T, Bitmap> {
41	  private static final String TAG = "VideoDecoder";
42	
43	  /**
44	   * A constant indicating we should use whatever frame we consider best, frequently not the first
45	   * frame.
46	   */
47	  public static final long DEFAULT_FRAME = -1;
48	
49	  /** Matches the behavior of {@link MediaMetadataRetriever#getFrameAtTime(long)}. */
50	  @VisibleForTesting
51	  static final int DEFAULT_FRAME_OPTION = MediaMetadataRetriever.OPTION_CLOSEST_SYNC;
52	
53	  /**
54	   * A long indicating the time position (in microseconds) of the target frame which will be
55	   * retrieved. {@link android.media.MediaMetadataRetriever#getFrameAtTime(long)} is used to extract
56	   * the video frame.
57	   *
58	   * <p>When retrieving the frame at the given time position, there is no guarantee that the data
59	   * source has a frame located at the position. When this happens, a frame nearby will be returned.
60	   * If the long is negative, time position and option will ignored, and any frame that the
61	   * implementation considers as representative may be returned.
62	   */
63	  public static final Option<Long> TARGET_FRAME =
64	      Option.disk(
65	          "com.bumptech.glide.load.resource.bitmap.VideoBitmapDecode.TargetFrame",
66	          DEFAULT_FRAME,
67	          new Option.CacheKeyUpdater<Long>() {
68	            private final ByteBuffer buffer = ByteBuffer.allocate(Long.SIZE / Byte.SIZE);
69	
70	            @Override
71	            public void update(
72	                @NonNull byte[] keyBytes,
73	                @NonNull Long value,
74	                @NonNull MessageDigest messageDigest) {
75	              messageDigest.update(keyBytes);
76	              synchronized (buffer) {
77	                buffer.position(0);
78	                messageDigest.update(buffer.putLong(value).array());
79	              }
80	            }
81	          });
82	
83	  /**
84	   * An integer indicating the frame option used to retrieve a target frame.
85	   *
86	   * <p>This option will be ignored if {@link #TARGET_FRAME} is not set or is set to {@link
87	   * #DEFAULT_FRAME}.
88	   *
89	   * @see MediaMetadataRetriever#getFrameAtTime(long, int)
90	   */
91	  // Public API.
92	  @SuppressWarnings("WeakerAccess")
93	  public static final Option<Integer> FRAME_OPTION =
94	      Option.disk(
95	          "com.bumptech.glide.load.resource.bitmap.VideoBitmapDecode.FrameOption",
96	          /* defaultValue= */ MediaMetadataRetriever.OPTION_CLOSEST_SYNC,
97	          new Option.CacheKeyUpdater<Integer>() {
98	            private final ByteBuffer buffer = ByteBuffer.allocate(Integer.SIZE / Byte.SIZE);
99	
100	            @Override
101	            public void update(
102	                @NonNull byte[] keyBytes,
103	                @NonNull Integer value,
104	                @NonNull MessageDigest messageDigest) {
105	              //noinspection ConstantConditions public API, people could have been doing it wrong
106	              if (value == null) {
107	                return;
108	              }
109	              messageDigest.update(keyBytes);
110	              synchronized (buffer) {
111	                buffer.position(0);
112	                messageDigest.update(buffer.putInt(value).array());
113	              }
114	            }
115	          });
116	
117	  private static final MediaMetadataRetrieverFactory DEFAULT_FACTORY =
118	      new MediaMetadataRetrieverFactory();
119	
120	  /**
121	   * List of Pixel Android T build id prefixes missing a fix for HDR video with 180 deg rotations
122	   * having doubly-rotated thumbnails.
123	   *
124	   * <p>More recent Android T builds should have the fix.
125	   */
126	  private static final List<String> PIXEL_T_BUILD_ID_PREFIXES_REQUIRING_HDR_180_ROTATION_FIX =
127	      Collections.unmodifiableList(Arrays.asList("TP1A", "TD1A.220804.031"));
128	
129	  private static final String WEBM_MIME_TYPE = "video/webm";
130	
131	  private final MediaInitializer<T> initializer;
132	  private final BitmapPool bitmapPool;
133	  private final MediaMetadataRetrieverFactory factory;
134	
135	  @RequiresApi(Build.VERSION_CODES.JELLY_BEAN)
136	  public static ResourceDecoder<AssetFileDescriptor, Bitmap> asset(BitmapPool bitmapPool) {
137	    return new VideoDecoder<>(bitmapPool, new AssetFileDescriptorInitializer());
138	  }
