153	  @VisibleForTesting
154	  VideoDecoder(
155	      BitmapPool bitmapPool,
156	      MediaInitializer<T> initializer,
157	      MediaMetadataRetrieverFactory factory) {
158	    this.bitmapPool = bitmapPool;
159	    this.initializer = initializer;
160	    this.factory = factory;
