213	  @Nullable
214	  private Bitmap decodeFrame(
215	      @NonNull T resource,
216	      MediaMetadataRetriever mediaMetadataRetriever,
217	      long frameTimeMicros,
218	      int frameOption,
219	      int outWidth,
220	      int outHeight,
221	      DownsampleStrategy strategy) {
222	    if (isUnsupportedFormat(resource, mediaMetadataRetriever)) {
223	      throw new IllegalStateException("Cannot decode VP8 video on CrOS.");
224	    }
225	
226	    Bitmap result = null;
227	    // Arguably we should handle the case where just width or just height is set to
228	    // Target.SIZE_ORIGINAL. Up to and including OMR1, MediaMetadataRetriever defaults to setting
229	    // the dimensions to the display width and height if they aren't specified (ie
230	    // getScaledFrameAtTime is not used). Given that this is an optimization only if
231	    // Target.SIZE_ORIGINAL is not used and not using getScaledFrameAtTime ever would match the
232	    // behavior of Glide in all versions of Android prior to OMR1, it's probably fine for now.
233	    if (Build.VERSION.SDK_INT >= VERSION_CODES.O_MR1
234	        && outWidth != Target.SIZE_ORIGINAL
235	        && outHeight != Target.SIZE_ORIGINAL
236	        && strategy != DownsampleStrategy.NONE) {
237	      result =
238	          decodeScaledFrame(
239	              mediaMetadataRetriever, frameTimeMicros, frameOption, outWidth, outHeight, strategy);
240	    }
241	
242	    if (result == null) {
243	      result = decodeOriginalFrame(mediaMetadataRetriever, frameTimeMicros, frameOption);
244	    }
245	
246	    // MediaMetadataRetriever has a bug where HDR videos with 180 deg rotations are rotated twice,
247	    // causing the output frame to appear upside. This needs to be corrected for all versions of
248	    // Android until a platform fix lands.
249	    result = correctHdr180DegVideoFrameOrientation(mediaMetadataRetriever, result);
250	
251	    // Throwing an exception works better in our error logging than returning null. It shouldn't
252	    // be expensive because video decoders are attempted after image loads. Video errors are often
253	    // logged by the framework, so we can also use this error to suggest callers look for the
254	    // appropriate tags in adb.
255	    if (result == null) {
256	      throw new VideoDecoderException();
257	    }
258	
259	    return result;
260	  }
261	
262	  /**
263	   * Corrects the orientation of a bitmap extracted from an HDR video with a 180 degree rotation
264	   * angle.
265	   *
266	   * <p>This method will only return a rotated bitmap instead of the input bitmap if
267	   *
268	   * <ul>
269	   *   <li>The Android SDK level is >= R && < T OR the build id is one of T builds without the
270	   *       platform fix.
271	   *   <li>The video has a color transfer function with an HLG or ST2084 (PQ) transfer function.
272	   *   <li>The video has a color standard of BT.2020.
273	   *   <li>The video has a rotation angle of +/- 180 degrees.
274	   * </ul>
275	   */
276	  @TargetApi(Build.VERSION_CODES.R)
277	  private static Bitmap correctHdr180DegVideoFrameOrientation(
278	      MediaMetadataRetriever mediaMetadataRetriever, Bitmap frame) {
279	    if (!isHdr180RotationFixRequired()) {
280	      return frame;
281	    }
282	    boolean requiresHdr180RotationFix = false;
283	    try {
284	      if (isHDR(mediaMetadataRetriever)) {
285	        String rotationString =
286	            mediaMetadataRetriever.extractMetadata(
287	                MediaMetadataRetriever.METADATA_KEY_VIDEO_ROTATION);
288	        int rotation = Integer.parseInt(rotationString);
289	        requiresHdr180RotationFix = Math.abs(rotation) == 180;
290	      }
291	    } catch (NumberFormatException e) {
292	      if (Log.isLoggable(TAG, Log.DEBUG)) {
293	        Log.d(TAG, "Exception trying to extract HDR transfer function or rotation");
294	      }
295	    }
296	
297	    if (!requiresHdr180RotationFix) {
298	      return frame;
299	    }
300	
301	    if (Log.isLoggable(TAG, Log.DEBUG)) {
302	      Log.d(TAG, "Applying HDR 180 deg thumbnail correction");
303	    }
304	    Matrix rotationMatrix = new Matrix();
305	    rotationMatrix.postRotate(
306	        /* degrees= */ 180, frame.getWidth() / 2.0f, frame.getHeight() / 2.0f);
307	    return Bitmap.createBitmap(
308	        frame,
309	        /* x= */ 0,
310	        /* y= */ 0,
311	        frame.getWidth(),
312	        frame.getHeight(),
313	        rotationMatrix,
314	        /* filter= */ true);
315	  }
316	
317	  @RequiresApi(VERSION_CODES.R)
318	  private static boolean isHDR(MediaMetadataRetriever mediaMetadataRetriever)
319	      throws NumberFormatException {
320	    String colorTransferString =
321	        mediaMetadataRetriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_COLOR_TRANSFER);
322	    String colorStandardString =
323	        mediaMetadataRetriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_COLOR_STANDARD);
324	    int colorTransfer = Integer.parseInt(colorTransferString);
325	    int colorStandard = Integer.parseInt(colorStandardString);
326	    // This check needs to match the isHDR check in
327	    // frameworks/av/media/libstagefright/FrameDecoder.cpp.
328	    return (colorTransfer == MediaFormat.COLOR_TRANSFER_HLG
329	            || colorTransfer == MediaFormat.COLOR_TRANSFER_ST2084)
330	        && colorStandard == MediaFormat.COLOR_STANDARD_BT2020;
331	  }
332	
333	  /** Returns true if the build requires a fix for the HDR 180 degree rotation bug. */
334	  @VisibleForTesting
335	  static boolean isHdr180RotationFixRequired() {
336	    // Only pixel devices have android T builds without the framework fix.
337	    if (Build.MODEL.startsWith("Pixel") && VERSION.SDK_INT == VERSION_CODES.TIRAMISU) {
338	      return isTBuildRequiringRotationFix();
339	    }
340	    return VERSION.SDK_INT >= VERSION_CODES.R && VERSION.SDK_INT < VERSION_CODES.TIRAMISU;
341	  }
342	
343	  /**
344	   * Returns true if the build is an Android T build that requires a fix for the HDR 180 degree
345	   * rotation bug.
346	   */
347	  private static boolean isTBuildRequiringRotationFix() {
348	    for (String buildId : PIXEL_T_BUILD_ID_PREFIXES_REQUIRING_HDR_180_ROTATION_FIX) {
349	      if (Build.ID.startsWith(buildId)) {
350	        return true;
351	      }
352	    }
353	    return false;
354	  }
355	
356	  @Nullable
357	  @TargetApi(Build.VERSION_CODES.O_MR1)
358	  private static Bitmap decodeScaledFrame(
359	      MediaMetadataRetriever mediaMetadataRetriever,
360	      long frameTimeMicros,
361	      int frameOption,
362	      int outWidth,
363	      int outHeight,
364	      DownsampleStrategy strategy) {
365	    try {
366	      int originalWidth =
367	          Integer.parseInt(
368	              mediaMetadataRetriever.extractMetadata(
369	                  MediaMetadataRetriever.METADATA_KEY_VIDEO_WIDTH));
370	      int originalHeight =
371	          Integer.parseInt(
372	              mediaMetadataRetriever.extractMetadata(
373	                  MediaMetadataRetriever.METADATA_KEY_VIDEO_HEIGHT));
374	      int orientation =
375	          Integer.parseInt(
376	              mediaMetadataRetriever.extractMetadata(
377	                  MediaMetadataRetriever.METADATA_KEY_VIDEO_ROTATION));
378	
379	      if (orientation == 90 || orientation == 270) {
380	        int temp = originalWidth;
381	        //noinspection SuspiciousNameCombination
382	        originalWidth = originalHeight;
383	        originalHeight = temp;
384	      }
385	
386	      float scaleFactor =
387	          strategy.getScaleFactor(originalWidth, originalHeight, outWidth, outHeight);
388	
389	      int decodeWidth = Math.round(scaleFactor * originalWidth);
390	      int decodeHeight = Math.round(scaleFactor * originalHeight);
391	
392	      return mediaMetadataRetriever.getScaledFrameAtTime(
393	          frameTimeMicros, frameOption, decodeWidth, decodeHeight);
394	    } catch (Throwable t) {
395	      // This is aggressive, but we'd rather catch errors caused by reading and/or parsing metadata
396	      // here and fall back to just decoding the frame whenever possible. If the exception is thrown
397	      // just from decoding the frame, then it will be thrown and exposed to callers by the method
398	      // below.
399	      if (Log.isLoggable(TAG, Log.DEBUG)) {
400	        Log.d(
401	            TAG,
402	            "Exception trying to decode a scaled frame on oreo+, falling back to a fullsize frame",
403	            t);
404	      }
405	
406	      return null;
407	    }
408	  }
409	
410	  private static Bitmap decodeOriginalFrame(
411	      MediaMetadataRetriever mediaMetadataRetriever, long frameTimeMicros, int frameOption) {
412	    return mediaMetadataRetriever.getFrameAtTime(frameTimeMicros, frameOption);
413	  }
414	
415	  /** Returns true if the format type is unsupported on the device. */
416	  private boolean isUnsupportedFormat(
417	      @NonNull T resource, MediaMetadataRetriever mediaMetadataRetriever) {
418	    // MediaFormat.KEY_MIME check below requires at least JELLY_BEAN
419	    if (Build.VERSION.SDK_INT < VERSION_CODES.JELLY_BEAN) {
420	      return false;
421	    }
422	
423	    // The primary known problem is vp8 video on ChromeOS (ARC) devices.
424	    boolean isArc = Build.DEVICE != null && Build.DEVICE.matches(".+_cheets|cheets_.+");
425	    if (!isArc) {
426	      return false;
427	    }
428	
429	    MediaExtractor mediaExtractor = null;
430	    try {
431	      // Include the MediaMetadataRetriever extract in the try block out of an abundance of caution.
432	      String mimeType =
433	          mediaMetadataRetriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_MIMETYPE);
434	      if (!WEBM_MIME_TYPE.equals(mimeType)) {
435	        return false;
436	      }
437	
438	      // Only construct a MediaExtractor for webm files, since the constructor makes a JNI call
439	      mediaExtractor = new MediaExtractor();
440	      initializer.initializeExtractor(mediaExtractor, resource);
441	      int numTracks = mediaExtractor.getTrackCount();
442	      for (int i = 0; i < numTracks; ++i) {
443	        MediaFormat mediaformat = mediaExtractor.getTrackFormat(i);
444	        String trackMimeType = mediaformat.getString(MediaFormat.KEY_MIME);
445	        if (MediaFormat.MIMETYPE_VIDEO_VP8.equals(trackMimeType)) {
446	          return true;
447	        }
448	      }
449	    } catch (Throwable t) {
450	      // Catching everything here out of an abundance of caution
451	      if (Log.isLoggable(TAG, Log.DEBUG)) {
452	        Log.d(TAG, "Exception trying to extract track info for a webm video on CrOS.", t);
453	      }
454	    } finally {
455	      if (mediaExtractor != null) {
456	        mediaExtractor.release();
457	      }
458	    }
459	
460	    return false;
461	  }
462	
