511	  @RequiresApi(Build.VERSION_CODES.M)
512	  static final class ByteBufferInitializer implements MediaInitializer<ByteBuffer> {
513	
514	    @Override
515	    public void initializeRetriever(MediaMetadataRetriever retriever, final ByteBuffer data) {
516	      retriever.setDataSource(getMediaDataSource(data));
517	    }
518	
519	    @Override
520	    public void initializeExtractor(MediaExtractor extractor, final ByteBuffer data)
521	        throws IOException {
522	      extractor.setDataSource(getMediaDataSource(data));
523	    }
524	
525	    private MediaDataSource getMediaDataSource(final ByteBuffer data) {
526	      return new MediaDataSource() {
527	        @Override
528	        public int readAt(long position, byte[] buffer, int offset, int size) {
529	          if (position >= data.limit()) {
530	            return -1;
531	          }
532	          data.position((int) position);
533	          int numBytesRead = Math.min(size, data.remaining());
534	          data.get(buffer, offset, numBytesRead);
535	          return numBytesRead;
536	        }
537	
538	        @Override
539	        public long getSize() {
540	          return data.limit();
541	        }
542	
543	        @Override
544	        public void close() {}
545	      };
546	    }
547	  }
