1	package com.bumptech.glide.integration.sqljournaldiskcache;
2	
3	import android.os.HandlerThread;
4	import android.os.Looper;
5	import android.os.Process;
6	import android.util.Log;
7	import androidx.annotation.Nullable;
8	import androidx.annotation.VisibleForTesting;
9	import com.bumptech.glide.util.Preconditions;
10	import java.io.File;
11	import java.io.IOException;
12	import java.util.ArrayList;
13	import java.util.Collections;
14	import java.util.List;
15	
16	/**
17	 * An Lru disk cache that stores each entry as a single File and uses a SQL based journal to track
18	 * sizes and eviction order.
19	 *
20	 * <p>Operations are not guaranteed and will silently fail in unexpected cases.
21	 *
22	 * <p>The size of the cache is approximate and will be exceeded for short periods of time. Failure
23	 * cases may leave behind temporary files that should be cleaned up in the future when the cache is
24	 * re-opened or when operations are attempted again.
25	 *
26	 * <p>This class is thread safe and may be accessed from multiple threads simultaneously.
27	 */
28	final class JournaledLruDiskCache {
29	  private static final String TAG = "DiskCache";
30	  private static final String CANARY_FILE_NAME = "cache_canary";
31	  // You must restart the app after enabling these logs for the change to take affect.
32	  // We cache isLoggable to avoid the performance hit of checking repeatedly.
33	  private static final boolean LOG_WARN = Log.isLoggable(TAG, Log.WARN);
34	  private static final boolean LOG_VERBOSE = Log.isLoggable(TAG, Log.VERBOSE);
35	  // The fraction of the maximum byte size of the cache we will allow the cache to go over before
36	  // triggering an eviction.
37	  private static final float DEFAULT_EVICTION_SLOP_MULTIPLIER = 0.05f;
38	  // The number of items we will queue to update the date modified time of in batches.
39	  private static final int DEFAULT_UPDATE_MODIFIED_TIME_BATCH_SIZE = 20;
40	
41	  static final String TEMP_FILE_INDICATOR = ".tmp";
42	
43	  private final File cacheDirectory;
44	  private final FileSystem fileSystem;
45	  private final Journal journal;
46	  // We use this File to determine if the system has wiped out our cache directory, which it may do
47	  // at any time. If the File is not present, then either we've never opened the cache for the given
48	  // directory before, or the cache was wiped.
49	  private final File canaryFile;
50	  private final EvictionManager evictionManager;
51	  private final RecoveryManager recoveryManager;
52	  private final EntryCache entries = new EntryCache();
53	
54	  private volatile boolean isOpen;
55	
56	  /**
57	   * @param cacheDirectory The directory in which the cache should store its files (Warning: the
58	   *     cache will delete all Files in the given directory. The directory should not be used to
59	   *     store any other content).
60	   * @param maximumSizeBytes The target maximum size in bytes. The cache size may briefly exceed
61	   *     this size by up to around 25mb depending on the size, thread scheduling, and the number of
62	   *     failed requests.
63	   */
64	  JournaledLruDiskCache(
65	      File cacheDirectory,
66	      DiskCacheDbHelper diskCacheDbHelper,
67	      long maximumSizeBytes,
68	      long staleEvictionThresholdMs,
69	      Clock clock) {
70	    this(
71	        cacheDirectory,
72	        diskCacheDbHelper,
73	        new FileSystem() {},
74	        maximumSizeBytes,
75	        getBackgroundLooper(),
76	        DEFAULT_EVICTION_SLOP_MULTIPLIER,
77	        DEFAULT_UPDATE_MODIFIED_TIME_BATCH_SIZE,
78	        staleEvictionThresholdMs,
79	        clock);
80	  }
81	
82	  @VisibleForTesting
83	  JournaledLruDiskCache(
84	      File cacheDirectory,
85	      DiskCacheDbHelper diskCacheDbHelper,
86	      FileSystem fileSystem,
87	      long maximumSizeBytes,
88	      Looper workLooper,
89	      float slopMultiplier,
90	      int updateModifiedTimeBatchSize,
91	      long staleEvictionThresholdMs,
92	      Clock clock) {
93	    Preconditions.checkArgument(
94	        updateModifiedTimeBatchSize >= 1, "updated modified time batch size must be >= 1");
95	    this.cacheDirectory = cacheDirectory;
96	    this.fileSystem = fileSystem;
97	
98	    journal = new Journal(diskCacheDbHelper, workLooper, updateModifiedTimeBatchSize, clock);
99	    canaryFile = new File(cacheDirectory, CANARY_FILE_NAME);
100	
101	    evictionManager =
102	        new EvictionManager(
103	            this,
104	            cacheDirectory,
105	            fileSystem,
106	            journal,
107	            workLooper,
108	            maximumSizeBytes,
109	            slopMultiplier,
110	            staleEvictionThresholdMs,
111	            clock);
112	    recoveryManager = new RecoveryManager(this, cacheDirectory, journal, workLooper);
113	  }
114	
115	  private static Looper getBackgroundLooper() {
116	    HandlerThread workThread =
117	        new HandlerThread("disk_cache_journal", Process.THREAD_PRIORITY_BACKGROUND);
118	    workThread.start();
119	    return workThread.getLooper();
120	  }
121	
122	  @SuppressWarnings("checkstyle:UnnecessaryParentheses") // Readability
123	  private void openIfNotOpen() {
124	    if (!isOpen) {
125	      synchronized (this) {
126	        if (!isOpen) {
127	          boolean createdDirectory =
128	              cacheDirectory.mkdirs() || (cacheDirectory.exists() && cacheDirectory.isDirectory());
129	          if (!createdDirectory) {
130	            throw new IllegalStateException("Failed to create cache directory: " + cacheDirectory);
131	          }
132	          journal.open();
133	          isOpen = true;
134	          recoveryManager.triggerRecovery();
135	        }
136	      }
137	    }
138	  }
139	
140	  // TODO(judds): rather than polling, we should use Android's FileObserver.
141	  private void verifyCanaryOrClear() {
142	    if (fileSystem.exists(canaryFile)) {
143	      return;
144	    }
145	
146	    synchronized (this) {
147	      if (fileSystem.exists(canaryFile)) {
148	        return;
149	      }
150	      if (LOG_WARN) {
151	        Log.w(TAG, "Failed to find canary file, clearing disk cache");
152	      }
153	      clear();
154	    }
155	  }
156	
157	  private void touchCanaryFile() {
158	    try {
159	      if (!fileSystem.createNewFile(canaryFile) && LOG_WARN) {
160	        Log.w(TAG, "Failed to create new canary file");
161	      }
162	    } catch (IOException e) {
163	      if (LOG_WARN) {
164	        Log.w(TAG, "Threw creating canary", e);
165	      }
166	    }
167	  }
168	
169	  long getCurrentSizeBytes() {
170	    return journal.getCurrentSizeBytes();
171	  }
172	
173	  /**
174	   * Makes a best effort attempt to delete all Files and clear the journal.
175	   *
176	   * <p>In progress writes may still complete and/or leave behind partial data.
177	   */
178	  public synchronized void clear() {
179	    if (LOG_WARN) {
180	      Log.w(TAG, "Clearing cache and deleting all entries!");
181	    }
182	    fileSystem.deleteAll(cacheDirectory);
183	    journal.clear();
184	    isOpen = false;
185	    entries.clear();
186	    openIfNotOpen();
187	    touchCanaryFile();
188	  }
189	
190	  /**
191	   * Attempts to delete any content currently in the cache for the given key.
192	   *
193	   * <p>If no entry for the given key is found, this method will silently fail. If an entry is
194	   * found, it is possible the File deletion will fail and be re-attempted in the future.
195	   */
196	  public void delete(String key) {
197	    delete(Collections.singletonList(key));
198	  }
199	
200	  List<String> delete(List<String> keys) {
201	    journal.markPendingDelete(keys);
202	    List<String> successfullyDeleted = new ArrayList<>(keys.size());
203	    for (String key : keys) {
204	      EntryCache.Entry entry = entries.get(key);
205	      entry.acquireWriteLock();
206	      try {
207	        File file = getCacheFile(key);
208	        if (fileSystem.delete(file)) {
209	          successfullyDeleted.add(key);
210	        } else if (LOG_WARN) {
211	          Log.w(TAG, "Failed to delete file: " + file);
212	        }
213	        entry.setNotPresent();
214	      } finally {
215	        entry.releaseWriteLock();
216	      }
217	    }
218	    journal.delete(successfullyDeleted);
219	    return successfullyDeleted;
220	  }
221	
222	  /**
223	   * Returns a File committed previously for the given key, or {@code null} if no such File exists.
224	   *
225	   * <p>If a write is in progress but not yet committed for the given key, this method will return
226	   * {@code null} immediately, just as if the key were simply not present.
227	   */
228	  public File get(String key) {
229	    long startTime = getLogTime();
230	    openIfNotOpen();
231	    final File result;
232	    EntryCache.Entry entry = entries.get(key);
233	    entry.acquireReadLock();
234	    try {
235	      if (entry.isStateKnown()) {
236	        result = entry.isPresent() ? entry.getFile() : null;
237	      } else {
238	        File cacheFile = getCacheFile(key);
239	        if (fileSystem.exists(cacheFile)) {
240	          entry.setPresent(cacheFile);
241	          result = cacheFile;
242	        } else {
243	          entry.setNotPresent();
244	          result = null;
245	        }
246	      }
247	      if (result != null) {
248	        journal.get(key);
249	      }
250	
251	      if (LOG_VERBOSE) {
252	        Log.v(TAG, "Completed get in: " + getElapsedTime(startTime) + ", key: " + key);
253	      }
254	    } finally {
255	      entry.releaseReadLock();
256	    }
257	
258	    return result;
259	  }
260	
261	  /**
262	   * Starts a put for the given key and returns a temporary {@link File} to which the caller can
263	   * write data, or {@code null} if an edit is already in progress for the given Key, or if a
264	   * committed entry already exists for the given key.
265	   *
266	   * <p>Callers should call {@link #commitPut(String, File)} with the given key and the {@link File}
267	   * returned from this method after they finish writing data to make the data they have written
268	   * available to calls to {@link #get(String)}. If an error occurs while writing data, callers can
269	   * omit calling {@link #commitPut(String, File)} and use {@link #abortPutIfNotCommitted(String,
270	   * File)} to cleanup any partial {@link File Files}.
271	   *
272	   * <p>Callers must call {@link #abortPutIfNotCommitted(String, File)} regardless of whether or not
273	   * their write succeeds. The expected pattern is as follows:
274	   *
275	   * <pre>{@code
276	   * File tempFile = cache.beginPut(key);
277	   * try {
278	   *   if (tempFile != null && writeToFile(someData, tempFile)) {
279	   *    cache.commitPut(key, tempFile);
280	   *   }
281	   * } finally {
282	   *   cache.abortIfNotCommitted(key, tempFile);
283	   * }
284	   * }</pre>
285	   *
286	   * <p>Until the caller calls {@link #abortPutIfNotCommitted(String, File)}, a lock is held that
287	   * will block future calls to this method for the given key.
288	   *
289	   * <p>The returned {@link File} may contain partial data if a previous write to this key failed.
290	   * Callers should not assume it is safe to append to the File without first clearing it.
291	   */
292	  @Nullable
293	  public File beginPut(String key) {
294	    long startTime = getLogTime();
295	    openIfNotOpen();
296	    verifyCanaryOrClear();
297	    EntryCache.Entry entry = entries.get(key);
298	    entry.acquireWriteLock();
299	
300	    File permanentFile = getCacheFile(key);
301	    if (fileSystem.exists(permanentFile)) {
302	      return null;
303	    }
304	
305	    File result = getTempFile(key);
306	    if (LOG_VERBOSE) {
307	      Log.v(TAG, "Completed begin put in: " + getElapsedTime(startTime) + ", key: " + key);
308	    }
309	    return result;
310	  }
311	
312	  /**
313	   * Updates the size of the cache based on the data in the given temporary file and renames the
314	   * given temporary File to its permanent equivalent and makes it available to calls from {@link
315	   * #get(String)}.
316	   *
317	   * <p>The given {@link File} must be a {@link File} returned from {@link #get(String)} for the
318	   * given key. No validation is performed to verify either that the given {@link File} is a
319	   * legitimate temporary file from this cache or that the given {@link File} matches the given key.
320	   *
321	   * <p>It is possible this commit may fail silently, there is no guarantee that the data in the
322	   * given {@link File} will actually be available from {@link #get(String)}} when this method
323	   * completes. In practice commits should fail rarely unless insufficient storage is available or
324	   * the cache's directory or files are manipulated by a third party.
325	   *
326	   * <p>If the commit does fail, it will do so in one of two ways:
327	   *
328	   * <ul>
329	   *   <li>Prior to or while writing the entry to the journal
330	   *   <li>After writing the entry to the journal prior to or while renaming the temporary file to
331	   *       the permanent file.
332	   * </ul>
333	   *
334	   * If the commit fails prior to writing the entry to the journal, the dangling temporary File will
335	   * be found during recovery and deleted. If the commit fails after writing the entry to the
336	   * journal, the temporary file will be found during recovery and deleted and the corresponding
337	   * journal entry will also be deleted. The absence of a temporary File for a given key is assumed
338	   * to mean that either no entry exists, or the entry is committed and may be read.
339	   *
340	   * @throws IllegalStateException If this method wasn't preceded by a call to {@link
341	   *     #beginPut(String)} for the given key.
342	   */
343	  public void commitPut(String key, File temp) {
344	    long startTime = getLogTime();
345	
346	    long totalBytesAdded = fileSystem.length(temp);
347	    journal.put(key, totalBytesAdded);
348	
349	    if (LOG_VERBOSE) {
350	      Log.v(TAG, "Completed insertIntoDb in: " + getElapsedTime(startTime));
351	    }
352	
353	    long startRenameTime = getLogTime();
354	    File permanentFile = getCacheFile(key);
355	
356	    boolean isRenameSuccessful = fileSystem.rename(temp, permanentFile);
357	    // If we fail to rename the file, we will try to recover in our next recovery phase.
358	    if (isRenameSuccessful) {
359	      if (LOG_VERBOSE) {
360	        Log.v(TAG, "Successfully renamed in: " + getElapsedTime(startRenameTime));
361	      }
362	      EntryCache.Entry entry = entries.get(key);
363	      entry.setPresent(permanentFile);
364	    } else if (LOG_WARN) {
365	      Log.w(TAG, "Failed to rename file" + ", from: " + temp + ", to: " + permanentFile);
366	    }
367	
368	    evictionManager.maybeScheduleEviction();
369	
370	    if (LOG_VERBOSE) {
371	      Log.v(
372	          TAG,
373	          "Completed commitPut in: "
374	              + getElapsedTime(startTime)
375	              + ", current size: "
376	              + journal.getCurrentSizeBytes()
377	              + ", key: "
378	              + key);
379	    }
380	  }
381	
382	  /**
383	   * Releases the write lock for the given key and, if the write was not committed, cleans up the
384	   * given temporary File and the corresponding journal entry for the given Key.
385	   *
386	   * <p>A write is assumed to have not been committed if the given temporary File still exists.
387	   */
388	  public void abortPutIfNotCommitted(String key, File temp) {
389	    try {
390	      // If the temporary File still exists, we haven't committed. If it doesn't exist, we either
391	      // didn't start writing and have nothing to roll back, or we finished writing and finished
392	      // the rename so the edit is committed.
393	      if (temp != null && fileSystem.delete(temp)) {
394	        journal.abortPut(key);
395	        EntryCache.Entry entry = entries.get(key);
396	        entry.setUnknown();
397	      }
398	    } finally {
399	      EntryCache.Entry entry = entries.get(key);
400	      entry.releaseWriteLock();
401	    }
402	  }
403	
404	  void recoverPartialWrite(File temp) {
405	    String key = keyFromFile(temp);
406	    EntryCache.Entry entry = entries.get(key);
407	    entry.acquireWriteLock();
408	    try {
409	      // Try to delete the temporary file, if it fails, we will try again in the next recovery
410	      // phase.
411	      boolean deleted = temp.delete();
412	      if (!deleted) {
413	        if (LOG_WARN) {
414	          Log.w(TAG, "Failed to cleanup in progress write: " + temp);
415	        }
416	        // The write lock prevents us from directly racing with an in progress write. However when
417	        // the write lock is released, we will get to run. If the write completed successfully,
418	        // the
419	        // temp file will no longer exist, but the entry will. We do not want to delete the entry
420	        // just because we happened to try to run recovery during the write.
421	        return;
422	      }
423	      delete(key);
424	    } finally {
425	      entry.releaseWriteLock();
426	    }
427	  }
428	
429	  private String keyFromFile(File file) {
430	    String name = file.getName();
431	    final String key;
432	    if (name.endsWith(TEMP_FILE_INDICATOR)) {
433	      key = name.substring(0, name.length() - TEMP_FILE_INDICATOR.length());
434	    } else {
435	      key = name;
436	    }
437	    return key;
438	  }
439	
440	  /**
441	   * Sets the maximum size of the cache to a new size in bytes.
442	   *
443	   * <p>Must be called on a background thread.
444	   *
445	   * <p>The EvictionManager manages the sizing of the cache. Decreasing the size may schedule an
446	   * eviction if the current cache size exceeds newMaximumSizeBytes. Evictions will be scheduled and
447	   * executed asynchronously. Therefore, the eviction will happen based on the latest maximum cache
448	   * size, not the maximum size at scheduling.
449	   */
450	  public void setMaximumSizeBytes(long newMaximumSizeBytes) {
451	    evictionManager.setMaximumSizeBytes(newMaximumSizeBytes);
452	  }
453	
454	  private File getCacheFile(String key) {
455	    return new File(cacheDirectory, key);
456	  }
457	
458	  private File getTempFile(String key) {
459	    return new File(cacheDirectory, key + TEMP_FILE_INDICATOR);
460	  }
461	
462	  private static long getLogTime() {
463	    return System.currentTimeMillis();
464	  }
465	
466	  private static long getElapsedTime(long startTime) {
467	    return getLogTime() - startTime;
468	  }
469	}
