1	package com.bumptech.glide.load.engine.bitmap_recycle;
2	
3	import android.graphics.Bitmap;
4	import android.os.Build;
5	import androidx.annotation.Nullable;
6	import androidx.annotation.RequiresApi;
7	import androidx.annotation.VisibleForTesting;
8	import com.bumptech.glide.util.Synthetic;
9	import com.bumptech.glide.util.Util;
10	import java.util.NavigableMap;
11	
12	/**
13	 * A strategy for reusing bitmaps that relies on {@link Bitmap#reconfigure(int, int,
14	 * Bitmap.Config)}.
15	 *
16	 * <p>Requires {@link Build.VERSION_CODES#KITKAT KitKat} or higher.
17	 */
18	@RequiresApi(Build.VERSION_CODES.KITKAT)
19	final class SizeStrategy implements LruPoolStrategy {
20	  private static final int MAX_SIZE_MULTIPLE = 8;
21	  private final KeyPool keyPool = new KeyPool();
22	  private final GroupedLinkedMap<Key, Bitmap> groupedMap = new GroupedLinkedMap<>();
23	  private final NavigableMap<Integer, Integer> sortedSizes = new PrettyPrintTreeMap<>();
24	
25	  @Override
26	  public void put(Bitmap bitmap) {
27	    int size = Util.getBitmapByteSize(bitmap);
28	    final Key key = keyPool.get(size);
29	
30	    groupedMap.put(key, bitmap);
31	
32	    Integer current = sortedSizes.get(key.size);
33	    sortedSizes.put(key.size, current == null ? 1 : current + 1);
34	  }
