2	
3	import androidx.annotation.NonNull;
4	import com.bumptech.glide.load.DataSource;
5	import com.bumptech.glide.load.Key;
6	import com.bumptech.glide.load.data.DataFetcher;
7	import com.bumptech.glide.load.model.ModelLoader;
8	import com.bumptech.glide.load.model.ModelLoader.LoadData;
9	import com.bumptech.glide.util.pool.GlideTrace;
10	import java.io.File;
11	import java.util.List;
12	
13	/**
14	 * Generates {@link com.bumptech.glide.load.data.DataFetcher DataFetchers} from cache files
15	 * containing original unmodified source data.
16	 */
17	class DataCacheGenerator implements DataFetcherGenerator, DataFetcher.DataCallback<Object> {
18	
19	  private final List<Key> cacheKeys;
20	  private final DecodeHelper<?> helper;
21	  private final FetcherReadyCallback cb;
22	
23	  private int sourceIdIndex = -1;
24	  private Key sourceKey;
25	  private List<ModelLoader<File, ?>> modelLoaders;
26	  private int modelLoaderIndex;
27	  private volatile LoadData<?> loadData;
28	
29	  // PMD is wrong here, this File must be an instance variable because it may be used across
30	  // multiple calls to startNext.
31	  @SuppressWarnings("PMD.SingularField")
32	  private File cacheFile;
33	
34	  DataCacheGenerator(DecodeHelper<?> helper, FetcherReadyCallback cb) {
35	    this(helper.getCacheKeys(), helper, cb);
36	  }
37	
38	  // In some cases we may want to load a specific cache key (when loading from source written to
39	  // cache), so we accept a list of keys rather than just obtain the list from the helper.
40	  DataCacheGenerator(List<Key> cacheKeys, DecodeHelper<?> helper, FetcherReadyCallback cb) {
41	    this.cacheKeys = cacheKeys;
42	    this.helper = helper;
43	    this.cb = cb;
44	  }
45	
46	  @Override
47	  public boolean startNext() {
48	    GlideTrace.beginSection("DataCacheGenerator.startNext");
49	    try {
50	      while (modelLoaders == null || !hasNextModelLoader()) {
51	        sourceIdIndex++;
52	        if (sourceIdIndex >= cacheKeys.size()) {
53	          return false;
54	        }
55	
56	        Key sourceId = cacheKeys.get(sourceIdIndex);
57	        // PMD.AvoidInstantiatingObjectsInLoops The loop iterates a limited number of times
58	        // and the actions it performs are much more expensive than a single allocation.
59	        @SuppressWarnings("PMD.AvoidInstantiatingObjectsInLoops")
60	        Key originalKey = new DataCacheKey(sourceId, helper.getSignature());
61	        cacheFile = helper.getDiskCache().get(originalKey);
62	        if (cacheFile != null) {
63	          this.sourceKey = sourceId;
64	          modelLoaders = helper.getModelLoaders(cacheFile);
65	          modelLoaderIndex = 0;
66	        }
67	      }
68	
69	      loadData = null;
70	      boolean started = false;
71	      while (!started && hasNextModelLoader()) {
72	        ModelLoader<File, ?> modelLoader = modelLoaders.get(modelLoaderIndex++);
73	        loadData =
74	            modelLoader.buildLoadData(
75	                cacheFile, helper.getWidth(), helper.getHeight(), helper.getOptions());
76	        if (loadData != null && helper.hasLoadPath(loadData.fetcher.getDataClass())) {
77	          started = true;
78	          loadData.fetcher.loadData(helper.getPriority(), this);
79	        }
80	      }
81	      return started;
82	    } finally {
83	      GlideTrace.endSection();
84	    }
85	  }
86	
87	  private boolean hasNextModelLoader() {
88	    return modelLoaderIndex < modelLoaders.size();
89	  }
90	
91	  @Override
92	  public void cancel() {
93	    LoadData<?> local = loadData;
94	    if (local != null) {
95	      local.fetcher.cancel();
96	    }
97	  }
98	
99	  @Override
100	  public void onDataReady(Object data) {
101	    cb.onDataFetcherReady(sourceKey, data, loadData.fetcher, DataSource.DATA_DISK_CACHE, sourceKey);
102	  }
103	
104	  @Override
105	  public void onLoadFailed(@NonNull Exception e) {
106	    cb.onDataFetcherFailed(sourceKey, e, loadData.fetcher, DataSource.DATA_DISK_CACHE);
107	  }
108	}
