157	  void cancelRequest(GlideUrl glideUrl, Listener listener) {
158	    final Job job;
159	    synchronized (this) {
160	      job = jobs.get(glideUrl);
161	    }
162	    // Jobs may be cancelled before they are started.
163	    if (job != null) {
164	      job.removeListener(listener);
