186	    private final List<Listener> listeners = new ArrayList<>(2);
187	
188	    private GlideUrl glideUrl;
189	    private Priority priority;
190	    private long startTime;
191	    private UrlRequest request;
192	    private long endTimeMs;
193	    private long responseStartTimeMs;
194	    private volatile boolean isCancelled;
