207	    void addListener(Listener listener) {
208	      synchronized (ChromiumRequestSerializer.this) {
209	        listeners.add(listener);
210	      }
211	    }
212	
213	    void removeListener(Listener listener) {
214	      synchronized (ChromiumRequestSerializer.this) {
