254	    @Override
255	    public void onSucceeded(UrlRequest request, final UrlResponseInfo info) {
256	      executorSupplier
257	          .get()
258	          .execute(
259	              new PriorityRunnable(priority) {
260	                @Override
261	                public void run() {
262	                  onRequestFinished(
263	                      info,
264	                      null /*exception*/,
265	                      false /*wasCancelled*/,
266	                      builder.build().coalesceToBuffer());
267	                }
268	              });
269	    }
270	
271	    @Override
272	    public void onFailed(
273	        UrlRequest urlRequest, final UrlResponseInfo urlResponseInfo, final CronetException e) {
274	      executorSupplier
275	          .get()
276	          .execute(
277	              new PriorityRunnable(priority) {
278	                @Override
279	                public void run() {
