2	
3	import androidx.annotation.NonNull;
4	import com.bumptech.glide.load.DataSource;
5	import com.bumptech.glide.load.Key;
6	import com.bumptech.glide.load.Transformation;
7	import com.bumptech.glide.load.data.DataFetcher;
8	import com.bumptech.glide.load.model.ModelLoader;
9	import com.bumptech.glide.load.model.ModelLoader.LoadData;
10	import com.bumptech.glide.util.pool.GlideTrace;
11	import java.io.File;
12	import java.util.List;
13	
14	/**
15	 * Generates {@link com.bumptech.glide.load.data.DataFetcher DataFetchers} from cache files
16	 * containing downsampled/transformed resource data.
17	 */
18	class ResourceCacheGenerator implements DataFetcherGenerator, DataFetcher.DataCallback<Object> {
19	
20	  private final FetcherReadyCallback cb;
21	  private final DecodeHelper<?> helper;
22	
23	  private int sourceIdIndex;
24	  private int resourceClassIndex = -1;
25	  private Key sourceKey;
26	  private List<ModelLoader<File, ?>> modelLoaders;
27	  private int modelLoaderIndex;
28	  private volatile LoadData<?> loadData;
29	
30	  // PMD is wrong here, this File must be an instance variable because it may be used across
31	  // multiple calls to startNext.
32	  @SuppressWarnings("PMD.SingularField")
33	  private File cacheFile;
34	
35	  private ResourceCacheKey currentKey;
36	
37	  ResourceCacheGenerator(DecodeHelper<?> helper, FetcherReadyCallback cb) {
38	    this.helper = helper;
39	    this.cb = cb;
40	  }
41	
42	  // See TODO below.
43	  @SuppressWarnings("PMD.CollapsibleIfStatements")
44	  @Override
45	  public boolean startNext() {
46	    GlideTrace.beginSection("ResourceCacheGenerator.startNext");
47	    try {
48	      List<Key> sourceIds = helper.getCacheKeys();
49	      if (sourceIds.isEmpty()) {
50	        return false;
51	      }
52	      List<Class<?>> resourceClasses = helper.getRegisteredResourceClasses();
53	      if (resourceClasses.isEmpty()) {
54	        if (File.class.equals(helper.getTranscodeClass())) {
55	          return false;
56	        }
57	        throw new IllegalStateException(
58	            "Failed to find any load path from "
59	                + helper.getModelClass()
60	                + " to "
61	                + helper.getTranscodeClass());
62	      }
63	      while (modelLoaders == null || !hasNextModelLoader()) {
64	        resourceClassIndex++;
65	        if (resourceClassIndex >= resourceClasses.size()) {
66	          sourceIdIndex++;
67	          if (sourceIdIndex >= sourceIds.size()) {
68	            return false;
69	          }
70	          resourceClassIndex = 0;
71	        }
72	
73	        Key sourceId = sourceIds.get(sourceIdIndex);
74	        Class<?> resourceClass = resourceClasses.get(resourceClassIndex);
75	        Transformation<?> transformation = helper.getTransformation(resourceClass);
76	        // PMD.AvoidInstantiatingObjectsInLoops Each iteration is comparatively expensive anyway,
77	        // we only run until the first one succeeds, the loop runs for only a limited
78	        // number of iterations on the order of 10-20 in the worst case.
79	        currentKey =
80	            new ResourceCacheKey( // NOPMD AvoidInstantiatingObjectsInLoops
81	                helper.getArrayPool(),
82	                sourceId,
83	                helper.getSignature(),
84	                helper.getWidth(),
85	                helper.getHeight(),
86	                transformation,
87	                resourceClass,
88	                helper.getOptions());
89	        cacheFile = helper.getDiskCache().get(currentKey);
90	        if (cacheFile != null) {
91	          sourceKey = sourceId;
92	          modelLoaders = helper.getModelLoaders(cacheFile);
93	          modelLoaderIndex = 0;
94	        }
95	      }
96	
97	      loadData = null;
98	      boolean started = false;
99	      while (!started && hasNextModelLoader()) {
100	        ModelLoader<File, ?> modelLoader = modelLoaders.get(modelLoaderIndex++);
101	        loadData =
102	            modelLoader.buildLoadData(
103	                cacheFile, helper.getWidth(), helper.getHeight(), helper.getOptions());
104	        if (loadData != null && helper.hasLoadPath(loadData.fetcher.getDataClass())) {
105	          started = true;
106	          loadData.fetcher.loadData(helper.getPriority(), this);
107	        }
108	      }
109	
110	      return started;
111	    } finally {
112	      GlideTrace.endSection();
113	    }
114	  }
115	
116	  private boolean hasNextModelLoader() {
117	    return modelLoaderIndex < modelLoaders.size();
118	  }
119	
120	  @Override
121	  public void cancel() {
122	    LoadData<?> local = loadData;
123	    if (local != null) {
124	      local.fetcher.cancel();
125	    }
126	  }
127	
128	  @Override
129	  public void onDataReady(Object data) {
130	    cb.onDataFetcherReady(
131	        sourceKey, data, loadData.fetcher, DataSource.RESOURCE_DISK_CACHE, currentKey);
132	  }
133	
134	  @Override
135	  public void onLoadFailed(@NonNull Exception e) {
136	    cb.onDataFetcherFailed(currentKey, e, loadData.fetcher, DataSource.RESOURCE_DISK_CACHE);
137	  }
138	}
