275	  }
276	
277	  private void dump() {
278	    if (Log.isLoggable(TAG, Log.VERBOSE)) {
279	      dumpUnchecked();
280	    }
281	  }
282	
283	  private void dumpUnchecked() {
284	    Log.v(
285	        TAG,
286	        "Hits="
287	            + hits
288	            + ", misses="
289	            + misses
290	            + ", puts="
291	            + puts
292	            + ", evictions="
293	            + evictions
294	            + ", currentSize="
295	            + currentSize
296	            + ", maxSize="
297	            + maxSize
298	            + "\nStrategy="
299	            + strategy);
300	  }
301	
302	  private static LruPoolStrategy getDefaultStrategy() {
