9	/**
10	 * A general purpose size limited cache that evicts items using an LRU algorithm. By default every
11	 * item is assumed to have a size of one. Subclasses can override {@link #getSize(Object)}} to
12	 * change the size on a per item basis.
13	 *
14	 * @param <T> The type of the keys.
15	 * @param <Y> The type of the values.
16	 */
17	public class LruCache<T, Y> {
18	  private final Map<T, Entry<Y>> cache = new LinkedHashMap<>(100, 0.75f, true);
19	  private final long initialMaxSize;
20	  private long maxSize;
21	  private long currentSize;
22	
23	  /**
24	   * Constructor for LruCache.
25	   *
26	   * @param size The maximum size of the cache, the units must match the units used in {@link
27	   *     #getSize(Object)}.
28	   */
29	  public LruCache(long size) {
30	    this.initialMaxSize = size;
31	    this.maxSize = size;
32	  }
33	
34	  /**
35	   * Sets a size multiplier that will be applied to the size provided in the constructor to put the
36	   * new size of the cache. If the new size is less than the current size, entries will be evicted
37	   * until the current size is less than or equal to the new size.
38	   *
39	   * @param multiplier The multiplier to apply.
40	   */
41	  public synchronized void setSizeMultiplier(float multiplier) {
42	    if (multiplier < 0) {
43	      throw new IllegalArgumentException("Multiplier must be >= 0");
44	    }
45	    maxSize = Math.round(initialMaxSize * multiplier);
46	    evict();
47	  }
48	
49	  /**
50	   * Returns the size of a given item, defaulting to one. The units must match those used in the
51	   * size passed in to the constructor. Subclasses can override this method to return sizes in
52	   * various units, usually bytes.
53	   *
54	   * @param item The item to get the size of.
55	   */
56	  protected int getSize(@Nullable Y item) {
57	    return 1;
58	  }
59	
60	  /** Returns the number of entries stored in cache. */
61	  protected synchronized int getCount() {
62	    return cache.size();
63	  }
64	
65	  /**
66	   * A callback called whenever an item is evicted from the cache. Subclasses can override.
67	   *
68	   * @param key The key of the evicted item.
69	   * @param item The evicted item.
70	   */
71	  protected void onItemEvicted(@NonNull T key, @Nullable Y item) {
72	    // optional override
73	  }
74	
75	  /** Returns the current maximum size of the cache in bytes. */
76	  public synchronized long getMaxSize() {
77	    return maxSize;
78	  }
79	
80	  /** Returns the sum of the sizes of all items in the cache. */
81	  public synchronized long getCurrentSize() {
82	    return currentSize;
83	  }
84	
85	  /**
86	   * Returns true if there is a value for the given key in the cache.
87	   *
88	   * @param key The key to check.
