105	  /**
106	   * Adds the given item to the cache with the given key and returns any previous entry for the
107	   * given key that may have already been in the cache.
108	   *
109	   * <p>If the size of the item is larger than the total cache size, the item will not be added to
110	   * the cache and instead {@link #onItemEvicted(Object, Object)} will be called synchronously with
111	   * the given key and item.
112	   *
113	   * <p>The size of the item is determined by the {@link #getSize(Object)} method. To avoid errors
114	   * where {@link #getSize(Object)} returns different values for the same object when called at
115	   * different times, the size value is acquired in {@code put} and retained until the item is
116	   * evicted, replaced or removed.
117	   *
118	   * <p>If {@code item} is null the behavior here is a little odd. For the most part it's similar to
119	   * simply calling {@link #remove(Object)} with the given key. The difference is that calling this
120	   * method with a null {@code item} will result in an entry remaining in the cache with a null
121	   * value and 0 size. The only real consequence is that at some point {@link #onItemEvicted(Object,
122	   * Object)} may be called with the given {@code key} and a null value. Ideally we'd make calling
123	   * this method with a null {@code item} identical to {@link #remove(Object)} but we're preserving
124	   * this odd behavior to match older versions :(.
125	   *
126	   * @param key The key to add the item at.
127	   * @param item The item to add.
128	   */
129	  @Nullable
130	  public synchronized Y put(@NonNull T key, @Nullable Y item) {
131	    final int itemSize = getSize(item);
132	    if (itemSize >= maxSize) {
133	      onItemEvicted(key, item);
134	      return null;
135	    }
136	
137	    if (item != null) {
138	      currentSize += itemSize;
139	    }
140	    @Nullable Entry<Y> old = cache.put(key, item == null ? null : new Entry<>(item, itemSize));
141	    if (old != null) {
142	      currentSize -= old.size;
143	
144	      if (!old.value.equals(item)) {
145	        onItemEvicted(key, old.value);
146	      }
147	    }
148	    evict();
149	
150	    return old != null ? old.value : null;
151	  }
152	
153	  /**
154	   * Removes the item at the given key and returns the removed item if present, and null otherwise.
155	   *
156	   * @param key The key to remove the item at.
157	   */
158	  @Nullable
159	  public synchronized Y remove(@NonNull T key) {
160	    Entry<Y> entry = cache.remove(key);
161	    if (entry == null) {
162	      return null;
163	    }
164	    currentSize -= entry.size;
165	    return entry.value;
166	  }
167	
168	  /** Clears all items in the cache. */
169	  public void clearMemory() {
170	    trimToSize(0);
171	  }
172	
173	  /**
174	   * Removes the least recently used items from the cache until the current size is less than the
175	   * given size.
176	   *
177	   * @param size The size the cache should be less than.
178	   */
179	  protected synchronized void trimToSize(long size) {
180	    Map.Entry<T, Entry<Y>> last;
181	    Iterator<Map.Entry<T, Entry<Y>>> cacheIterator;
182	    while (currentSize > size) {
183	      cacheIterator = cache.entrySet().iterator();
184	      last = cacheIterator.next();
185	      final Entry<Y> toRemove = last.getValue();
186	      currentSize -= toRemove.size;
187	      final T key = last.getKey();
188	      cacheIterator.remove();
189	      onItemEvicted(key, toRemove.value);
190	    }
191	  }
192	
193	  private void evict() {
194	    trimToSize(maxSize);
195	  }
