31	/** Uses {@link android.net.ConnectivityManager} to identify connectivity changes. */
32	final class SingletonConnectivityReceiver {
33	  private static volatile SingletonConnectivityReceiver instance;
34	  private static final String TAG = "ConnectivityMonitor";
35	
36	  private final FrameworkConnectivityMonitor frameworkConnectivityMonitor;
37	
38	  @GuardedBy("this")
39	  @Synthetic
40	  final Set<ConnectivityListener> listeners = new HashSet<>();
41	
42	  @GuardedBy("this")
43	  private boolean isRegistered;
44	
45	  static SingletonConnectivityReceiver get(@NonNull Context context) {
46	    if (instance == null) {
47	      synchronized (SingletonConnectivityReceiver.class) {
48	        if (instance == null) {
49	          instance = new SingletonConnectivityReceiver(context.getApplicationContext());
