63	        GlideSuppliers.memorize(
64	            () -> (ConnectivityManager) context.getSystemService(Context.CONNECTIVITY_SERVICE));
65	    ConnectivityListener connectivityListener =
66	        isConnected -> {
67	          Util.assertMainThread();
68	          List<ConnectivityListener> toNotify;
69	          synchronized (SingletonConnectivityReceiver.this) {
70	            toNotify = new ArrayList<>(listeners);
71	          }
72	          for (ConnectivityListener listener : toNotify) {
73	            listener.onConnectivityChanged(isConnected);
