128	    @Synthetic boolean isConnected;
129	    @Synthetic final ConnectivityListener listener;
130	    private final GlideSupplier<ConnectivityManager> connectivityManager;
131	    private final NetworkCallback networkCallback =
132	        new NetworkCallback() {
133	          @Override
134	          public void onAvailable(@NonNull Network network) {
135	            postOnConnectivityChange(true);
136	          }
137	
138	          @Override
139	          public void onLost(@NonNull Network network) {
140	            postOnConnectivityChange(false);
141	          }
142	
143	          private void postOnConnectivityChange(final boolean newState) {
144	            // We could use registerDefaultNetworkCallback with a Handler, but that's only available
145	            // on API 26, instead of API 24. We can mimic the same behavior here manually by
146	            // posting to the UI thread. All calls have to be posted to make sure that we retain the
147	            // original order. Otherwise a call on a background thread, followed by a call on the UI
148	            // thread could result in the first call running second.
149	            Util.postOnUiThread(() -> onConnectivityChange(newState));
