206	      implements FrameworkConnectivityMonitor {
207	    // Using AsyncTasks's executor is a hack. We need a background thread, but it's not trivial to
208	    // pass one through to this point. We could make a breaking API change, which upsets external
209	    // users. Or we could try to add an API to expose one of Glide's executors via the singleton,
210	    // but that could allow Glide's executors to be misused as general purpose executors. Given that
211	    // this code is deprecated anyway, using some pre-existing general purpose executor doesn't seem
212	    // wildly unreasonable.
213	    @Synthetic static final Executor EXECUTOR = AsyncTask.SERIAL_EXECUTOR;
214	    @Synthetic final Context context;
215	    @Synthetic final ConnectivityListener listener;
216	    private final GlideSupplier<ConnectivityManager> connectivityManager;
217	    // These are only manipulated serially, but the executor might use separate threads to do so,
218	    // so we use volatile.
219	    @Synthetic volatile boolean isConnected;
220	    @Synthetic volatile boolean isRegistered;
221	
222	    @Synthetic
223	    final BroadcastReceiver connectivityReceiver =
224	        new BroadcastReceiver() {
225	          @Override
226	          public void onReceive(@NonNull Context context, Intent intent) {
227	            onConnectivityChange();
228	          }
229	        };
230	
231	    FrameworkConnectivityMonitorPreApi24(
232	        Context context,
233	        GlideSupplier<ConnectivityManager> connectivityManager,
234	        ConnectivityListener listener) {
235	      this.context = context.getApplicationContext();
236	      this.connectivityManager = connectivityManager;
237	      this.listener = listener;
238	    }
239	
240	    @Override
241	    public boolean register() {
242	      EXECUTOR.execute(
243	          () -> {
244	            // Initialize isConnected so that we notice the first time around when there's a
245	            // broadcast.
246	            // TODO(judds): This causes a race where:
247	            // 1. Connectivity is disconnected
248	            // 2. Register is called, but punted to a background thread and not run yet
249	            // 3. Some network requiring request is started, runs and fails due to connectivity
250	            // 4. Connectivity is re-established
251	            // 5. This code finally runs on the background thread.
252	            // In step 5, we'll think that we're currently connected and won't trigger a retry for
253	            // any previously failed requests.
254	            // In the long run it might be nice to define some explicit initialization step for
255	            // Glide where we do this and other expensive things on a background thread prior to
256	            // starting the first request. For now it seems better to just accept this race than
257	            // either take the latency hit of the IPC on the main thread, or try something like
258	            // always notifying all listeners once right after this logic runs just in case
259	            // something failed.
260	            isConnected = isConnected();
261	            try {
262	              // See #1405
263	              context.registerReceiver(
264	                  connectivityReceiver,
265	                  new IntentFilter(ConnectivityManager.CONNECTIVITY_ACTION));
266	              isRegistered = true;
267	            } catch (SecurityException e) {
268	              // See #1417, registering the receiver can throw SecurityException.
269	              if (Log.isLoggable(TAG, Log.WARN)) {
270	                Log.w(TAG, "Failed to register", e);
271	              }
272	              isRegistered = false;
273	            }
274	          });
275	
276	      // We track our registration status internally, so we always need to be called to unregister.
277	      return true;
278	    }
279	
280	    @Override
281	    public void unregister() {
282	      // Always post to the executor to make sure everything runs in the correct order. If we short
283	      // circuit that by checking isConnected on this thread, we might leak a receiver.
284	      EXECUTOR.execute(
285	          () -> {
286	            if (!isRegistered) {
287	              return;
288	            }
289	            isRegistered = false;
290	            context.unregisterReceiver(connectivityReceiver);
291	          });
292	    }
293	
294	    @Synthetic
295	    void onConnectivityChange() {
296	      EXECUTOR.execute(
297	          () -> {
298	            boolean wasConnected = isConnected;
299	            isConnected = isConnected();
300	            if (wasConnected != isConnected) {
301	              if (Log.isLoggable(TAG, Log.DEBUG)) {
302	                Log.d(TAG, "connectivity changed, isConnected: " + isConnected);
303	              }
304	              notifyChangeOnUiThread(isConnected);
305	            }
306	          });
307	    }
308	
309	    // Pass through the boolean because the instance variable could change while we're waiting for
310	    // the runnable to be executed on the main thread.
311	    @Synthetic
312	    void notifyChangeOnUiThread(final boolean isConnected) {
313	      Util.postOnUiThread(() -> listener.onConnectivityChanged(isConnected));
314	    }
315	
316	    @SuppressWarnings("WeakerAccess")
317	    @Synthetic
318	    // Permissions are checked in the factory instead.
319	    @SuppressLint("MissingPermission")
320	    boolean isConnected() {
321	      NetworkInfo networkInfo;
322	      try {
323	        networkInfo = connectivityManager.get().getActiveNetworkInfo();
324	      } catch (RuntimeException e) {
325	        // #1405 shows that this throws a SecurityException.
326	        // b/70869360 shows that this throws NullPointerException on APIs 22, 23, and 24.
