328	        if (Log.isLoggable(TAG, Log.WARN)) {
329	          Log.w(TAG, "Failed to determine connectivity status when connectivity changed", e);
330	        }
331	        // Default to true;
332	        return true;
333	      }
334	      return networkInfo != null && networkInfo.isConnected();
335	    }
336	  }
