2	
3	import android.content.ContentResolver;
4	import android.content.Context;
5	import android.content.pm.PackageManager.NameNotFoundException;
6	import android.content.res.Resources;
7	import android.content.res.Resources.Theme;
8	import android.graphics.drawable.Drawable;
9	import android.net.Uri;
10	import android.text.TextUtils;
11	import androidx.annotation.DrawableRes;
12	import androidx.annotation.NonNull;
13	import androidx.annotation.Nullable;
14	import com.bumptech.glide.load.Option;
15	import com.bumptech.glide.load.Options;
16	import com.bumptech.glide.load.ResourceDecoder;
17	import com.bumptech.glide.load.engine.Resource;
18	import com.bumptech.glide.util.Preconditions;
19	import java.util.List;
20	
21	/**
22	 * Decodes {@link Drawable}s given resource {@link Uri}s.
23	 *
24	 * <p>This is typically used as a fallback for resource types that either aren't Bitmaps (see #350)
25	 * or for resource types that we can't obtain an {@link java.io.InputStream} for using a standard
26	 * {@link ContentResolver}, including some types of application icons and resources loaded from
27	 * other packages.
28	 */
29	public class ResourceDrawableDecoder implements ResourceDecoder<Uri, Drawable> {
30	
31	  /** Specifies a {@link Theme} which will be used to load the drawable. */
32	  public static final Option<Theme> THEME =
33	      Option.memory("com.bumptech.glide.load.resource.bitmap.Downsampler.Theme");
34	
35	  /**
36	   * The package name to provide {@link Resources#getIdentifier(String, String, String)} when trying
37	   * to find system resource ids.
38	   *
39	   * <p>As far as I can tell this is undocumented, but works.
40	   */
41	  private static final String ANDROID_PACKAGE_NAME = "android";
42	
43	  /**
44	   * {@link Resources#getIdentifier(String, String, String)} documents that it will return 0 and
45	   * that 0 is not a valid resouce id.
46	   */
47	  private static final int MISSING_RESOURCE_ID = 0;
48	
49	  // android.resource://<package_name>/<type>/<name>.
50	  private static final int NAME_URI_PATH_SEGMENTS = 2;
51	  private static final int TYPE_PATH_SEGMENT_INDEX = 0;
52	  private static final int NAME_PATH_SEGMENT_INDEX = 1;
53	  // android.resource://<package_name>/<resource_id>
54	  private static final int ID_PATH_SEGMENTS = 1;
55	  private static final int RESOURCE_ID_SEGMENT_INDEX = 0;
56	
57	  private final Context context;
58	
59	  public ResourceDrawableDecoder(Context context) {
60	    this.context = context.getApplicationContext();
61	  }
62	
63	  @Override
64	  public boolean handles(@NonNull Uri source, @NonNull Options options) {
65	    String scheme = source.getScheme();
66	    return scheme != null && scheme.equals(ContentResolver.SCHEME_ANDROID_RESOURCE);
67	  }
68	
69	  @Nullable
70	  @Override
71	  public Resource<Drawable> decode(
72	      @NonNull Uri source, int width, int height, @NonNull Options options) {
73	    String packageName = source.getAuthority();
74	    if (TextUtils.isEmpty(packageName)) {
75	      throw new IllegalStateException("Package name for " + source + " is null or empty");
76	    }
77	    Context targetContext = findContextForPackage(source, packageName);
78	    @DrawableRes int resId = findResourceIdFromUri(targetContext, source);
79	    // Only use the provided theme if we're loading resources from our package. We can't get themes
80	    // from other packages and we don't want to use a theme from our package when loading another
81	    // package's resources.
82	    Theme theme =
83	        Preconditions.checkNotNull(packageName).equals(context.getPackageName())
84	            ? options.get(THEME)
85	            : null;
86	    Drawable drawable =
87	        theme == null
88	            ? DrawableDecoderCompat.getDrawable(context, targetContext, resId)
89	            : DrawableDecoderCompat.getDrawable(context, resId, theme);
90	    return NonOwnedDrawableResource.newInstance(drawable);
91	  }
92	
93	  @NonNull
94	  private Context findContextForPackage(Uri source, @NonNull String packageName) {
95	    // Fast path
96	    if (packageName.equals(context.getPackageName())) {
97	      return context;
98	    }
99	
100	    try {
101	      return context.createPackageContext(packageName, /* flags= */ 0);
102	    } catch (NameNotFoundException e) {
103	      // The parent APK holds the correct context if the resource is located in a split
104	      if (packageName.contains(context.getPackageName())) {
105	        return context;
106	      }
107	
108	      throw new IllegalArgumentException(
109	          "Failed to obtain context or unrecognized Uri format for: " + source, e);
110	    }
111	  }
112	
113	  @DrawableRes
114	  private int findResourceIdFromUri(Context context, Uri source) {
115	    List<String> segments = source.getPathSegments();
116	    if (segments.size() == NAME_URI_PATH_SEGMENTS) {
117	      return findResourceIdFromTypeAndNameResourceUri(context, source);
118	    }
119	    if (segments.size() == ID_PATH_SEGMENTS) {
120	      return findResourceIdFromResourceIdUri(source);
121	    }
122	    throw new IllegalArgumentException("Unrecognized Uri format: " + source);
123	  }
124	
125	  // android.resource://com.android.camera2/mipmap/logo_camera_color
126	  @DrawableRes
127	  private int findResourceIdFromTypeAndNameResourceUri(Context context, Uri source) {
128	    List<String> segments = source.getPathSegments();
129	    String packageName = source.getAuthority();
130	    String typeName = segments.get(TYPE_PATH_SEGMENT_INDEX);
131	    String resourceName = segments.get(NAME_PATH_SEGMENT_INDEX);
132	    int result = context.getResources().getIdentifier(resourceName, typeName, packageName);
133	    if (result == MISSING_RESOURCE_ID) {
134	      result = Resources.getSystem().getIdentifier(resourceName, typeName, ANDROID_PACKAGE_NAME);
135	    }
136	    if (result == MISSING_RESOURCE_ID) {
137	      throw new IllegalArgumentException("Failed to find resource id for: " + source);
138	    }
139	    return result;
140	  }
141	
142	  // android.resource://com.android.camera2/123456
143	  @DrawableRes
144	  private int findResourceIdFromResourceIdUri(Uri source) {
145	    List<String> segments = source.getPathSegments();
146	    try {
147	      return Integer.parseInt(segments.get(RESOURCE_ID_SEGMENT_INDEX));
148	    } catch (NumberFormatException e) {
149	      throw new IllegalArgumentException("Unrecognized Uri format: " + source, e);
150	    }
151	  }
152	}
