9	
10	  /** Creates a new {@link StateVerifier} instance. */
11	  @NonNull
12	  public static StateVerifier newInstance() {
13	    return DEBUG ? new DebugStateVerifier() : new DefaultStateVerifier();
14	  }
15	
16	  private StateVerifier() {}
17	
18	  /**
19	   * Throws an exception if we believe our object is recycled and inactive (i.e. is currently in an
20	   * object pool).
21	   */
22	  public abstract void throwIfRecycled();
23	
24	  /** Sets whether or not our object is recycled. */
25	  abstract void setRecycled(boolean isRecycled);
26	
27	  private static class DefaultStateVerifier extends StateVerifier {
28	    private volatile boolean isReleased;
29	
30	    @Synthetic
31	    DefaultStateVerifier() {}
32	
33	    @Override
34	    public void throwIfRecycled() {
35	      if (isReleased) {
36	        throw new IllegalStateException("Already released");
37	      }
38	    }
39	
40	    @Override
41	    public void setRecycled(boolean isRecycled) {
42	      this.isReleased = isRecycled;
43	    }
44	  }
