56	        throw new IllegalStateException("Already released", recycledAtStackTraceException);
57	      }
58	    }
59	
60	    @Override
61	    void setRecycled(boolean isRecycled) {
62	      recycledAtStackTraceException = isRecycled ? new RuntimeException("Released") : null;
