11	    T get();
12	  }
13	
14	  private GlideSuppliers() {}
15	
16	  public static <T> GlideSupplier<T> memorize(final GlideSupplier<T> supplier) {
17	    return new GlideSupplier<T>() {
18	      private volatile T instance;
