15	@SuppressWarnings({"unused", "WeakerAccess"})
16	public final class ExternalPreferredCacheDiskCacheFactory extends DiskLruCacheFactory {
17	
18	  public ExternalPreferredCacheDiskCacheFactory(Context context) {
19	    this(
20	        context,
21	        DiskCache.Factory.DEFAULT_DISK_CACHE_DIR,
22	        DiskCache.Factory.DEFAULT_DISK_CACHE_SIZE);
23	  }
24	
25	  public ExternalPreferredCacheDiskCacheFactory(Context context, long diskCacheSize) {
26	    this(context, DiskCache.Factory.DEFAULT_DISK_CACHE_DIR, diskCacheSize);
27	  }
