29	  public ExternalPreferredCacheDiskCacheFactory(
30	      final Context context, final String diskCacheName, final long diskCacheSize) {
31	    super(
32	        new CacheDirectoryGetter() {
33	          @Nullable
34	          private File getInternalCacheDirectory() {
35	            File cacheDirectory = context.getCacheDir();
36	            if (cacheDirectory == null) {
37	              return null;
38	            }
39	            if (diskCacheName != null) {
40	              return new File(cacheDirectory, diskCacheName);
41	            }
42	            return cacheDirectory;
43	          }
44	
45	          @Override
46	          public File getCacheDirectory() {
47	            File internalCacheDirectory = getInternalCacheDirectory();
48	
49	            // Already used internal cache, so keep using that one,
50	            // thus avoiding using both external and internal with transient errors.
51	            if (internalCacheDirectory != null && internalCacheDirectory.exists()) {
52	              return internalCacheDirectory;
53	            }
54	
55	            File cacheDirectory = context.getExternalCacheDir();
56	
57	            // Shared storage is not available.
58	            if (cacheDirectory == null || !cacheDirectory.canWrite()) {
59	              return internalCacheDirectory;
60	            }
61	            if (diskCacheName != null) {
62	              return new File(cacheDirectory, diskCacheName);
63	            }
64	            return cacheDirectory;
65	          }
66	        },
