import os, re

def find_else_after_return(path):
    results = []
    try:
        src = open(path).read()
        lines = src.split('\n')
        for i, line in enumerate(lines):
            if re.search(r'^\s*} else \{', line) or re.search(r'^\s*} else if\b', line):
                # look backward for a preceding return/throw
                for j in range(i-1, max(i-5, -1), -1):
                    s = lines[j].strip()
                    if s.startswith('return ') or s == 'return;' or s.startswith('throw '):
                        results.append((i+1, line.strip()))
                        break
                    elif s and not s.startswith('//') and not s.startswith('*'):
                        break
    except:
        pass
    return results

dirs = ['library/src/main/java', 'annotation/compiler/src/main/java', 'integration']
for d in dirs:
    for root, _, files in os.walk(d):
        for f in files:
            if f.endswith('.java') and 'Test' not in f and 'test' not in root:
                path = os.path.join(root, f)
                hits = find_else_after_return(path)
                for lineno, txt in hits:
                    print(f'{path}:{lineno}: {txt}')
