import os, re

# Look for assign-once patterns: variable = something; ... return variable; (or return x.method(variable))
# where variable is only assigned once (the initial assignment)
def find_assign_once(path):
    results = []
    try:
        src = open(path).read()
        lines = src.split('\n')
        for i, line in enumerate(lines):
            # Match patterns like: Type varName = null; followed later by if (cond) { varName = ... } return varName;
            m = re.match(r'\s+([\w<>\[\]?]+)\s+(\w+)\s+=\s+null;', line)
            if m:
                varname = m.group(2)
                # look ahead for single assignment then return
                assign_count = 0
                for j in range(i+1, min(i+40, len(lines))):
                    l = lines[j]
                    if re.search(r'\b' + varname + r'\s*=\s*', l) and not re.match(r'\s*//\s', l):
                        assign_count += 1
                    if re.match(r'\s*return\s+' + varname + r'\s*;', l):
                        if assign_count == 1:
                            results.append((i+1, line.strip()[:80]))
                        break
    except:
        pass
    return results

dirs = ['library/src/main/java', 'annotation/compiler/src/main/java', 'integration']
for d in dirs:
    for root, _, files in os.walk(d):
        for f in files:
            if f.endswith('.java') and 'Test' not in f and 'test' not in root:
                path = os.path.join(root, f)
                hits = find_assign_once(path)
                for lineno, txt in hits:
                    print(f'{path}:{lineno}: {txt}')
