41	  public synchronized <Model, Data> void prepend(
42	      @NonNull Class<Model> modelClass,
43	      @NonNull Class<Data> dataClass,
44	      @NonNull ModelLoaderFactory<? extends Model, ? extends Data> factory) {
45	    multiModelLoaderFactory.prepend(modelClass, dataClass, factory);
46	    cache.clear();
47	  }
48	
49	  public synchronized <Model, Data> void remove(
50	      @NonNull Class<Model> modelClass, @NonNull Class<Data> dataClass) {
51	    tearDown(multiModelLoaderFactory.remove(modelClass, dataClass));
52	    cache.clear();
53	  }
54	
55	  public synchronized <Model, Data> void replace(
56	      @NonNull Class<Model> modelClass,
57	      @NonNull Class<Data> dataClass,
58	      @NonNull ModelLoaderFactory<? extends Model, ? extends Data> factory) {
59	    tearDown(multiModelLoaderFactory.replace(modelClass, dataClass, factory));
60	    cache.clear();
61	  }
62	
63	  private <Model, Data> void tearDown(
64	      @NonNull List<ModelLoaderFactory<? extends Model, ? extends Data>> factories) {
65	    for (ModelLoaderFactory<? extends Model, ? extends Data> factory : factories) {
66	      factory.teardown();
67	    }
