72	  @SuppressWarnings("PMD.AvoidInstantiatingObjectsInLoops")
73	  @NonNull
74	  public <A> List<ModelLoader<A, ?>> getModelLoaders(@NonNull A model) {
75	    List<ModelLoader<A, ?>> modelLoaders = getModelLoadersForClass(getClass(model));
76	    if (modelLoaders.isEmpty()) {
77	      throw new NoModelLoaderAvailableException(model);
78	    }
79	    int size = modelLoaders.size();
80	    boolean isEmpty = true;
81	    List<ModelLoader<A, ?>> filteredLoaders = Collections.emptyList();
82	    //noinspection ForLoopReplaceableByForEach to improve perf
83	    for (int i = 0; i < size; i++) {
84	      ModelLoader<A, ?> loader = modelLoaders.get(i);
85	      if (loader.handles(model)) {
86	        if (isEmpty) {
87	          filteredLoaders = new ArrayList<>(size - i);
88	          isEmpty = false;
89	        }
90	        filteredLoaders.add(loader);
91	      }
92	    }
93	    if (filteredLoaders.isEmpty()) {
94	      throw new NoModelLoaderAvailableException(model, modelLoaders);
95	    }
96	    return filteredLoaders;
97	  }
98	
99	  public synchronized <Model, Data> ModelLoader<Model, Data> build(
100	      @NonNull Class<Model> modelClass, @NonNull Class<Data> dataClass) {
101	    return multiModelLoaderFactory.build(modelClass, dataClass);
102	  }
103	
104	  @NonNull
105	  public synchronized List<Class<?>> getDataClasses(@NonNull Class<?> modelClass) {
106	    return multiModelLoaderFactory.getDataClasses(modelClass);
107	  }
108	
109	  @NonNull
110	  private synchronized <A> List<ModelLoader<A, ?>> getModelLoadersForClass(
111	      @NonNull Class<A> modelClass) {
112	    List<ModelLoader<A, ?>> loaders = cache.get(modelClass);
113	    if (loaders == null) {
114	      loaders = Collections.unmodifiableList(multiModelLoaderFactory.build(modelClass));
115	      cache.put(modelClass, loaders);
116	    }
117	    return loaders;
118	  }
119	
120	  @NonNull
121	  @SuppressWarnings("unchecked")
122	  private static <A> Class<A> getClass(@NonNull A model) {
123	    return (Class<A>) model.getClass();
124	  }
125	
126	  private static class ModelLoaderCache {
127	    private final Map<Class<?>, Entry<?>> cachedModelLoaders = new HashMap<>();
128	
129	    @Synthetic
130	    ModelLoaderCache() {}
131	
132	    public void clear() {
133	      cachedModelLoaders.clear();
134	    }
135	
136	    public <Model> void put(Class<Model> modelClass, List<ModelLoader<Model, ?>> loaders) {
137	      Entry<?> previous = cachedModelLoaders.put(modelClass, new Entry<>(loaders));
138	      if (previous != null) {
139	        throw new IllegalStateException("Already cached loaders for model: " + modelClass);
140	      }
141	    }
142	
143	    @Nullable
144	    @SuppressWarnings("unchecked")
145	    public <Model> List<ModelLoader<Model, ?>> get(Class<Model> modelClass) {
146	      Entry<Model> entry = (Entry<Model>) cachedModelLoaders.get(modelClass);
147	      return entry == null ? null : entry.loaders;
148	    }
149	
150	    private static class Entry<Model> {
151	      @Synthetic final List<ModelLoader<Model, ?>> loaders;
152	
153	      public Entry(List<ModelLoader<Model, ?>> loaders) {
154	        this.loaders = loaders;
155	      }
156	    }
157	  }
