127	   */
128	  public ListPreloader(
129	      @NonNull RequestManager requestManager,
130	      @NonNull PreloadModelProvider<T> preloadModelProvider,
131	      @NonNull PreloadSizeProvider<T> preloadDimensionProvider,
132	      int maxPreload) {
133	    this.requestManager = requestManager;
134	    this.preloadModelProvider = preloadModelProvider;
135	    this.preloadDimensionProvider = preloadDimensionProvider;
136	    this.maxPreload = maxPreload;
137	    preloadTargetQueue = new PreloadTargetQueue(maxPreload + 1);
138	  }
139	
140	  @Override
141	  public void onScrollStateChanged(AbsListView absListView, int scrollState) {
142	    // Do nothing.
143	  }
144	
145	  @Override
146	  public void onScroll(
147	      AbsListView absListView, int firstVisible, int visibleCount, int totalCount) {
148	    if (totalItemCount == 0 && totalCount == 0) {
149	      return;
150	    }
151	    totalItemCount = totalCount;
152	    if (firstVisible > lastFirstVisible) {
153	      preload(firstVisible + visibleCount, true);
154	    } else if (firstVisible < lastFirstVisible) {
155	      preload(firstVisible, false);
156	    }
157	    lastFirstVisible = firstVisible;
158	  }
159	
160	  private void preload(int start, boolean increasing) {
161	    if (isIncreasing != increasing) {
162	      isIncreasing = increasing;
163	      cancelAll();
164	    }
165	    preload(start, start + (increasing ? maxPreload : -maxPreload));
166	  }
167	
168	  private void preload(int from, int to) {
169	    int start;
170	    int end;
171	    if (from < to) {
172	      start = Math.max(lastEnd, from);
173	      end = to;
174	    } else {
175	      start = to;
176	      end = Math.min(lastStart, from);
177	    }
178	    end = Math.min(totalItemCount, end);
179	    start = Math.min(totalItemCount, Math.max(0, start));
180	
181	    if (from < to) {
182	      // Increasing
183	      for (int i = start; i < end; i++) {
184	        preloadAdapterPosition(
185	            preloadModelProvider.getPreloadItems(i), /* position= */ i, /* isIncreasing= */ true);
186	      }
187	    } else {
188	      // Decreasing
189	      for (int i = end - 1; i >= start; i--) {
190	        preloadAdapterPosition(
191	            preloadModelProvider.getPreloadItems(i), /* position= */ i, /* isIncreasing= */ false);
192	      }
193	    }
194	
195	    lastStart = start;
196	    lastEnd = end;
197	  }
198	
199	  private void preloadAdapterPosition(List<T> items, int position, boolean isIncreasing) {
200	    final int numItems = items.size();
201	    if (isIncreasing) {
202	      for (int i = 0; i < numItems; ++i) {
203	        preloadItem(items.get(i), position, i);
204	      }
205	    } else {
206	      for (int i = numItems - 1; i >= 0; --i) {
207	        preloadItem(items.get(i), position, i);
208	      }
209	    }
210	  }
211	
212	  @SuppressWarnings("unchecked")
213	  private void preloadItem(@Nullable T item, int position, int perItemPosition) {
214	    if (item == null) {
215	      return;
216	    }
217	    int[] dimensions = preloadDimensionProvider.getPreloadSize(item, position, perItemPosition);
218	    if (dimensions == null) {
219	      return;
220	    }
221	    RequestBuilder<Object> preloadRequestBuilder =
222	        (RequestBuilder<Object>) preloadModelProvider.getPreloadRequestBuilder(item);
223	    if (preloadRequestBuilder == null) {
224	      return;
225	    }
226	
227	    preloadRequestBuilder.into(preloadTargetQueue.next(dimensions[0], dimensions[1]));
228	  }
229	
230	  private void cancelAll() {
231	    for (int i = 0; i < preloadTargetQueue.queue.size(); i++) {
232	      requestManager.clear(preloadTargetQueue.next(0, 0));
233	    }
234	  }
235	
236	  private static final class PreloadTargetQueue {
237	    @Synthetic final Queue<PreloadTarget> queue;
238	
239	    // The loop is short and the only point is to create the objects.
240	    @SuppressWarnings("PMD.AvoidInstantiatingObjectsInLoops")
241	    PreloadTargetQueue(int size) {
242	      queue = Util.createQueue(size);
243	
244	      for (int i = 0; i < size; i++) {
245	        queue.offer(new PreloadTarget());
246	      }
247	    }
248	
249	    public PreloadTarget next(int width, int height) {
250	      final PreloadTarget result = queue.poll();
251	      queue.offer(result);
252	      result.photoWidth = width;
253	      result.photoHeight = height;
254	      return result;
255	    }
256	  }
257	
258	  private static final class PreloadTarget implements Target<Object> {
259	    @Synthetic int photoHeight;
260	    @Synthetic int photoWidth;
261	    @Nullable private Request request;
262	
263	    @Synthetic
264	    PreloadTarget() {}
265	
266	    @Override
267	    public void onLoadStarted(@Nullable Drawable placeholder) {
268	      // Do nothing.
269	    }
270	
271	    @Override
272	    public void onLoadFailed(@Nullable Drawable errorDrawable) {
273	      // Do nothing.
274	    }
275	
276	    @Override
277	    public void onResourceReady(
278	        @NonNull Object resource, @Nullable Transition<? super Object> transition) {
279	      // Do nothing.
280	    }
281	
282	    @Override
283	    public void onLoadCleared(@Nullable Drawable placeholder) {
284	      // Do nothing.
285	    }
286	
287	    @Override
288	    public void getSize(@NonNull SizeReadyCallback cb) {
