295	    }
296	
297	    @Override
298	    public void setRequest(@Nullable Request request) {
299	      this.request = request;
300	    }
301	
302	    @Nullable
303	    @Override
304	    public Request getRequest() {
305	      return request;
306	    }
307	
308	    @Override
309	    public void onStart() {
310	      // Do nothing.
311	    }
312	
313	    @Override
314	    public void onStop() {
315	      // Do nothing.
316	    }
