3	import androidx.annotation.NonNull;
4	import java.io.FilterInputStream;
5	import java.io.IOException;
6	import java.io.InputStream;
7	
8	/**
9	 * Adds an exif segment with an orientation attribute to a wrapped {@link InputStream} containing
10	 * image data.
11	 *
12	 * <p>This class assumes that the wrapped stream contains an image format that can contain exif
13	 * information and performs no verification.
14	 */
15	public final class ExifOrientationStream extends FilterInputStream {
16	  /** Allow two bytes for the file format. */
17	  private static final int SEGMENT_START_POSITION = 2;
18	
19	  private static final byte[] EXIF_SEGMENT =
20	      new byte[] {
21	        /* segment start id. */
22	        (byte) 0xFF,
23	        /* segment type. */
24	        (byte) 0xE1,
25	        /* segmentLength. */
26	        0x00,
27	        (byte) 0x1C,
28	        /* exif identifier. */
29	        0x45,
30	        0x78,
31	        0x69,
32	        0x66,
33	        0x00,
34	        0x00,
35	        /* motorola byte order (big endian). */
36	        (byte) 0x4D,
37	        (byte) 0x4D,
38	        /* filler? */
39	        0x00,
40	        0x00,
41	        /* first id offset. */
42	        0x00,
43	        0x00,
44	        0x00,
45	        0x08,
46	        /* tagCount. */
47	        0x00,
48	        0x01,
49	        /* exif tag type. */
50	        0x01,
51	        0x12,
52	        /* 2 byte format. */
53	        0x00,
54	        0x02,
55	        /* component count. */
56	        0x00,
57	        0x00,
58	        0x00,
59	        0x01,
60	        /* 2 byte orientation value, the first byte of which is always 0. */
61	        0x00,
62	      };
63	  private static final int SEGMENT_LENGTH = EXIF_SEGMENT.length;
64	  private static final int ORIENTATION_POSITION = SEGMENT_LENGTH + SEGMENT_START_POSITION;
65	  private final byte orientation;
66	  private int position;
67	
68	  public ExifOrientationStream(InputStream in, int orientation) {
69	    super(in);
70	    if (orientation < -1 || orientation > 8) {
71	      throw new IllegalArgumentException("Cannot add invalid orientation: " + orientation);
72	    }
73	    this.orientation = (byte) orientation;
74	  }
75	
76	  @Override
77	  public boolean markSupported() {
78	    return false;
79	  }
80	
81	  // No need for synchronized since all we do is throw.
82	  @SuppressWarnings("UnsynchronizedOverridesSynchronized")
83	  @Override
84	  public void mark(int readLimit) {
85	    throw new UnsupportedOperationException();
86	  }
87	
88	  @Override
89	  public int read() throws IOException {
90	    final int result;
91	    if (position < SEGMENT_START_POSITION || position > ORIENTATION_POSITION) {
92	      result = super.read();
93	    } else if (position == ORIENTATION_POSITION) {
94	      result = orientation;
95	    } else {
96	      result = EXIF_SEGMENT[position - SEGMENT_START_POSITION] & 0xFF;
97	    }
98	    if (result != -1) {
99	      position++;
100	    }
101	    return result;
102	  }
103	
104	  @Override
105	  public int read(@NonNull byte[] buffer, int byteOffset, int byteCount) throws IOException {
106	    int read;
107	    if (position > ORIENTATION_POSITION) {
108	      read = super.read(buffer, byteOffset, byteCount);
109	    } else if (position == ORIENTATION_POSITION) {
110	      buffer[byteOffset] = orientation;
111	      read = 1;
112	    } else if (position < SEGMENT_START_POSITION) {
113	      read = super.read(buffer, byteOffset, SEGMENT_START_POSITION - position);
114	    } else {
115	      read = Math.min(ORIENTATION_POSITION - position, byteCount);
116	      System.arraycopy(EXIF_SEGMENT, position - SEGMENT_START_POSITION, buffer, byteOffset, read);
117	    }
118	    if (read > 0) {
119	      position += read;
120	    }
121	    return read;
122	  }
123	
124	  @Override
125	  public long skip(long byteCount) throws IOException {
126	    long skipped = super.skip(byteCount);
127	    if (skipped > 0) {
128	      // See https://errorprone.info/bugpattern/NarrowingCompoundAssignment.
129	      position = (int) (position + skipped);
130	    }
131	    return skipped;
132	  }
133	
134	  // No need for synchronized since all we do is throw.
135	  @SuppressWarnings("UnsynchronizedOverridesSynchronized")
136	  @Override
137	  public void reset() throws IOException {
138	    throw new UnsupportedOperationException();
139	  }
140	}
