27	/**
28	 * Wraps an existing {@link InputStream} and <em>buffers</em> the input. Expensive interaction with
29	 * the underlying input stream is minimized, since most (smaller) requests can be satisfied by
30	 * accessing the buffer alone. The drawback is that some extra space is required to hold the buffer
31	 * and that copying takes place when filling that buffer, but this is usually outweighed by the
32	 * performance benefits.
33	 *
34	 * <p>A typical application pattern for the class looks like this:
35	 *
36	 * <pre>
37	 * BufferedInputStream buf = new BufferedInputStream(new FileInputStream("file.java"));
38	 * </pre>
39	 */
40	public class RecyclableBufferedInputStream extends FilterInputStream {
41	  /** The buffer containing the current bytes read from the target InputStream. */
42	  private volatile byte[] buf;
43	
44	  /** The total number of bytes inside the byte array {@code buf}. */
45	  private int count;
46	
47	  /** The current limit, which when passed, invalidates the current mark. */
48	  private int marklimit;
49	
50	  /**
51	   * The currently marked position. -1 indicates no mark has been put or the mark has been
52	   * invalidated.
53	   */
54	  private int markpos = -1;
55	
56	  /** The current position within the byte array {@code buf}. */
57	  private int pos;
58	
59	  private final ArrayPool byteArrayPool;
