61	  public RecyclableBufferedInputStream(@NonNull InputStream in, @NonNull ArrayPool byteArrayPool) {
62	    this(in, byteArrayPool, ArrayPool.STANDARD_BUFFER_SIZE_BYTES);
63	  }
64	
65	  @VisibleForTesting
66	  RecyclableBufferedInputStream(
67	      @NonNull InputStream in, @NonNull ArrayPool byteArrayPool, int bufferSize) {
68	    super(in);
69	    this.byteArrayPool = byteArrayPool;
70	    buf = byteArrayPool.get(bufferSize, byte[].class);
