80	   */
81	  @Override
82	  public synchronized int available() throws IOException {
83	    // in could be invalidated by close().
84	    InputStream localIn = in;
85	    if (buf == null || localIn == null) {
86	      throw streamClosed();
87	    }
88	    return count - pos + localIn.available();
89	  }
