103	  @SuppressWarnings("WeakerAccess")
104	  public synchronized void fixMarkLimit() {
105	    marklimit = buf.length;
106	  }
107	
108	  public synchronized void release() {
109	    if (buf != null) {
110	      byteArrayPool.put(buf);
111	      buf = null;
112	    }
113	  }
