117	   * released.
118	   *
119	   * @throws IOException if an error occurs while closing this stream.
120	   */
121	  @Override
122	  public void close() throws IOException {
123	    if (buf != null) {
124	      byteArrayPool.put(buf);
125	      buf = null;
126	    }
127	    InputStream localIn = in;
128	    in = null;
129	    if (localIn != null) {
130	      localIn.close();
131	    }
132	  }
