134	  private int fillbuf(InputStream localIn, byte[] localBuf) throws IOException {
135	    if (markpos == -1 || pos - markpos >= marklimit) {
136	      // Mark position not put or exceeded readlimit
137	      int result = localIn.read(localBuf);
138	      if (result > 0) {
139	        markpos = -1;
140	        pos = 0;
141	        count = result;
142	      }
143	      return result;
144	    }
145	    // Added count == localBuf.length so that we do not immediately double the buffer size before
146	    // reading any data
147	    // when marklimit > localBuf.length. Instead, we will double the buffer size only after
148	    // reading the initial
149	    // localBuf worth of data without finding what we're looking for in the stream. This allows
150	    // us to put a
151	    // relatively small initial buffer size and a large marklimit for safety without causing an
152	    // allocation each time
153	    // read is called.
154	    if (markpos == 0 && marklimit > localBuf.length && count == localBuf.length) {
155	      // Increase buffer size to accommodate the readlimit
156	      int newLength = localBuf.length * 2;
157	      if (newLength > marklimit) {
158	        newLength = marklimit;
159	      }
160	      byte[] newbuf = byteArrayPool.get(newLength, byte[].class);
161	      System.arraycopy(localBuf, 0, newbuf, 0, localBuf.length);
162	      byte[] oldbuf = localBuf;
163	      // Reassign buf, which will invalidate any local references
164	      // FIXME: what if buf was null?
165	      localBuf = buf = newbuf;
166	      byteArrayPool.put(oldbuf);
167	    } else if (markpos > 0) {
168	      System.arraycopy(localBuf, markpos, localBuf, 0, localBuf.length - markpos);
169	    }
170	    // Set the new position and mark position
171	    pos -= markpos;
172	    count = markpos = 0;
173	    int bytesread = localIn.read(localBuf, pos, localBuf.length - pos);
174	    count = bytesread <= 0 ? pos : pos + bytesread;
175	    return bytesread;
176	  }
