183	   *
184	   * @param readlimit the number of bytes that can be read before the mark is invalidated.
185	   * @see #reset()
186	   */
187	  @Override
188	  public synchronized void mark(int readlimit) {
189	    // This is stupid, but BitmapFactory.decodeStream calls mark(1024)
190	    // which is too small for a substantial portion of images. This
191	    // change (using Math.max) ensures that we don't overwrite readlimit
192	    // with a smaller value
193	    marklimit = Math.max(marklimit, readlimit);
194	    markpos = pos;
