220	  public synchronized int read() throws IOException {
221	    // Use local refs since buf and in may be invalidated by an
222	    // unsynchronized close()
223	    byte[] localBuf = buf;
224	    InputStream localIn = in;
225	    if (localBuf == null || localIn == null) {
226	      throw streamClosed();
227	    }
228	
229	    // Are there buffered bytes available?
230	    if (pos >= count && fillbuf(localIn, localBuf) == -1) {
231	      // no, fill buffer
232	      return -1;
233	    }
234	    // localBuf may have been invalidated by fillbuf
235	    if (localBuf != buf) {
236	      localBuf = buf;
237	      if (localBuf == null) {
238	        throw streamClosed();
239	      }
240	    }
