16	 * Bitmap} and can apply it to every frame of any {@link
17	 * com.bumptech.glide.load.resource.gif.GifDrawable}.
18	 */
19	public class GifDrawableTransformation implements Transformation<GifDrawable> {
20	  private final Transformation<Bitmap> wrapped;
21	
22	  public GifDrawableTransformation(Transformation<Bitmap> wrapped) {
23	    this.wrapped = Preconditions.checkNotNull(wrapped);
24	  }
25	
26	  @NonNull
27	  @Override
28	  public Resource<GifDrawable> transform(
29	      @NonNull Context context,
30	      @NonNull Resource<GifDrawable> resource,
31	      int outWidth,
32	      int outHeight) {
33	    GifDrawable drawable = resource.get();
34	
35	    // The drawable needs to be initialized with the correct width and height in order for a view
36	    // displaying it to end up with the right dimensions. Since our transformations may arbitrarily
37	    // modify the dimensions of our GIF, here we create a stand in for a frame and pass it to the
38	    // transformation to see what the final transformed dimensions will be so that our drawable can
39	    // report the correct intrinsic width and height.
40	    BitmapPool bitmapPool = Glide.get(context).getBitmapPool();
