42	    Resource<Bitmap> bitmapResource = new BitmapResource(firstFrame, bitmapPool);
43	    Resource<Bitmap> transformed = wrapped.transform(context, bitmapResource, outWidth, outHeight);
44	    if (!bitmapResource.equals(transformed)) {
45	      bitmapResource.recycle();
46	    }
47	    Bitmap transformedFrame = transformed.get();
48	
49	    drawable.setFrameTransformation(wrapped, transformedFrame);
