19	final class LifecycleRequestManagerRetriever {
20	  @Synthetic final Map<Lifecycle, RequestManager> lifecycleToRequestManager = new HashMap<>();
21	  @NonNull private final RequestManagerFactory factory;
22	
23	  LifecycleRequestManagerRetriever(@NonNull RequestManagerFactory factory) {
24	    this.factory = factory;
25	  }
26	
27	  RequestManager getOnly(Lifecycle lifecycle) {
28	    Util.assertMainThread();
29	    return lifecycleToRequestManager.get(lifecycle);
30	  }
31	
32	  RequestManager getOrCreate(
33	      Context context,
34	      Glide glide,
35	      final Lifecycle lifecycle,
36	      FragmentManager childFragmentManager,
37	      boolean isParentVisible) {
38	    Util.assertMainThread();
39	    RequestManager result = getOnly(lifecycle);
40	    if (result == null) {
41	      LifecycleLifecycle glideLifecycle = new LifecycleLifecycle(lifecycle);
42	      result =
43	          factory.build(
44	              glide,
45	              glideLifecycle,
46	              new SupportRequestManagerTreeNode(childFragmentManager),
47	              context);
48	      lifecycleToRequestManager.put(lifecycle, result);
49	      glideLifecycle.addListener(
50	          new LifecycleListener() {
51	            @Override
52	            public void onStart() {}
53	
54	            @Override
55	            public void onStop() {}
56	
57	            @Override
58	            public void onDestroy() {
59	              lifecycleToRequestManager.remove(lifecycle);
60	            }
61	          });
62	      // This is a bit of hack, we're going to start the RequestManager, but not the
63	      // corresponding Lifecycle. It's safe to start the RequestManager, but starting the
64	      // Lifecycle might trigger memory leaks. See b/154405040
65	      if (isParentVisible) {
66	        result.onStart();
67	      }
68	    }
69	    return result;
70	  }
71	
72	  private final class SupportRequestManagerTreeNode implements RequestManagerTreeNode {
73	    private final FragmentManager childFragmentManager;
74	
75	    SupportRequestManagerTreeNode(FragmentManager childFragmentManager) {
76	      this.childFragmentManager = childFragmentManager;
77	    }
78	
79	    @NonNull
80	    @Override
81	    public Set<RequestManager> getDescendants() {
82	      Set<RequestManager> result = new HashSet<>();
83	      getChildFragmentsRecursive(childFragmentManager, result);
84	      return result;
85	    }
86	
87	    private void getChildFragmentsRecursive(
88	        FragmentManager fragmentManager, Set<RequestManager> requestManagers) {
89	      List<Fragment> children = fragmentManager.getFragments();
90	      for (int i = 0, size = children.size(); i < size; i++) {
91	        Fragment child = children.get(i);
92	        getChildFragmentsRecursive(child.getChildFragmentManager(), requestManagers);
93	        RequestManager fromChild = getOnly(child.getLifecycle());
94	        if (fromChild != null) {
95	          requestManagers.add(fromChild);
96	        }
97	      }
98	    }
99	  }
100	}
