1	package com.bumptech.glide.util;
2	
3	import androidx.annotation.NonNull;
4	import androidx.annotation.Nullable;
5	import java.util.Iterator;
6	import java.util.LinkedHashMap;
7	import java.util.Map;
8	
9	/**
10	 * A general purpose size limited cache that evicts items using an LRU algorithm. By default every
11	 * item is assumed to have a size of one. Subclasses can override {@link #getSize(Object)}} to
12	 * change the size on a per item basis.
13	 *
14	 * @param <T> The type of the keys.
15	 * @param <Y> The type of the values.
16	 */
17	public class LruCache<T, Y> {
18	  private final Map<T, Entry<Y>> cache = new LinkedHashMap<>(100, 0.75f, true);
19	  private final long initialMaxSize;
20	  private long maxSize;
21	  private long currentSize;
22	
23	  /**
24	   * Constructor for LruCache.
25	   *
26	   * @param size The maximum size of the cache, the units must match the units used in {@link
27	   *     #getSize(Object)}.
28	   */
29	  public LruCache(long size) {
30	    this.initialMaxSize = size;
31	    this.maxSize = size;
32	  }
33	
34	  /**
35	   * Sets a size multiplier that will be applied to the size provided in the constructor to put the
36	   * new size of the cache. If the new size is less than the current size, entries will be evicted
37	   * until the current size is less than or equal to the new size.
38	   *
39	   * @param multiplier The multiplier to apply.
40	   */
41	  public synchronized void setSizeMultiplier(float multiplier) {
42	    if (multiplier < 0) {
43	      throw new IllegalArgumentException("Multiplier must be >= 0");
44	    }
45	    maxSize = Math.round(initialMaxSize * multiplier);
46	    evict();
47	  }
48	
49	  /**
50	   * Returns the size of a given item, defaulting to one. The units must match those used in the
51	   * size passed in to the constructor. Subclasses can override this method to return sizes in
52	   * various units, usually bytes.
53	   *
54	   * @param item The item to get the size of.
55	   */
56	  protected int getSize(@Nullable Y item) {
57	    return 1;
58	  }
59	
60	  /** Returns the number of entries stored in cache. */
61	  protected synchronized int getCount() {
62	    return cache.size();
63	  }
64	
65	  /**
66	   * A callback called whenever an item is evicted from the cache. Subclasses can override.
67	   *
68	   * @param key The key of the evicted item.
69	   * @param item The evicted item.
70	   */
71	  protected void onItemEvicted(@NonNull T key, @Nullable Y item) {
72	    // optional override
73	  }
74	
75	  /** Returns the current maximum size of the cache in bytes. */
76	  public synchronized long getMaxSize() {
77	    return maxSize;
78	  }
79	
80	  /** Returns the sum of the sizes of all items in the cache. */
81	  public synchronized long getCurrentSize() {
82	    return currentSize;
83	  }
84	
85	  /**
86	   * Returns true if there is a value for the given key in the cache.
87	   *
88	   * @param key The key to check.
89	   */
90	  public synchronized boolean contains(@NonNull T key) {
91	    return cache.containsKey(key);
92	  }
93	
94	  /**
95	   * Returns the item in the cache for the given key or null if no such item exists.
96	   *
97	   * @param key The key to check.
98	   */
99	  @Nullable
100	  public synchronized Y get(@NonNull T key) {
101	    Entry<Y> entry = cache.get(key);
102	    return entry != null ? entry.value : null;
103	  }
104	
105	  /**
106	   * Adds the given item to the cache with the given key and returns any previous entry for the
107	   * given key that may have already been in the cache.
108	   *
109	   * <p>If the size of the item is larger than the total cache size, the item will not be added to
110	   * the cache and instead {@link #onItemEvicted(Object, Object)} will be called synchronously with
111	   * the given key and item.
112	   *
113	   * <p>The size of the item is determined by the {@link #getSize(Object)} method. To avoid errors
114	   * where {@link #getSize(Object)} returns different values for the same object when called at
115	   * different times, the size value is acquired in {@code put} and retained until the item is
116	   * evicted, replaced or removed.
117	   *
118	   * <p>If {@code item} is null the behavior here is a little odd. For the most part it's similar to
119	   * simply calling {@link #remove(Object)} with the given key. The difference is that calling this
120	   * method with a null {@code item} will result in an entry remaining in the cache with a null
121	   * value and 0 size. The only real consequence is that at some point {@link #onItemEvicted(Object,
122	   * Object)} may be called with the given {@code key} and a null value. Ideally we'd make calling
123	   * this method with a null {@code item} identical to {@link #remove(Object)} but we're preserving
124	   * this odd behavior to match older versions :(.
125	   *
126	   * @param key The key to add the item at.
127	   * @param item The item to add.
128	   */
129	  @Nullable
130	  public synchronized Y put(@NonNull T key, @Nullable Y item) {
131	    final int itemSize = getSize(item);
132	    if (itemSize >= maxSize) {
133	      onItemEvicted(key, item);
134	      return null;
135	    }
136	
137	    if (item != null) {
138	      currentSize += itemSize;
139	    }
140	    @Nullable Entry<Y> old = cache.put(key, item == null ? null : new Entry<>(item, itemSize));
141	    if (old != null) {
142	      currentSize -= old.size;
143	
144	      if (!old.value.equals(item)) {
145	        onItemEvicted(key, old.value);
146	      }
147	    }
148	    evict();
149	
150	    return old != null ? old.value : null;
151	  }
152	
153	  /**
154	   * Removes the item at the given key and returns the removed item if present, and null otherwise.
155	   *
156	   * @param key The key to remove the item at.
157	   */
158	  @Nullable
159	  public synchronized Y remove(@NonNull T key) {
160	    Entry<Y> entry = cache.remove(key);
161	    if (entry == null) {
162	      return null;
163	    }
164	    currentSize -= entry.size;
165	    return entry.value;
166	  }
167	
168	  /** Clears all items in the cache. */
169	  public void clearMemory() {
170	    trimToSize(0);
171	  }
172	
173	  /**
174	   * Removes the least recently used items from the cache until the current size is less than the
175	   * given size.
176	   *
177	   * @param size The size the cache should be less than.
178	   */
179	  protected synchronized void trimToSize(long size) {
180	    Map.Entry<T, Entry<Y>> last;
181	    Iterator<Map.Entry<T, Entry<Y>>> cacheIterator;
182	    while (currentSize > size) {
183	      cacheIterator = cache.entrySet().iterator();
184	      last = cacheIterator.next();
185	      final Entry<Y> toRemove = last.getValue();
186	      currentSize -= toRemove.size;
187	      final T key = last.getKey();
188	      cacheIterator.remove();
189	      onItemEvicted(key, toRemove.value);
190	    }
191	  }
192	
193	  private void evict() {
194	    trimToSize(maxSize);
195	  }
196	
197	  @Synthetic
198	  static final class Entry<Y> {
199	    final Y value;
200	    final int size;
201	
202	    @Synthetic
203	    Entry(Y value, int size) {
204	      this.value = value;
205	      this.size = size;
206	    }
207	  }
208	}
