2	
3	/** Similar to {@link com.google.common.base.Suppliers}, but named to reduce import confusion. */
4	public final class GlideSuppliers {
5	  /**
6	   * Produces a non-null instance of {@code T}.
7	   *
8	   * @param <T> The data type
9	   */
10	  public interface GlideSupplier<T> {
11	    T get();
12	  }
13	
14	  private GlideSuppliers() {}
15	
16	  public static <T> GlideSupplier<T> memorize(final GlideSupplier<T> supplier) {
17	    return new GlideSupplier<T>() {
18	      private volatile T instance;
19	
20	      @Override
21	      public T get() {
22	        if (instance == null) {
23	          synchronized (this) {
24	            if (instance == null) {
25	              instance = Preconditions.checkNotNull(supplier.get());
26	            }
27	          }
28	        }
29	        return instance;
30	      }
31	    };
32	  }
33	}
