22	   *     {@link android.provider.MediaStore.Images.ImageColumns#MIME_TYPE} or {@link
23	   *     android.provider.MediaStore.Video.VideoColumns#MIME_TYPE}.
24	   * @param dateModified The date modified time of the media store media. Ok to default to 0. See
25	   *     {@link android.provider.MediaStore.Images.ImageColumns#DATE_MODIFIED} or {@link
26	   *     android.provider.MediaStore.Video.VideoColumns#DATE_MODIFIED}.
27	   * @param orientation The orientation of the media store media. Ok to default to 0. See {@link
28	   *     android.provider.MediaStore.Images.ImageColumns#ORIENTATION}.
29	   */
30	  public MediaStoreSignature(@Nullable String mimeType, long dateModified, int orientation) {
31	    this.mimeType = mimeType == null ? "" : mimeType;
32	    this.dateModified = dateModified;
33	    this.orientation = orientation;
34	  }
35	
36	  @SuppressWarnings({"PMD.SimplifyBooleanReturns", "RedundantIfStatement"})
37	  @Override
38	  public boolean equals(Object o) {
39	    if (this == o) {
40	      return true;
41	    }
42	    if (o == null || getClass() != o.getClass()) {
43	      return false;
44	    }
45	
46	    MediaStoreSignature that = (MediaStoreSignature) o;
47	
48	    if (dateModified != that.dateModified) {
49	      return false;
50	    }
51	    if (orientation != that.orientation) {
52	      return false;
53	    }
54	    if (!mimeType.equals(that.mimeType)) {
55	      return false;
56	    }
57	    return true;
58	  }
